INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:complement','complement','v','مکمل، تکمیل کردن','/ˈkɒmpləment/ · 1)add to 2)supplement','Fruit would be a good complement for this meal.','[["Fruit would be a good complement for this meal.","میوه مکمل خوبی برای این وعده غذایی خواهد بود."],["These were complemented by new fast-food restaurants where travelers could eat a quick meal.","رستوران‌های فست‌فود جدید، که مسافران می‌توانستند در آن‌ها غذایی سریع بخورند، مکمل این‌ها شدند."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:comprise','comprise','v','شامل بودن، در بر داشتن','/kəmˈpraɪz/ · consist of, make up, form','The team comprises ten scientists.','[["The team comprises ten scientists.","این تیم شامل ده دانشمند است."],["The house comprises three bedrooms and a kitchen.","خانه شامل سه اتاق خواب و یک آشپزخانه است."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:compulsory','compulsory','adj','اجباری، ضروری','/kəmˈpʌlsəri/ · required, mandatory','Attendance at lectures is compulsory.','[["Attendance at lectures is compulsory.","حضور در جلسات سخنرانی الزامی است."],["Primary education is compulsory in most countries.","آموزش ابتدایی در اکثر کشورها اجباری است."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:concede','concede','v','قبول کردن، تصدیق کردن','/kənˈsiːd/ · accept','That goalkeeper hasn''t conceded a goal in the last 10 matches.','[["That goalkeeper hasn''t conceded a goal in the last 10 matches.","این دروازه‌بان در 10 بازی اخیر گلی دریافت نکرده است."],["England’s goalkeeper was criticized for the amount of goals he conceded.","دروازه‌بان تیم ملی انگلیس به خاطر تعداد گل‌های خورده‌اش مورد انتقاد قرار گرفت."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:concise','concise','adj','ساده، مختصر','/kənˈsaɪs/ · simple, brief, short','Keep your answer concise.','[["Keep your answer concise.","پاسخ خود را مختصر نگه دارید."],["Please keep your answers clear and concise.","لطفا پاسخ‌های خود را واضح و مختصر بنویسید."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:conclusive','conclusive','adj','قطعی، نهایی','/kənˈkluːsɪv/ · final, ultimate','There is no conclusive evidence that the drug works.','[["There is no conclusive evidence that the drug works.","هیچ مدرک قطعی مبنی بر اثربخشی دارو وجود ندارد."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:conserve','conserve','v','نگه داری، از صدمه حفط کردن','/kənˈsɜːv/ · save','We should turn off the lights to conserve energy.','[["We should turn off the lights to conserve energy.","برای صرفه‌جویی در مصرف انرژی، باید چراغ‌ها را خاموش کنیم."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:conspicuous','conspicuous','adj','انگشت نما، قابل توجه','/kənˈspɪkjuəs/ · notable','Marcus was once again conspicuous by his absence.','[["Marcus was once again conspicuous by his absence.","غیبت مارکوس بار دیگر جلب توجه می‌کرد."],["Bees have conspicuous colors to deter their enemies.","زنبورها برای ترساندن دشمنان خود رنگ‌های چشمگیری دارند."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:constellation','constellation','n','مجموعه، ترکیب','/ˌkɒnstəˈleɪʃən/ · collection, combination','He knows all the constellations.','[["He knows all the constellations.","او تمام صورت‌های فلکی را می‌شناسد."],["What constellations do you know?","چه صورت‌های فلکی را می‌شناسید؟"]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:contemplate','contemplate','v','در نظر داشتن','/ˈkɑːn.təm.pleɪt/ · consider','Rodrigo contemplated capturing the centipede and releasing it outside.','[["Rodrigo contemplated capturing the centipede and releasing it outside.","رودریگو به این فکر کرد که هزارپا را بگیرد و بیرون رها کند."],["He was contemplating the water of the pond.","داشت به آب حوض نگاه می‌کرد."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:contend','contend','v','رقابت کردن، ادعا کردن','/kənˈtend/ · 1) to compete against someone in order to gain something 2)to argue or state that something is true','Scientists contend that climate change is reversible.','[["Scientists contend that climate change is reversible.","دانشمندان معتقدند که تغییرات آب و هوایی برگشت پذیر است."],["The scientist contends that the theory is flawed.","این دانشمند ادعا می‌کند که این نظریه ایراد دارد."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:contention','contention','n','ادعا، مشاجره','/kənˈtenʃən/ · 1) claim 2) argument and disagreement between people','Her main contention is that the plan will cost too much.','[["Her main contention is that the plan will cost too much.","ادعای اصلی او این است که این طرح هزینه زیادی خواهد داشت."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:contentious','contentious','adj','ستیزجوی، دعوایی، اهل جر و بحث، ستیزگرای','/kənˈten.ʃəs/ · disputed','The debate was very contentious and didn''t result in any fruitful conclusions.','[["The debate was very contentious and didn''t result in any fruitful conclusions.","بحث بسیار جنجالی بود و به هیچ نتیجه‌ی مثبتی منجر نشد."],["The issue turned out to be very contentious.","موضوع خیلی جنجالی شد."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:continual','continual','adj','پی در پی، مکرر، پیوسته، همواره','/kənˈtɪn.ju.əl/ · constant, ceaseless','You continually make me feel unimportant.','[["You continually make me feel unimportant.","تو مدام باعث میشی احساس کنم آدم بی اهمیتی هستم."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:contour','contour','n','نما، نمود، خطوط خارجی هرچیز','/ˈkɑːn.tʊr/ · outline','A voluminous robe hid the contours of the body underneath.','[["A voluminous robe hid the contours of the body underneath.","ردایی حجیم، خطوط بدن را در زیر خود پنهان می‌کرد."],["I''m learning how to contour my face with make-up.","دارم یاد می‌گیرم چطور با آرایش، صورتم را کانتور کنم."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:convict','convict','v','محکوم شناختن، گناهکار شناختن، مجرم شناختن','/kənˈvɪkt/ · doom, sentence, condemn','Tomás was convicted for money laundering.','[["Tomás was convicted for money laundering.","توماس به جرم پولشویی محکوم شد."],["Miroslav was a convicted child predator.","میروسلاو یک کودک‌آزار محکوم شده بود."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:counterpart','counterpart','n','همتا، همدوش، مکمل، قرینه، نظیر، نسخه، کپی، رونوشت','/ˈkaʊn.tɚ.pɑːrt/ · equivalent, similitude, peer','Our sales team is more efficient than their counterparts in other branches.','[["Our sales team is more efficient than their counterparts in other branches.","تیم فروش ما از همتایان خود در سایر شعب کارآمدتر است."],["I tried to close the discussions at noon, but my counterpart would not stop talking.","من سعی کردم بحث‌ها را ظهر تمام کنم، اما طرف مقابلم دست از صحبت کردن بر نمی‌داشت."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:crawl','crawl','v','خزیدن، آهسته حرکت کردن','/krɑːl/ · move, creep','That scream made my skin crawl.','[["That scream made my skin crawl.","آن فریاد باعث شد پوستم مور مور شود."],["I crawled out of the tent.","از چادر بیرون خزیدم."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:crest','crest','n','قله، فرازینگاه، نوک، سر، راس','/krest/ · peak, climax, culmination, summit','A rooster''s crest is red.','[["A rooster''s crest is red.","تاج خروس قرمز است."],["The Pacific Crest Trail was our destination.","مسیر پاسیفیک کرست مقصد ما بود."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:criticize','criticize','v','انتقاد (ادبی یا هنری و غیره) کردن','/ˈkrɪt·əˌsɑɪz/ · debate, argue','He is often criticized by others.','[["He is often criticized by others.","او اغلب مورد انتقاد دیگران قرار می‌گیرد."],["The logging company was widely criticized.","شرکت چوب‌بری مورد انتقاد گسترده قرار گرفت."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:curb','curb','v','مهار کردن، کنترل کردن','/kɝːb/ · control, suppress','Measures to curb inflation were introduced.','[["Measures to curb inflation were introduced.","اقداماتی برای مهار تورم ارائه شد."],["The government is trying to curb inflation.","تلاش دولت برای مهار تورم"]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:cushion','cushion','v','کاهش دادن اثر (ضربه یا آسیب)، ضربه‌گیر شدن؛ بالشتک','/ˈkʊʃ.ən/ · protect, shield','Exhausted, she sunk into the cushion.','[["Exhausted, she sunk into the cushion.","خسته، در کوسن فرو رفت."],["This sofa has too many cushions.","این مبل کوسن‌های زیادی دارد."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:daring','daring','adj','پر جرات، شجاع، دلیر','/ˈder.ɪŋ/ · bold, brave, defiant','What a daring thing to say!','[["What a daring thing to say!","چه حرف جسورانه‌ای!"]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:decorating','decorating','n','تزیینات','/ˈdekəˌreɪtɪŋ/ · ornaments, adornments','I am not decorating their house.','[["I am not decorating their house.","من خانه آنها را تزئین نمی‌کنم."],["She''s decorating a table beautifully.","داره یه میز رو خیلی قشنگ تزیین می‌کنه."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:deficient','deficient','adj','ناقص، معیوب، ناکامل، کمبوددار، کاستن','/dɪˈfɪʃ.ənt/ · inadequate, defective','Their diet is deficient in protein.','[["Their diet is deficient in protein.","رژیم غذایی آنها فاقد پروتئین است."],["The structure is deficient in harmony.","این ساختار از نظر هماهنگی کمبود دارد."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:deluxe','deluxe','adj','لوکس، مجلل','/dəˈlʌks/ · lavish, luxurious, glorious','What is the difference between a deluxe room and a standard room?','[["What is the difference between a deluxe room and a standard room?","تفاوت اتاق لوکس با اتاق استاندارد چیست؟"],["I''ll have a kebab pizza deluxe, with mixed sauce.","من یک پیتزای کباب دلوکس با سس مخلوط خواهم خورد."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:demise','demise','n','مردن، انقراض','/dɪˈmʌɪz/ · extinction, perish','Alienation from nature will one day become humanity''s demise.','[["Alienation from nature will one day become humanity''s demise.","بیگانگی با طبیعت روزی به نابودی بشریت منجر خواهد شد."],["Rumours of our demise have been greatly exaggerated.","شایعات مربوط به مرگ ما بسیار اغراق‌آمیز بوده‌اند."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:depict','depict','v','به تصویر کشیدن، شرح دادن','/dɪˈpɪkt/ · 1)describe 2)portray','As depicted, he was about thirty years old.','[["As depicted, he was about thirty years old.","همانطور که در تصویر نشان داده شده، او حدود سی سال سن داشته است."],["Miroslav saw a picture depicting a beast.","میروسلاو تصویری را دید که یک جانور را به تصویر می‌کشید."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:derive-from','derive from','phr','مشتق شدن از، نشأت گرفتن از','/dɪˈraɪv frɒm/ · arise from','That song is derived from another.','[["That song is derived from another.","اون آهنگ از یه آهنگ دیگه گرفته شده."],["This word derives from the Greek.","این کلمه از یونانی گرفته شده است."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:designate','designate','v','نامزد کردن (برای شغل)، برگزیدن، تعیین کردن، نامیدن','/ˈdezɪɡneɪt/ · 1) assign, to choose someone or something for a particular job or purpose 2) identify to represent or refer to something using a particular sign, name etc','Stay within the designated swimming area.','[["Stay within the designated swimming area.","در محدوده تعیین‌شده برای شنا بمانید."],["Wales has three designated national parks.","ولز سه پارک ملی تعیین‌شده دارد."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:designation','designation','n','گزینش، انتخاب، انتصاب','/ˌdezɪɡˈneɪʃən/ · identification, [uncountable] the act of choosing someone or something for a particular purpose, or of giving them a particular description','The area received its designation as a national park in 1980.','[["The area received its designation as a national park in 1980.","این منطقه در سال ۱۹۸۰ به عنوان پارک ملی ثبت شد."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:detrimental','detrimental','adj','زیان آور، مضر','/ˌdetrəˈmentl/ · harmful','Smoking is detrimental to health.','[["Smoking is detrimental to health.","سیگار برای سلامتی مضر است."],["Too much screen time can be detrimental to children.","استفاده بیش از حد از صفحه نمایش می‌تواند برای کودکان مضر باشد."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:deviation','deviation','n','کج روی، انحراف','/ˌdiːviˈeɪʃən/ · departure, deflection, digression','Next, try to confirm the deviation with an oscilloscope.','[["Next, try to confirm the deviation with an oscilloscope.","در مرحله بعد، سعی کنید انحراف را با اسیلوسکوپ تأیید کنید."],["No deviation from the regulations will be tolerated.","هیچ گونه انحرافی از مقررات تحمل نخواهد شد."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:devoid','devoid','adj','خالی از، تهی از، بدون','/dɪˈvɔɪd əv/ · short of, lack of, scant of, without','Your life is devoid of any values.','[["Your life is devoid of any values.","زندگی شما عاری از هرگونه ارزش است."],["Gustavo is completely devoid of empathy.","گوستاوو کاملاً عاری از حس همدلی است."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:dictate','dictate','v','فرمان دادن، تحمیل کردن','/dɪkˈteɪt/ · give orders to, prescribe','Powerful nations often dictate the global narrative.','[["Powerful nations often dictate the global narrative.","کشورهای قدرتمند اغلب روایت جهانی را دیکته می‌کنند."],["This is dictated by diplomatic protocol.","این طبق پروتکل دیپلماتیک دیکته شده است."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:dilemma','dilemma','n','معضل، تنگنا، معما','/dəˈlemə/ · problem, difficult/complex situation, no-win situation','I am in a real dilemma.','[["I am in a real dilemma.","من در یک دوگانگی واقعی هستم."],["I''m in a dilemma about which job to take.","من در دوراهی هستم که کدام شغل را انتخاب کنم."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:dim','dim','v','کم نور کردن، ضعیف کردن','/dɪm/ · 1) decrease, if a light dims, or if you dim it, it becomes less bright 2) weak, if a feeling, quality etc dims or is dimmed, it grows weaker or less','We dim the lights for a special ambiance.','[["We dim the lights for a special ambiance.","ما برای ایجاد فضایی خاص، چراغ‌ها را کم نور می‌کنیم."],["He woke up in a dimly lit basement.","او در یک زیرزمین نیمه تاریک از خواب بیدار شد."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:discard','discard','v','دور انداختن','/dɪsˈkɑːd/ · throw away, throw up','That idea was discarded as soon as it was brought up.','[["That idea was discarded as soon as it was brought up.","این ایده به محض مطرح شدن، کنار گذاشته شد."],["For him, women are there to be used and then, discarded.","برای او، زنان برای استفاده شدن و سپس دور انداختن هستند."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:discrete','discrete','adj','مجزا، جدا','/dɪˈskriːt/ · separate','The organisms can be divided into discrete categories.','[["The organisms can be divided into discrete categories.","ارگانیسم‌ها را می‌توان به دسته‌های مجزا تقسیم کرد."],["Instead of conceiving of it as a single thing, we have to recognize it as several discrete types of a similar compound.","به‌جای اینکه آن را یک چیز واحد تصور کنیم، باید آن را چند نوع مجزا از یک ترکیب مشابه بدانیم."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:disguise','disguise','v','پنهان ساختن، لباس مبدل','/dɪsˈɡaɪz/ · hidden, camouflage','I was disguised as a workman.','[["I was disguised as a workman.","من خودم را به شکل یک کارگر درآورده بودم."],["Kalman disguised himself as a beggar.","کالمن خود را به شکل یک گدا درآورد."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:disgust','disgust','v','بیزار شدن، منزجر کردن، مشمئز کردن','/dɪsˈɡʌst/ · distaste, hatred','I am disgusted by that behavior.','[["I am disgusted by that behavior.","از اون رفتارش دلخورم."],["What a disgusting thing to say!","چه حرف زشت و زننده‌ای!"]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:disperse','disperse','v','متفرق کردن، پراکنده کردن','/dɪˈspɜːs/ · scatter, diffuse','The crowd is dispersing now.','[["The crowd is dispersing now.","الان جمعیت داره پراکنده میشه."],["We dispersed from each other.","از هم پراکنده شدیم."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:disposition','disposition','n','طبع، منش، خو','/ˌdɪspəˈzɪʃən/ · temperament, character','My disposition is similar to that of my father.','[["My disposition is similar to that of my father.","اخلاق و رفتارم شبیه پدرم است."],["The boy has his father''s serious disposition.","پسر، خلق و خوی جدی پدرش را دارد."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:distinctly','distinctly','adv','به طور واضح','/dɪˈstɪŋktli/ · clearly, markedly, in a way that is readily distinguishable by the senses','Ziri began to distinctly hear scratching noises.','[["Ziri began to distinctly hear scratching noises.","زیری به وضوح صداهای خراشیدگی را شنید."],["I remember it very distinctly.","من آن را خیلی واضح به یاد دارم."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:distribute','distribute','v','توزیع کردن، پخش کردن','/dɪˈstrɪbjuːt/ · spread; distribution, dispersion','Seeds are distributed by the wind.','[["Seeds are distributed by the wind.","دانه‌ها توسط باد توزیع می‌شوند."],["Volunteers distributed food to the families.","داوطلبان بین خانواده‌ها غذا توزیع کردند."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:disturb','disturb','v','مزاحم شدن، پریشان کردن','/dɪˈstɝːb/ · upset, unsettle, disorganize','Nothing could disturb our unshakeable friendship.','[["Nothing could disturb our unshakeable friendship.","هیچ چیز نمی‌توانست دوستی تزلزل‌ناپذیر ما را خدشه‌دار کند."],["Their raucous behavior disturbed the neighbors.","رفتار ناهنجار آنها همسایه‌ها را آزار می‌داد."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:divert','divert','v','منحرف کردن، معطوف داشتن','/dɪˈvɝːt/ · deflect, redirect','The river was diverted to irrigate nearby fields.','[["The river was diverted to irrigate nearby fields.","رودخانه برای آبیاری مزارع مجاور منحرف شد."],["Traffic is being diverted because of flooding.","به دلیل سیل، ترافیک در حال تغییر مسیر است."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:dormant','dormant','adj','خوابیده، ساکت','/ˈdɔːr.mənt/ · hibernated, inactive','The volcano has been dormant for centuries.','[["The volcano has been dormant for centuries.","این آتشفشان قرن‌ها خاموش بوده است."],["Seeds can remain dormant in the soil for years.","دانه‌ها می‌توانند سال‌ها در خاک خفته بمانند."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:drastic','drastic','adj','شدید، موثر','/ˈdræstɪk/ · extreme; drastically, severely','The government undertook a drastic reform of parliament.','[["The government undertook a drastic reform of parliament.","دولت اصلاحات اساسی در پارلمان انجام داد."],["The time is ripe for a drastic reform.","زمان برای اصلاحات اساسی فرا رسیده است."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:duplicate','duplicate','v','کپی کردن','/ˈdjuːpləkeɪt/ · copy, repeat','This contract is made in duplicate.','[["This contract is made in duplicate.","این قرارداد به صورت تکراری تنظیم شده است."],["Please do not add duplicate entries.","لطفا از اضافه کردن مطالب تکراری خودداری کنید."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:durable','durable','adj','با دوام، ماندنی','/ˈdʊrəbl/ · lasting, enduring','Cork flooring is lightweight and durable.','[["Cork flooring is lightweight and durable.","کفپوش چوب پنبه ای سبک و بادوام است."],["Cardboard is more durable than paper.","مقوا از کاغذ بادوام‌تر است."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:eccentric','eccentric','adj','غیر عادی، عجیب، دمدومی مزاج','/ɪkˈsentrɪk/ · strange, erratic, peculiar','His eccentric behaviour makes everyone a bit uncomfortable.','[["His eccentric behaviour makes everyone a bit uncomfortable.","رفتار عجیب و غریب او همه را کمی معذب می‌کند."],["Poor people are crazy; rich people are eccentric.","فقرا دیوانه هستند؛ ثروتمندان عجیب و غریب."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:edible','edible','adj','خوراکی، خوردنی','/ˈedəbl/ · eatable','How can you tell if a mushroom is edible?','[["How can you tell if a mushroom is edible?","چگونه می‌توان تشخیص داد که قارچ خوراکی است؟"],["Pomegranates are one of the oldest known edible fruits.","انار یکی از قدیمی‌ترین میوه‌های خوراکی شناخته شده است."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:elevate','elevate','v','بالا بردن','/ˈelɪveɪt/ · raise, boost','Which way to the elevated highway?','[["Which way to the elevated highway?","از کدام مسیر به بزرگراه مرتفع می‌روید؟"],["Improved conditions elevate the human experience.","شرایط بهبود یافته، تجربه انسانی را ارتقا می‌دهد."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:elusive','elusive','adj','گریزان','/iˈluːsɪv/ · difficult to catch','The answer to this question has proved elusive.','[["The answer to this question has proved elusive.","پاسخ به این سوال، مبهم و مبهم بوده است."],["The truth is elusive in espionage.","حقیقت در جاسوسی گریزان است."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:embark','embark','v','شروع کردن، دست زدن به (کاری)؛ سوار شدن','/ɪmˈbɑːrk/ · start, begin','He embarked on a journey through the cave.','[["He embarked on a journey through the cave.","او سفری را در میان غار آغاز کرد."],["He embarked on a trip this day.","او در این روز سفری را آغاز کرد."]]','t1212',15,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:emergence','emergence','n','پیدایش، ظهور','/ɪˈmɜːrdʒəns/ · rise, appearance','The emergence of the internet changed the way people communicate.','[["The emergence of the internet changed the way people communicate.","ظهور اینترنت، شیوه‌ی ارتباط مردم را تغییر داد."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:endeavor','endeavor','n','کوشش، جد و جهد، سعی','/ɪnˈdevər/ · enterprise, effort, strife','She seeks their approval in every endeavor.','[["She seeks their approval in every endeavor.","او در هر تلاشی به دنبال تأیید آنها است."],["Implementing this nationwide was no simple endeavor.","اجرای این طرح در سطح کشور کار ساده‌ای نبود."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:endorse','endorse','v','صحه گذاردن، پشتیبانی کردن','/ɪnˈdɔːrs/ · support, advocate','Many experts endorsed the proposal.','[["Many experts endorsed the proposal.","بسیاری از کارشناسان این پیشنهاد را تایید کردند."],["Several celebrities endorsed the new product.","چندین سلبریتی محصول جدید را تایید کردند."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:enduring','enduring','adj','پرطاقت، بادوام، پایدار','/ɪnˈdʊrɪŋ/ · lasting, withstanding, durable','The book is an enduring classic of American literature.','[["The book is an enduring classic of American literature.","این کتاب از آثار کلاسیک ماندگار ادبیات آمریکاست."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:enlist','enlist','v','کمک طلب کردن و گرفتن کمک','/ɪnˈlɪst/ · recurit, obtain, formal to ask for and get help or support from someone','My father opposed my decision to enlist in the special forces.','[["My father opposed my decision to enlist in the special forces.","پدرم با تصمیم من برای ثبت نام در نیروهای ویژه مخالف بود."],["You knew what you were getting into when you enlisted.","وقتی وارد خدمت شدی، می‌دانستی چه چیزی در انتظارت است."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:enrich','enrich','v','غنی کردن، پربار کردن','/ɪnˈrɪtʃ/ · enhance, to improve the "quality" of something, especially by adding things to it','Diversity in opinion enriches our lives.','[["Diversity in opinion enriches our lives.","تنوع در دیدگاه‌ها، زندگی ما را غنی‌تر می‌کند."],["Compassion costs nothing but enriches all.","شفقت هیچ هزینه‌ای ندارد اما همه را غنی می‌کند."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ensuing','ensuing','adj','متعاقب، پیرو','subsequent, following','The ensuing gold rush attracted immigrants, mining companies and slave owners.','[["The ensuing gold rush attracted immigrants, mining companies and slave owners.","تب طلا که در پی آن به راه افتاد، مهاجران، شرکت‌های معدنی و برده‌داران را به خود جذب کرد."],["This sentence was born from indecisiveness and ensuing boredom.","این جمله از بلاتکلیفی و کسالت ناشی از آن زاده شد."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:equilibrium','equilibrium','n','تعادل، برابری، ارامش','/ˌiːkwəˈlɪbriəm/ · balance','How can we define equilibrium for a system of moving particles?','[["How can we define equilibrium for a system of moving particles?","چگونه می‌توانیم تعادل را برای سیستمی از ذرات متحرک تعریف کنیم؟"],["We could apply the theory of punctuated equilibrium to languages.","ما می‌توانیم نظریه تعادل نقطه‌ای را در مورد زبان‌ها به کار ببریم."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:erect','erect','v','ساختن','to build something such as a building or wall (formal )','I erected a stone house.','[["I erected a stone house.","من یک خانه سنگی ساختم."],["Sit erect and sit still.","صاف و بدون حرکت بنشینید."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:erratic','erratic','adj','متغیر، نامنظم','/ɪˈrætɪk/ · irregular, unpredictable, inconsistent','Share prices have been erratic this last month.','[["Share prices have been erratic this last month.","قیمت سهام در ماه گذشته بی‌ثبات بوده است."],["Sami''s behavior was becoming more controlling and erratic.","رفتار سامی داشت کنترل‌گرانه‌تر و غیرقابل پیش‌بینی‌تر می‌شد."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:escalate','escalate','v','تشدید شدن','/ˈeskəleɪt/ · extend, increase rapidly, burgeon','The crisis escalated faster than anyone imagined.','[["The crisis escalated faster than anyone imagined.","بحران سریع‌تر از آنچه کسی تصور می‌کرد، تشدید شد."],["Flavio stopped the conversation before it escalated.","فلاویو قبل از اینکه بحث بالا بگیرد، آن را متوقف کرد."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:estimation','estimation','n','ارزیابی، تخمین','/ˌestəˈmeɪʃən/ · evaluation, assessment, calculation','In my estimation, this is a legitimate purpose.','[["In my estimation, this is a legitimate purpose.","به نظر من، این یک هدف مشروع است."],["In my estimation, he is an honest man.","از نظر من، او مرد شریفی است."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:eventual','eventual','adj','پایانی','/ɪˈventʃuəl/ · later, final, ultimate, end','One will find anything boring eventually.','[["One will find anything boring eventually.","آدم بالاخره هر چیزی را کسل‌کننده خواهد یافت."],["Eventually, we found shelter and warmth.","بالاخره یه جایی پیدا کردیم که گرم و نرم باشه و سرپناه داشته باشیم."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:excavation','excavation','n','حفاری','/ekskəˈveɪʃən/ · unearthing, dig (n)','The excavation uncovered ancient tombs.','[["The excavation uncovered ancient tombs.","در این حفاری مقبره‌های باستانی کشف شد."],["Excavation of the site began in 1931.","حفاری این سایت در سال 1931 آغاز شد."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:exceedingly','exceedingly','adv','بسیار، به حد زیاد','/ɪkˈsiː.dɪŋ.li/ · formal, extremely, to a very great degree','I rejoice exceedingly when I punish an enemy.','[["I rejoice exceedingly when I punish an enemy.","وقتی دشمنی را مجازات می‌کنم، بی‌نهایت شادمان می‌شوم."],["I thought that that went exceedingly well.","به نظرم خیلی خوب پیش رفت."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:exceptionally','exceptionally','adv','به طور غیر معمول','/adverb]/ · unusually, outstandingly','That young lady is exceptionally beautiful.','[["That young lady is exceptionally beautiful.","آن خانم جوان فوق‌العاده زیباست."],["Algeria has an exceptionally long history.","الجزایر تاریخ فوق‌العاده طولانی دارد."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:exert','exert','v','استفاده کردن، اعمال دادن','/ɪɡˈzɜːrt/ · utilize, to use your power, influence etc in order to make something happen','Knowing him, exerting pressure on him is useless.','[["Knowing him, exerting pressure on him is useless.","شناختن او، اعمال فشار بر او بی‌فایده است."],["We exerted ourselves to finish the job.","ما خودمان را به زحمت انداختیم تا کار را تمام کنیم."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:fashionable','fashionable','adj','وابسته به مد، مدگرایانه، مدپرستانه','/ˈfæʃənəbəl/ · popular','Ziri wore fashionable clothes to school.','[["Ziri wore fashionable clothes to school.","زیری لباس‌های شیک و مد روز را در مدرسه می‌پوشید."],["Ziri''s clothes really were fashionable.","لباس‌های زیری واقعاً مد روز بودند."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:feasible','feasible','adj','امکانپذیر','/ˈfiːzəbəl/ · achievable; practicable; probable, possible','Is the plan financially feasible?','[["Is the plan financially feasible?","آیا این طرح از نظر مالی امکان پذیر است؟"],["Is it feasible to finish the project by May?","آیا تکمیل پروژه تا اردیبهشت ماه امکان پذیر است؟"]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:fertile','fertile','adj','بارور، حاصلخیز','/ˈfɜːrtl/ · productive, reproductive','The valley has fertile soil.','[["The valley has fertile soil.","این دره دارای خاک حاصلخیز است."],["She has a fertile imagination.","او تخیل باروری دارد."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:first-and-foremost','first and foremost','phr','اولین و مهمترین','above all','First and foremost, you need to figure out why you''re here.','[["First and foremost, you need to figure out why you''re here.","اول از همه، باید بفهمید که چرا اینجا هستید."],["He always thinks first and foremost of his own benefit.","او همیشه قبل از هر چیز به منافع شخصی خود فکر می‌کند."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:flourish','flourish','v','رشد کردن، شکوفا شدن','/ˈflɜːrɪʃ/ · prosper, thrive','The textile industry flourished after his invention.','[["The textile industry flourished after his invention.","صنعت نساجی پس از اختراع او رونق گرفت."],["The arms trade is flourishing.","تجارت اسلحه رونق گرفته است."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:focal-point','focal point','n','نقطه مرکزی','central point','The tree was the focal point of the village square.','[["The tree was the focal point of the village square.","این درخت نقطه کانونی میدان روستا بود."],["The increase in sales was the focal point of the team meeting.","افزایش فروش، نقطه کانونی جلسه تیمی بود."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:foremost','foremost','adj','بهترین، پیشترین','important, most prominent in rank, importance, or position','I lost my balance and pitched head foremost into the ooze.','[["I lost my balance and pitched head foremost into the ooze.","تعادلم را از دست دادم و سرم را محکم به داخل گل و لای انداختم."],["He always thinks first and foremost of his own benefit.","او همیشه قبل از هر چیز به منافع شخصی خود فکر می‌کند."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:formidable','formidable','adj','نیرومند، دشوار','/fəˈmɪd/ · excessive, powerful, intimidating','Suleimani was a formidable strategist.','[["Suleimani was a formidable strategist.","سلیمانی یک استراتژیست توانمند بود."],["Tom is a formidable man.","تام مرد قدرتمندی است."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:fragment','fragment','n','قطعه، تکه','/ˈfræɡmənt/ · break up; fragmentation, break; fragmentize, break up, piece, particle','They found fragments of pottery.','[["They found fragments of pottery.","تکه‌های سفال پیدا کردند."],["I only heard fragments of their conversation.","من فقط تکه‌هایی از صحبت هایشان را شنیدم."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:friction','friction','n','اختلاف','/ˈfrɪkʃən/ · conflict, disagreement, strife','There is almost zero friction to taking the next step.','[["There is almost zero friction to taking the next step.","برداشتن قدم بعدی تقریباً هیچ مشکلی ایجاد نمی‌کند."],["The newspaper reported friction between the two parties.","این روزنامه از اختلاف نظر بین دو طرف خبر داد."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:get-accustomed-to','get accustomed to','phr','عادت کردن به','/əˈkʌstəmd/ · become used to','You will soon get accustomed to your new school.','[["You will soon get accustomed to your new school.","به زودی به مدرسه جدیدت عادت خواهی کرد."],["You''ll soon get accustomed to this cold weather.","به زودی به این هوای سرد عادت خواهی کرد."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:govern','govern','v','حکومت کردن','/ˈɡʌvən/ · control, regulate','I believe Jews should govern themselves.','[["I believe Jews should govern themselves.","من معتقدم یهودیان باید خودشان را اداره کنند."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:groom','groom','v','آراستن، زیبا کردن','/ɡrʊm/ · make up, clean','Boldi washed the puppy and groomed it.','[["Boldi washed the puppy and groomed it.","بولدی توله سگ را شست و آن را مرتب کرد."],["Ziri was watching his cat grooming itself.","زیری داشت گربه‌اش را تماشا می‌کرد که داشت خودش را تمیز می‌کرد."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:hallmark','hallmark','n','نشان، انگ','/hɑl.mɑrk/ · characteristic, mark, sign','A certain hallmark of wisdom is the cheerful benevolence it confers.','[["A certain hallmark of wisdom is the cheerful benevolence it confers.","یکی از نشانه‌های حکمت، خوش‌بینی و خیرخواهی‌ای است که به همراه دارد."],["The hallmark of a sociopath is a lack of empathy.","مشخصه بارز یک جامعه‌ستیز، فقدان همدلی است."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:harness','harness','v','مورد استفاده قرار دادن، استفاده کردن از','/ˈhɑːnəs/ · put into use, use, utilize, control and use the natural force or power of something','The albatross was harnessing the power for the storm.','[["The albatross was harnessing the power for the storm.","آلباتروس داشت قدرت طوفان را مهار می‌کرد."],["There was neither saddle nor harness on the horse.","اسب نه زین داشت و نه افسار."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:havoc','havoc','n','خرابی، تخریب','/hævək/ · destruction, decimation','That a single person can wreak so much havoc!','[["That a single person can wreak so much havoc!","اینکه یه نفر به تنهایی بتونه این همه خرابی به بار بیاره!"],["The drunken sailors wrecked havoc inside the bar.","ملوانان مست داخل بار آشوب به پا کردند."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:hinder','hinder','v','مانع، تداخل داشتن با','/ˈhɪndə/ · hamperinterfere withprevent','Lack of funds hindered progress.','[["Lack of funds hindered progress.","کمبود بودجه مانع پیشرفت شد"],["Bad weather hindered the rescue efforts.","آب و هوای بد مانع از تلاش‌های امدادی شد."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:hurdle','hurdle','n','حصار، مشکل','/hɜːdl/ · 1) fence, [ C ] a frame or fence for jumping over in a race, 2)a problem that you have to deal with before you can make progress','This is just another hurdle to overcome.','[["This is just another hurdle to overcome.","این فقط یک مانع دیگر است که باید بر آن غلبه کرد."],["He succeeded in spite of major hurdles.","او با وجود موانع بزرگ، موفق شد."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:hypothetical','hypothetical','adj','مفروض','/haɪpəˈθetɪkəl/ · supposed, based on a hypothesis','Who would win in this hypothetical matchup?','[["Who would win in this hypothetical matchup?","در این مسابقه فرضی چه کسی برنده می‌شود؟"],["What is hypothetical may not be real.","چیزی که فرضی است، ممکن است واقعی نباشد."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ignite','ignite','v','مشتعل شدن، کردن','/ɪɡˈnaɪt/ · set on fire','He tried to ignite it.','[["He tried to ignite it.","سعی کرد آن را آتش بزند."],["Damiano ignited the bom manually.","دامیانو بمب را با دست روشن کرد."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:illuminate','illuminate','v','روشن کردن، روشن ساختن','/ɪˈluːməneɪt/ · bright, turn on, shine','Let respect illuminate our journey.','[["Let respect illuminate our journey.","بگذارید احترام، مسیر ما را روشن کند."],["The conversation was very illuminating.","گفتگو بسیار روشنگرانه بود."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:immensely','immensely','adv','فوق العاده، خیلی','/ɪˈmensli/ · extremely, to a great extent','Despite our differences, we respect each other immensely.','[["Despite our differences, we respect each other immensely.","با وجود تفاوت‌هایمان، ما بی‌نهایت به یکدیگر احترام می‌گذاریم."],["This tea parlor is immensely popular.","این چایخانه فوق‌العاده محبوب است."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:immoral','immoral','adj','نامناسب، زشت','/ɪˈmɔːrəl/ · improper, indecent','Pornography is a sinful and immoral portrayal of human sexuality.','[["Pornography is a sinful and immoral portrayal of human sexuality.","پورنوگرافی تصویری گناه آلود و غیراخلاقی از تمایلات جنسی انسان است."],["I refuse to choreograph such a hideous and immoral production.","من از طراحی رقص چنین نمایش شنیع و غیراخلاقی‌ای خودداری می‌کنم."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:imposing','imposing','adj','تاثیر گذار','/ɪmˈpəʊzɪŋ/ · impressive','The UN building is very imposing.','[["The UN building is very imposing.","ساختمان سازمان ملل بسیار با ابهت است."],["Our cathedral is an imposing structure.","کلیسای جامع ما بنایی باشکوه است."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:in-tandem','in tandem','phr','با هم','together','Tom runs the café in tandem with his wife.','[["Tom runs the café in tandem with his wife.","تام به همراه همسرش کافه را اداره می‌کند."],["How good are these trucks powered by Eaton diesel engines and electric motors in tandem?","این کامیون‌ها که با موتورهای دیزلی Eaton و موتورهای الکتریکی به صورت همزمان کار می‌کنند، چقدر خوب هستند؟"]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:inaccessible','inaccessible','adj','دست نیافتنی، دور از دسترس','/ˌɪnəkˈsesəbəl/ · unreachable','The southern shore of the lake is marshy and inaccessible.','[["The southern shore of the lake is marshy and inaccessible.","ساحل جنوبی دریاچه باتلاقی و غیرقابل دسترس است."],["They can''t understand, however, how inaccessible these areas are.","با این حال، آنها نمی‌توانند درک کنند که این مناطق چقدر غیرقابل دسترس هستند."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:inadvertently','inadvertently','adv','سهوا، بدون عمد','/ˌɪnədˈvɜːtəntli/ · without knowing, unintentionally','He inadvertently deleted the file.','[["He inadvertently deleted the file.","او ناخواسته فایل را حذف کرد."],["Species are sometimes introduced inadvertently by ships.","گونه‌ها گاهی به صورت ناخواسته توسط کشتی‌ها معرفی می‌شوند."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:inception','inception','n','شروع به کار یک موسسه یا شرکت','/ɪnˈsepʃən/ · beginning, start','That fund has risen in value quite a bit since its inception.','[["That fund has risen in value quite a bit since its inception.","ارزش این صندوق از زمان تأسیس تاکنون به میزان قابل توجهی افزایش یافته است."],["Tatoeba''s popularity has been growing exponentially since the day of its inception.","محبوبیت تاتوبا از روز آغاز به کار خود به صورت تصاعدی در حال افزایش بوده است."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:incidentally','incidentally','adv','اتفاقا، به هر حال','/ˌɪnsəˈdentəli/ · by the way, accidentally','The film we incidentally watched yesterday was well worth watching.','[["The film we incidentally watched yesterday was well worth watching.","فیلمی که دیروز اتفاقاً تماشا کردیم، واقعاً ارزش دیدن داشت."],["Incidentally, I have to tell you something.","اتفاقاً باید یه چیزی بهت بگم."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:indications','indications','n','نشانه','/ɪndɪˈkeɪʃ(ə)n/ · signs','There are some indications of progress.','[["There are some indications of progress.","برخی نشانه‌های پیشرفت وجود دارد."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:indispensable','indispensable','adj','ضروری','/ɪndɪˈspɛnsəb(ə)l/ · essential, necessary, needed, required, significant, vital','I detest liars. Honesty is an indispensable quality of good character.','[["I detest liars. Honesty is an indispensable quality of good character.","از دروغگوها متنفرم. صداقت یک ویژگی ضروری از شخصیت خوب است."],["Her financial support is indispensable to this project of ours.","حمایت مالی او برای این پروژه ما ضروری است."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:induce','induce','v','وادار کردن، تحریک کردن','/inˈd(y)o͞os/ · bring about, bring, cause, give rise to, produce','None of these measures induced a change of policy.','[["None of these measures induced a change of policy.","هیچ یک از این اقدامات باعث تغییر سیاست نشد."],["Some drugs induce sleep.","برخی داروها خواب را تحریک می‌کنند."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:inflict','inflict','v','تحمیل کردن، وادارکردن','/inˈflikt/ · bring about, impose, cause to be suffered by someone or something','Inflation inflicts a creeping expropriation upon savers.','[["Inflation inflicts a creeping expropriation upon savers.","تورم، سلب مالکیت خزنده‌ای را از پس‌اندازکنندگان تحمیل می‌کند."],["Antonio enjoyed inflicting pain on other people.","آنتونیو از آزار و اذیت دیگران لذت می‌برد."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ingenious','ingenious','adj','خلاق، باهوش، مبتکر، مخترع','/inˈjēnyəs/ · very clever, intelligent, smart, astute','The ingenious man received the prestigious award for the first time.','[["The ingenious man received the prestigious award for the first time.","مرد مبتکر برای اولین بار این جایزه معتبر را دریافت کرد."],["Ingenious solutions often capture our attention because of their simplicity.","راه‌حل‌های هوشمندانه اغلب به دلیل سادگی‌شان توجه ما را جلب می‌کنند."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:inhibit','inhibit','v','محدودکردن، کاستن','/ɪnˈhɪbɪt/ · decrease, hinder, hamper','the obstacles which inhibit change','[["the obstacles which inhibit change","موانعی که مانع از تغییر می‌شوند"],["Fear can inhibit a child''s ability to learn.","ترس می‌تواند توانایی کودک برای یادگیری را مهار کند."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:initiate','initiate','v','آغاز، وارد کردن','/ɪˈnɪʃieɪt/ · start, begin [v]','That landing in Alabama initiated a full-scale invasion.','[["That landing in Alabama initiated a full-scale invasion.","آن ورود به آلاباما، آغازگر یک هجوم تمام‌عیار بود."],["The government initiated a program to plant trees.","دولت برنامه ای را برای کاشت درخت آغاز کرد."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:insufficient','insufficient','adj','ناکافی','/ˈinsəˈfiSHənt/ · inadequate, not enough','Your response is wholly insufficient.','[["Your response is wholly insufficient.","پاسخ شما کاملاً ناکافی است."],["Housing is insufficient in Algeria.","مسکن در الجزایر ناکافی است."]]','t1212',16,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:intercourse','intercourse','n','تبادل (ایده)، ارتباط','/ˈɪntərkɔːrs/ · exchange, an exchange of ideas, feelings etc which make people or groups understand each other better','Rodrigo expressed his desire to have intercourse.','[["Rodrigo expressed his desire to have intercourse.","رودریگو تمایل خود را برای داشتن رابطه جنسی ابراز کرد."],["Virginity is lost in intercourse.","بکارت در رابطه جنسی از بین می‌رود."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:intricate','intricate','adj','پیچیده و با جزییات زیاد','/ˈɪntrɪkət/ · carefully shaped; complex','The walls feature intricate floral patterns.','[["The walls feature intricate floral patterns.","دیوارها دارای الگوهای پیچیده گل هستند."],["They admired the intricate design on the cake.","آنها طرح پیچیده روی کیک را تحسین کردند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:intrigue','intrigue','v','شیفته کردن','/ɪnˈtriːɡ/ · interest, fascinate','I am, as they say, intrigued.','[["I am, as they say, intrigued.","من، همانطور که می‌گویند، کنجکاو هستم."],["Morocco has some intriguing internal politics.","مراکش سیاست داخلی جذابی دارد."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:intriguing','intriguing','adj','جذاب','/ɪnˈtriːɡɪŋ/ · fascinating','Morocco has some intriguing internal politics.','[["Morocco has some intriguing internal politics.","مراکش سیاست داخلی جذابی دارد."],["His paintings are intriguing to me.","نقاشی‌هایش برایم جذاب هستند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:intrinsic','intrinsic','adj','ذاتی، لازمه','/ɪnˈtrɪnsɪk/ · essential; inherent','Flexibility is intrinsic to creative management.','[["Flexibility is intrinsic to creative management.","انعطاف پذیری ذاتی مدیریت خلاق است."],["The painting has little intrinsic value.","این نقاشی ارزش ذاتی کمی دارد."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:intrusive','intrusive','adj','آزاردهنده','/ɪnˈtruː.sɪv/ · invasive, causing disruption or annoyance through being unwelcome or uninvited','Miroslav apologized for being intrusive at the beginning.','[["Miroslav apologized for being intrusive at the beginning.","میروسلاو در ابتدا به خاطر فضولی‌اش عذرخواهی کرد."],["I let the intrusive thoughts win.","گذاشتم افکار مزاحم پیروز شوند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:invade','invade','v','حمله کردن','/ɪnˈveɪd/ · move into, attack a country or region','Normally, wolves would never invade human territory.','[["Normally, wolves would never invade human territory.","گرگ‌ها معمولاً هرگز به قلمرو انسان‌ها حمله نمی‌کنند."],["He invades the privacy of others.","او به حریم خصوصی دیگران تجاوز می‌کند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:invaluable','invaluable','adj','فوق العاده گرانبها و سودمند','/ɪnˈvæl.jə.bəl/ · highly useful, very valuable','This clothes bag is invaluable.','[["This clothes bag is invaluable.","این کیف لباس فوق‌العاده ارزشمند است."],["Their support has been invaluable.","حمایت آنها بسیار ارزشمند بوده است."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:invariably','invariably','adv','همواره','/ɪnˈver.i.ə.bli/ · always, in every case or on every occasion, constantly','Such a person invariably expends his physical energy more slowly.','[["Such a person invariably expends his physical energy more slowly.","چنین شخصی همواره انرژی فیزیکی خود را کندتر مصرف می‌کند."],["Why is it that at a bachelor''s establishment the servants invariably drink the champagne?","چرا در یک مهمانخانه مجردی، خدمتکاران همیشه شامپاین می‌نوشند؟"]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:invent','invent','v','اختراع کردن، درست کردن','/ɪnˈvent/ · devise, create or design (something that has not existed before)','Before bar codes were invented, supermarket customers waited in long lines.','[["Before bar codes were invented, supermarket customers waited in long lines.","پیش از اختراع بارکد، مشتریان سوپرمارکت در صف‌های طولانی منتظر می‌ماندند."],["This is why internet was invented.","به همین دلیل اینترنت اختراع شد."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:invoke','invoke','v','التماس، درخواست','/inˈvōk/ · appeal, cite or appeal to','The UN threatened to invoke economic sanctions.','[["The UN threatened to invoke economic sanctions.","سازمان ملل تهدید به اعمال تحریم‌های اقتصادی کرد."],["Maybe the ads will invoke the authority of a famous baby doctor to emphasize the health appeal.","شاید آگهی‌ها به اعتبار یک پزشک کودکان مشهور استناد کنند تا بر جذابیت سلامت‌محور محصول تأکید کنند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:jointly','jointly','adv','به طور مشترک','/ˈjointlē/ · combined, in partnership, cooperatively','They worked jointly on this project.','[["They worked jointly on this project.","آنها به طور مشترک روی این پروژه کار کردند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:lateral','lateral','adj','جانبی','/ˈlætərəl/ · side','The lateral malleolus is the bone on the outside of the ankle joint.','[["The lateral malleolus is the bone on the outside of the ankle joint.","قوزک خارجی استخوانی است که در قسمت بیرونی مفصل مچ پا قرار دارد."],["It may be necessary to think laterally to come up with a good solution.","شاید لازم باشد برای رسیدن به یک راه حل خوب، کمی فکر کنید."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:lax','lax','adj','سست، اهمال کار','/læks/ · careless, not strict or careful enough about standards of behaviour, work, safety etc','Some member countries have been lax in abiding by G-7 agreements.','[["Some member countries have been lax in abiding by G-7 agreements.","برخی از کشورهای عضو در رعایت توافق‌نامه‌های گروه هفت سهل‌انگاری کرده‌اند."],["Parents who are lax in raising their children do them a disservice.","والدینی که در تربیت فرزندان خود سهل‌انگار هستند، به آنها آسیب می‌رسانند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:legitimacy','legitimacy','n','حقانی، قانونی بودن، درستی، بر حق بودن','/ləˈdʒɪt.ə.mə.si/ · authority, authenticity, validity','Fair trials ensure the legitimacy of holding war criminals accountable.','[["Fair trials ensure the legitimacy of holding war criminals accountable.","محاکمات عادلانه، مشروعیت پاسخگو نگه داشتن جنایتکاران جنگی را تضمین می‌کند."],["I don''t accept the legitimacy of this government.","من مشروعیت این حکومت را قبول ندارم."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:legitimately','legitimately','adv','به صورت مشروعی و قانونی','/əˈdʒɪt.ə.mət.li/ · properly, lawfully','Sami is legitimately my biggest supporter.','[["Sami is legitimately my biggest supporter.","سامی واقعاً بزرگترین حامی من است."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:linger','linger','v','ماندن، درنگ کردن، طول کشیدن','/ˈlɪŋɡər/ · stroll, wanderto continue to exist, be noticeable etc for longer than is usual or desirable','The vision that was planted in my senses still silently lingers.','[["The vision that was planted in my senses still silently lingers.","رؤیایی که در حواس من کاشته شده بود، هنوز هم در سکوت ادامه دارد."],["There are rumors that some evil spirits linger around here.","شایعاتی وجود دارد مبنی بر اینکه برخی ارواح شیطانی در اینجا پرسه می‌زنند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:little-short-of-miraculous','little short of miraculous','phr','چیزی شبیه معجزه','/mɪˈrækjələs/ · amazing but it is impossible','His recovery after the accident was little short of miraculous.','[["His recovery after the accident was little short of miraculous.","بهبودی او پس از تصادف چیزی شبیه معجزه بود."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:livelihood','livelihood','n','معیشت، معاش، وسیله معاش','/ˈlaɪvlihʊd/ · means of support, living','Subsistence farming is the dominant form of livelihood.','[["Subsistence farming is the dominant form of livelihood.","کشاورزی معیشتی، شکل غالب معیشت است."],["Many of them have lost their livelihood.","بسیاری از آنها معیشت خود را از دست داده‌اند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:lucrative','lucrative','adj','سودآور، پرمنفعت، سودمند','/ˈluːkrətɪv/ · profitable, beneficial','Tourism is a lucrative industry.','[["Tourism is a lucrative industry.","گردشگری یک صنعت پرسود است."],["Real estate can be a lucrative investment.","املاک و مستغلات می‌تواند یک سرمایه گذاری سودآور باشد."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:majestic','majestic','adj','باشکوه، باعظمت','/məˈdʒestɪk/ · magnificent, glorious, splendid, very big, impressive, or beautiful','A majestic rooster paced around the yard.','[["A majestic rooster paced around the yard.","خروس باشکوهی در حیاط قدم می‌زد."],["My signature is meaningful, majestic and inimitable.","امضای من معنادار، باشکوه و بی‌نظیر است."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:manifest','manifest','v','آشکار ساختن، معلوم کردن، فاش کردن','/ˈmænəfest/ · reveal, to display or show (a quality or feeling) by one''s acts or appearance; demonstrate','I manifest my heart''s desires quickly and easily.','[["I manifest my heart''s desires quickly and easily.","من به سرعت و به راحتی خواسته‌های قلبی‌ام را آشکار می‌کنم."],["Flavio manifested signs of infection.","فلاویو علائم عفونت را نشان داد."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:manipulate','manipulate','v','دستکاری کردن، اداره کردن','/məˈnɪpjəleɪt/ · control, manage, handle or control (a tool, mechanism, etc.), typically in a skillful manner','She knows how to manipulate her parents to get what she wants.','[["She knows how to manipulate her parents to get what she wants.","او می‌داند که چگونه پدر و مادرش را دستکاری کند تا به آنچه می‌خواهد برسد."],["He is being manipulated by her.","او توسط او دستکاری می‌شود."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:mastery','mastery','n','اربابی، سلطه','/ˈmæˈstəri/ · control, lordship','Workers seek mastery in challenging tasks.','[["Workers seek mastery in challenging tasks.","کارگران به دنبال تسلط در کارهای چالش برانگیز هستند."],["Life is a melody composed with supreme art and excellent mastery.","زندگی ملودی‌ای است که با هنری والا و استادی بی‌نظیر ساخته شده است."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:merge','merge','v','ادغام کردن، ترکیب کردن','/mɜːrdʒ/ · blend, combine, to combine, or to join things together to form one thing','Continuous integration involves frequently merging code changes.','[["Continuous integration involves frequently merging code changes.","ادغام مداوم شامل ادغام مکرر تغییرات کد است."],["Elias quickly merged to the left lane.","الیاس به سرعت به لاین چپ پیچید."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:milestone','milestone','n','رویداد مهم','/ˈmaɪlstoʊn/ · significant event, landmark','The first fart is an important milestone in a romantic relationship.','[["The first fart is an important milestone in a romantic relationship.","اولین گوز نقطه عطف مهمی در یک رابطه عاشقانه است."],["She sees the service award as a milestone in her career.","او دریافت این نشان افتخار را نقطه عطفی در کارنامه خود می‌داند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:mimic','mimic','v','تقلید کردن؛ مقلد','/ˈmɪmɪk/ · copy, imitate','Children learn by mimicking words and tones.','[["Children learn by mimicking words and tones.","کودکان با تقلید کلمات و لحن‌ها یاد می‌گیرند."],["The alien was trying to mimic a human being.","موجود فضایی سعی داشت ادای انسان را دربیاورد."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:miniature','miniature','adj','کوچک، کوتاه','/ˈmɪniətʃər/ · small, tiny, minuscule','Have you ever played miniature golf?','[["Have you ever played miniature golf?","تا حالا مینی گلف بازی کردی؟"],["Neubronner fitted pigeons with miniature cameras.","نوبرونر کبوترها را به دوربین‌های مینیاتوری مجهز کرد."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:misunderstanding','misunderstanding','n','سوء تفاهم، اشتباه فهمیدن','/ˌmɪsʌndərˈstændɪŋ/ · false idea, misconception','That helps in melting away misunderstandings.','[["That helps in melting away misunderstandings.","این به از بین بردن سوءتفاهم‌ها کمک می‌کند."],["Misunderstandings often arise from incomplete information.","سوءتفاهم‌ها اغلب از اطلاعات ناقص ناشی می‌شوند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:modification','modification','n','اصلاح، پیرایش، تعدیل','/ˌmɒdɪfɪˈkeɪʃən/ · alteration, amendment','This document must not undergo further modifications.','[["This document must not undergo further modifications.","این سند نباید دستخوش تغییرات بیشتر شود."],["I see you made a few modifications.","می‌بینم که چند تا تغییر ایجاد کردی."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:modify','modify','v','تغییر دادن','/ˈmɒdɪfaɪ/ · change, alter, amend','The regulations can only be modified by a special committee.','[["The regulations can only be modified by a special committee.","این مقررات فقط توسط یک کمیته ویژه قابل تغییر است."],["The plan was modified after the test.","این طرح پس از آزمایش اصلاح شد."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:monumental','monumental','adj','عظیم، زیاد','/ˌmɒnjəˈmentl/ · giant, significant, great in importance, extent, or size','Ultimately, everything ended up being a monumental mess.','[["Ultimately, everything ended up being a monumental mess.","در نهایت، همه چیز به یک آشفتگی عظیم تبدیل شد."],["The moon landing was a monumental achievement.","فرود بر ماه یک دستاورد بزرگ بود."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:motif','motif','n','الگو، طرح','/məʊˈtiːf/ · pattern, a decorative design or pattern','Tudor pennons were highly decorated with slogans and heraldic motifs.','[["Tudor pennons were highly decorated with slogans and heraldic motifs.","پرچم‌های تودور با شعارها و نقوش هرالدیک بسیار تزئین شده بودند."],["Flowers and geometric motifs were painted on the interior walls.","گل‌ها و نقوش هندسی بر روی دیوارهای داخلی نقاشی شده بودند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:mundane','mundane','adj','عادی، معمولی، پیش پا افتاده، دنیوی','/mʌnˈdeɪn/ · material, ordinary, lacking interest or excitement','Robots can do mundane tasks.','[["Robots can do mundane tasks.","ربات‌ها می‌توانند کارهای روزمره را انجام دهند."],["She was tired of the mundane routine of office life.","او از روال عادی زندگی اداری خسته شده بود."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:mutually-exclusive','mutually exclusive','phr','ناسازگار، مانعه‌الجمع','/ˈmjuːtʃuəli ɪkˈskluːsɪv/ · contradictory','That is not to say the two are mutually exclusive.','[["That is not to say the two are mutually exclusive.","این به آن معنا نیست که این دو از هم جدا هستند."],["It would appear to me that the two ideas aren''t mutually exclusive.","به نظر من این دو ایده با هم تناقض ندارند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:myriad','myriad','adj','فراوان، هزاران','/ɪkˈskluːsɪv/ · countless, innumerable, numerous, extremely great in number.','We entered this world to experience life in its myriad forms.','[["We entered this world to experience life in its myriad forms.","ما به این دنیا آمده‌ایم تا زندگی را در اشکال بی‌شمارش تجربه کنیم."],["The night sky was filled with a myriad of stars.","آسمان شب پر از ستاره‌های بی‌شماری بود."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:needless-to-say','needless to say','phr','آشکار است، نیاز به توضیح نیست','obvious, used when you are telling someone something that they probably know or expect','Needless to say, it was a rare occurrence.','[["Needless to say, it was a rare occurrence.","ناگفته نماند که اتفاق نادری بود."],["Needless to say, getting up early is important.","ناگفته نماند که زود بیدار شدن مهم است."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:noticeable','noticeable','adj','قابل توجه، برجسته','/ˈnoʊ.tɪ.sə.bəl/ · obvious','There has been a noticeable change in her behavior.','[["There has been a noticeable change in her behavior.","تغییر محسوسی در رفتارش ایجاد شده است."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:notwithstanding','notwithstanding','prep','علی رغم، با وجود اینکه','/ˌnɑːt.wɪðˈstæn.dɪŋ/ · despite, nevertheless','Notwithstanding the costs, the project continued.','[["Notwithstanding the costs, the project continued.","با وجود هزینه‌ها، پروژه ادامه یافت."],["Notwithstanding the bad weather, the event was a success.","با وجود آب و هوای بد، این رویداد موفقیت آمیز بود."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:on-the-spur-of-the-moment','on the spur of the moment','phr','بدون برنامه و ناگهانی','without planning','These issues cannot be decided on the spur of the moment.','[["These issues cannot be decided on the spur of the moment.","این مسائل را نمی‌توان فی‌البداهه و آنی حل کرد."],["Ideas occur to me on the spur of the moment.","ایده‌ها در لحظه به ذهنم می‌رسند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:onset','onset','n','شروع','/ˈɑːnset/ · 1) start 2)beginning, (especially something unpleasant)','We need to buy warm clothes before the onset of winter.','[["We need to buy warm clothes before the onset of winter.","قبل از شروع زمستان باید لباس گرم بخریم."],["The doctors are trying to delay the onset of the disease.","پزشکان در تلاشند تا شروع بیماری را به تأخیر بیندازند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:opaque','opaque','adj','غیر شفاف، مبهم، کدر، مات، پوشیده','/oʊˈpeɪk/ · impenetrable ریذپانذوفنimpermeable ریذپانذوفنimpervious ریذپانذوفن (materials that are impervious to water)not able to be seen through','Contrary to what many people think, opaque glass is very old.','[["Contrary to what many people think, opaque glass is very old.","برخلاف تصور بسیاری از مردم، شیشه مات قدمت زیادی دارد."],["Opaque? Not at all. Intuitively obvious to the most casual observer.","مات؟ به هیچ وجه. برای عادی‌ترین ناظر هم کاملاً واضح است."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:originate-from','originate from','phr','سرچشمه گرفتن از، نشأت گرفتن از','come into existence from','Where did blood originate from?','[["Where did blood originate from?","خون از کجا سرچشمه گرفته است؟"],["Those stories originate from Algeria.","این داستان‌ها از الجزایر سرچشمه می‌گیرند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ornament','ornament','n','تزئین، زینت','/ˈɔːrnəmənt/ · decorate','It just works as an ornament.','[["It just works as an ornament.","فقط به عنوان یه وسیله تزئینی عمل می‌کنه."],["Proverbs are the ornaments of speech.","ضرب المثل‌ها زینت کلام هستند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ornamental','ornamental','adj','زینتی','/ˌɔːrnəˈmentl/ · decorative','Ziri uses ivies as ornamental plants.','[["Ziri uses ivies as ornamental plants.","زیری از پیچک‌ها به عنوان گیاهان زینتی استفاده می‌کند."],["Hydrangeas are popular ornamental garden shrubs.","گل‌های هورتانسیا درختچه‌های زینتی محبوبی برای باغ‌ها هستند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:overlook','overlook','v','چشم پوشی کردن','/ˌoʊvərˈlʊk/ · ignore','He overlooks my successes at every opportunity.','[["He overlooks my successes at every opportunity.","او در هر فرصتی موفقیت‌های مرا نادیده می‌گیرد."],["A volcanic butte overlooked the barren landscape.","یک تپه آتشفشانی مشرف به چشم‌انداز بایر بود."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:owing-to','owing to','prep','بعلت، زیرا','because of, due to','Owing to her nervousness, she made many mistakes.','[["Owing to her nervousness, she made many mistakes.","به دلیل عصبی بودنش، اشتباهات زیادی مرتکب شد."],["We could not play owing to the rain.","به خاطر باران نتوانستیم بازی کنیم."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:paradox','paradox','n','تناقض، بیان مغایر، اضداد','/ˈpærədɑːks/ · 1)contrary 2)contradictory','It is a paradox that more choice can make us less happy.','[["It is a paradox that more choice can make us less happy.","این یک پارادوکس است که انتخاب بیشتر می‌تواند ما را کمتر خوشحال کند."],["It''s a paradox that the more choices we have, the less happy we feel.","این یک پارادوکس است که هرچه انتخاب‌های بیشتری داشته باشیم، کمتر احساس خوشبختی می‌کنیم."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:parcel-out','parcel out','phr','توزیع کردن، پخش کردن','/ˈpɑːrsəl aʊt/ · parcel out, distributeparcel off/up, divideparcel (n), packagea parcel of clothes and blankets','Frankie parceled out soup for each of the homeless men.','[["Frankie parceled out soup for each of the homeless men.","فرانکی برای هر یک از مردان بی‌خانمان سوپ بسته‌بندی کرد."],["The money was parceled out to several charities.","این پول بین چندین موسسه خیریه تقسیم شد."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:peculiar','peculiar','adj','عجیب وغریب، دارای اخلاق غریب، ویژه','/pɪˈkjuːliər/ · strange, eccentric','She has a very peculiar sense of humor.','[["She has a very peculiar sense of humor.","او حس شوخ طبعی خیلی عجیبی دارد."],["My views are, shall we say, quite peculiar.","می‌توان گفت که دیدگاه‌های من کاملاً عجیب و غریب هستند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:penetrate','penetrate','v','نفوذ کردن در، بداخل سرایت کردن، رخنه کردن','/ˈpenətreɪt/ · enter, pierce, osmose, make a hole in','The water penetrated the walls.','[["The water penetrated the walls.","آب به دیوارها نفوذ کرد."],["Sunlight is penetrating the curtains.","نور خورشید از لای پرده‌ها به داخل نفوذ می‌کند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:peril','peril','n','خطر، مخاطره، بیم زیان','/ˈperəl/ · danger','I dread more the peril to my good name.','[["I dread more the peril to my good name.","من بیشتر از به خطر افتادن آبرویم می‌ترسم."],["Victory without peril is triumph without glory.","پیروزی بدون خطر، پیروزی بدون افتخار است."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:periodically','periodically','adv','بصورت دوره‌ای، در فواصل معین','/ˌpɪriˈɑː-dɪkli/ · 1)from time to time 2)regularly','The equipment is checked periodically for safety.','[["The equipment is checked periodically for safety.","تجهیزات به صورت دوره‌ای از نظر ایمنی بررسی می‌شوند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:perpetual','perpetual','adj','ابدی، همیشگی','/pərˈpetʃuəl/ · constant, continual, habitual, eternal','They are perpetually upset with them.','[["They are perpetually upset with them.","آنها دائماً از آنها ناراحت هستند."],["They perpetually reminisce about him.","آنها مدام از او خاطره تعریف می‌کنند."]]','t1212',17,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:persist','persist','v','اصرار ورزیدن، پافشاری کردن','/pərˈsɪst/ · 1)continue 2)last','But the Oxford camp persists in their position.','[["But the Oxford camp persists in their position.","اما اردوگاه آکسفوردی‌ها بر موضع خود پافشاری می‌کند."],["The only thing that persists is change.","تنها چیزی که پابرجاست، تغییر است."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:pertinent','pertinent','adj','مربوط','/ˈpɜːrtnənt/ · relevant, related','Could you please summarize the pertinent points?','[["Could you please summarize the pertinent points?","میشه لطفا نکات مهم رو خلاصه کنید؟"],["Do you think this is pertinent?","به نظر شما این موضوع مرتبط است؟"]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:pervasive','pervasive','adj','فراگیر','/pərˈveɪsɪv/ · widespread, existing in all parts of a place or thing; spreading gradually to affect all parts of a place or thing','The pervasive influence of social media is clear.','[["The pervasive influence of social media is clear.","نفوذ فراگیر رسانه‌های اجتماعی واضح است."],["A pervasive smell of smoke filled the house.","بوی فراگیر دود خانه را پر کرده بود."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:phenomena','phenomena','n','پدیده، آثار','/fɪˈnɒmənən/ · [pl.] events','Why are we awestruck by certain natural phenomena?','[["Why are we awestruck by certain natural phenomena?","چرا ما از دیدن برخی پدیده‌های طبیعی شگفت‌زده می‌شویم؟"],["Extreme weather phenomena are becoming ever more frequent.","پدیده‌های آب و هوایی شدید، بیش از پیش شایع می‌شوند."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:phenomenal','phenomenal','adj','فوق العاده، شگفت‌انگیز','/fɪˈnɒmɪnəl/ · extraordinary','Tom is phenomenal in bed.','[["Tom is phenomenal in bed.","تام توی رختخواب فوق‌العاده‌ست."],["Tom has a phenomenal memory.","تام حافظه‌ی فوق‌العاده‌ای دارد."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:pigment','pigment','n','رنگ','/ˈpɪɡmənt/ · color','Natural pigments were extracted from minerals.','[["Natural pigments were extracted from minerals.","رنگدانه‌های طبیعی از مواد معدنی استخراج شد."],["Make up has often used carmine as a pigment to achieve bright red shades.","لوازم آرایش اغلب از کارمین به عنوان رنگدانه برای رسیدن به سایه‌های قرمز روشن استفاده می‌کنند."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:pinnacle','pinnacle','n','اوج، راس، منتهی درجه','/ˈpɪnəkəl/ · high point, culmination','The pinnacle of evolution is the dolphin.','[["The pinnacle of evolution is the dolphin.","اوج تکامل دلفین است."],["Australia is a pinnacle of social progress.","استرالیا اوج پیشرفت اجتماعی است."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:pinpoint','pinpoint','v','با دقت مشخص کردن، دقیقاً پیدا کردن','/ˈpɪnpɔɪnt/ · 1)clearly identify 2)describe precisely','A GPS device can pinpoint your location anywhere in the world.','[["A GPS device can pinpoint your location anywhere in the world.","یک دستگاه GPS می‌تواند موقعیت مکانی شما را در هر کجای دنیا مشخص کند."],["It''s not possible to pinpoint when human beings began to exist.","نمی‌توان دقیقاً مشخص کرد که انسان از چه زمانی شروع به وجود آوردن کرده است."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:plausible','plausible','adj','باور کردنی، محتمل','/ˈplɑː.zə.bəl/ · 1)believable 2)apparently reasonable and valid','I accuse the politicians of starting a war without plausible motive.','[["I accuse the politicians of starting a war without plausible motive.","من سیاستمداران را به شروع جنگ بدون انگیزه موجه متهم می‌کنم."],["Your explanation sounds plausible, but it just doesn''t hold water.","توضیح شما منطقی به نظر می‌رسد، اما با واقعیت جور در نمی‌آید."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:potent','potent','adj','قوی، نیرومند','/ˈpoʊtnt/ · powerful','Race remains a potent and often divisive force in our society.','[["Race remains a potent and often divisive force in our society.","نژاد همچنان یک نیروی قدرتمند و اغلب تفرقه‌انگیز در جامعه ما است."],["Polonium can be used as a very potent poison.","پولونیوم می‌تواند به عنوان یک سم بسیار قوی مورد استفاده قرار گیرد."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:pragmatic','pragmatic','adj','عملگرا','/præɡˈmætɪk/ · practical, based on practical rather than theoretical considerations','We need a pragmatic solution.','[["We need a pragmatic solution.","ما به یک راه حل عملی نیاز داریم."],["She took a pragmatic approach to the problem.","او رویکردی عمل‌گرایانه به این مشکل داشت."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:prevail','prevail','v','غالب بودن، چیره شدن، رایج بودن','/prɪˈveɪl/ · dominate, monopolize','He was eventually prevailed upon to accept the appointment.','[["He was eventually prevailed upon to accept the appointment.","سرانجام او را متقاعد کردند که این انتصاب را بپذیرد."],["A serious form of flu prevails throughout the country.","نوعی آنفولانزای شدید در سراسر کشور شیوع پیدا کرده است."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:prevailing','prevailing','adj','غالب، محبوب','/prɪˈveɪlɪŋ/ · dominant, popular','Bad cold is prevailing throughout the country.','[["Bad cold is prevailing throughout the country.","سرمای شدیدی سراسر کشور را فرا گرفته است."],["This is now the prevailing opinion.","الان این نظر غالب است."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:prevalent','prevalent','adj','شایع، مشترک، غالب','/ˈprevələnt/ · common, prevailing','Dry weather with tropical temperatures is prevalent.','[["Dry weather with tropical temperatures is prevalent.","آب و هوای خشک با دمای گرمسیری غالب است."],["Water is the most prevalent liquid.","آب رایج‌ترین مایع است."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:pristine','pristine','adj','تر و تازه','/ˈprɪstiːn/ · pure, fresh, in its original condition; unspoiled.','Sunlight reflected off the pristine lake, dancing tremulously across the boats'' hulls.','[["Sunlight reflected off the pristine lake, dancing tremulously across the boats'' hulls.","نور خورشید از دریاچه بکر منعکس می‌شد و با لرزشی لرزان بر روی بدنه قایق‌ها می‌رقصید."],["The governor''s recent scandal was a blight on her otherwise pristine track record.","رسوایی اخیر فرماندار، لکه ننگی بر سابقه درخشان او بود."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:prized','prized','adj','با ارزش','/praɪzd/ · valued, cherished','The old violin is his most prized possession.','[["The old violin is his most prized possession.","ویولن قدیمی باارزش‌ترین دارایی اوست."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:procurement','procurement','n','تدارک، تهیه، به دست آوردن','/prəˈkjʊr/ · acquire, obtain (something), especially with care or effort','The military''s procurement process was found to favor the vice-president''s company.','[["The military''s procurement process was found to favor the vice-president''s company.","مشخص شد که روند تدارکات ارتش به نفع شرکت معاون رئیس جمهور بوده است."],["We are trying to clarify your future procurement requirements.","ما در تلاشیم تا نیازهای تدارکاتی آینده شما را روشن کنیم."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:programmed','programmed','adj','برنامه ریزی‌شده، مشخص','determined, arrange according to a plan or schedule','Leon was programmed to say that.','[["Leon was programmed to say that.","لئون طوری برنامه‌ریزی شده بود که این را بگوید."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:progressively','progressively','adv','به تدریج','/prəˈɡresɪvli/ · gradually','The disease became progressively worse over the years.','[["The disease became progressively worse over the years.","این بیماری در طول سال‌ها به تدریج بدتر شد."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:projection','projection','n','تخمین، پیش بینی','/prəˈdʒekʃən/ · estimate/prediction','Map projection distorts size and distance.','[["Map projection distorts size and distance.","طرح ریزی نقشه اندازه و فاصله را تغییر می‌دهد."],["Climate projections guide environmental policies.","پیش بینی‌های اقلیمی سیاست‌های زیست محیطی را هدایت می‌کند."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:proliferation','proliferation','n','تکثیر، افزایش','/prəˌlɪfəˈreɪʃn/ · [n] increase, rapid increase in numbers','The proliferation of fast food is worrying.','[["The proliferation of fast food is worrying.","گسترش فست فودها نگران کننده است."],["The proliferation of smartphones has changed society.","گسترش گوشی‌های هوشمند جامعه را تغییر داده است."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:prosper','prosper','v','موفق شدن','/ˈprɑːspər/ · succeed, thrive','May you all live long and prosper.','[["May you all live long and prosper.","ایشالا که همگی عمر طولانی و موفقیت روزافزون داشته باشید."],["The business prospered beneath his guiding hand.","کسب و کار تحت هدایت او رونق گرفت."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:prosperous','prosperous','adj','موفق، ثروتمند','/ˈprɑːspərəs/ · wealthy, flourishing financially','Mark lives in a more prosperous country.','[["Mark lives in a more prosperous country.","مارک در یک کشور مرفه‌تر زندگی می‌کند."],["Algeria needs to become rich and prosperous.","الجزایر باید ثروتمند و مرفه شود."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:provoke','provoke','v','بیرون کشیدن، تحریک کردن','/prəˈvoʊk/ · elicit, arouse, produce, evoke, give rise to','Male homosexual encounters still provoke strong reactions.','[["Male homosexual encounters still provoke strong reactions.","برخوردهای همجنسگرایان مرد هنوز واکنش‌های شدیدی را برمی‌انگیزد."],["He did not provoke them this time.","این بار آنها را تحریک نکرد."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:prowess','prowess','n','تخصص','/ˈpraʊɪs/ · 1)great skill, expertise, 2)bravery in battle','I wouldn''t dare to question your prowess in video games.','[["I wouldn''t dare to question your prowess in video games.","جرات ندارم مهارتت رو تو بازی‌های ویدیویی زیر سوال ببرم."],["His martial arts prowess has already reached a level of sublime perfection.","مهارت او در هنرهای رزمی به سطح والایی از کمال رسیده است."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:radically','radically','adv','به صورت کامل','/ˈrædɪkli/ · completely, fundamentally','He promised to do things radically different.','[["He promised to do things radically different.","او قول داد که کارها را کاملاً متفاوت انجام دهد."],["My life began to radically change.","زندگی من شروع به تغییر اساسی کرد."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:rebound','rebound','v','دوباره به جای اول برگشتن','/rɪˈbaʊnd/ · recover, bounce back','Alessia missed a sitter but, from the rebound, scored a worldie.','[["Alessia missed a sitter but, from the rebound, scored a worldie.","آلیسیا یک ضربه ایستگاهی را از دست داد اما از روی ریباند، یک امتیاز جهانی کسب کرد."],["She went out with him on the rebound.","او در ریباند با او بیرون رفت."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:recharge','recharge','v','دوباره پر کردن','/ˌriːˈtʃɑːrdʒ/ · refill','I need a little time to recharge away from the everyday.','[["I need a little time to recharge away from the everyday.","به کمی زمان نیاز دارم تا از روزمرگی‌ها دور شوم و تجدید قوا کنم."],["It''s time to recharge your energy. Head to bed, please.","وقتشه انرژیتو دوباره شارژ کنی. لطفا برو بخواب."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:reconcile','reconcile','v','سازش کردن، وفق دادن','/ˈrekənsaɪl/ · compromise, tune, restore friendly relations betweenif you reconcile two ideas, situations, or facts, you find a way in which they can both be true or acceptable','John helped his parents reconcile.','[["John helped his parents reconcile.","جان به والدینش کمک کرد تا با هم آشتی کنند."],["Yanni was willing to reconcile.","یانی حاضر به آشتی بود."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:reinforce','reinforce','v','تقویت کردن، کمک کردن','/ˌriːənˈfɔːs/ · strengthen','You should reinforce your argument by giving more facts.','[["You should reinforce your argument by giving more facts.","شما باید استدلال خود را با ارائه حقایق بیشتر تقویت کنید."],["The walls were reinforced with steel.","دیوارها با فولاد تقویت شدند."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:relic','relic','n','یادگار، باقی مانده','/ˈrelɪk/ · remain; remnant; historical object, antique, artifact','Cherish our cultural relics; it is all our duty.','[["Cherish our cultural relics; it is all our duty.","آثار فرهنگی خود را گرامی بداریم؛ این وظیفه همه ماست."],["David will become a relic of the past.","دیوید به یادگاری از گذشته تبدیل خواهد شد."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:reluctance','reluctance','n','بی میلی، اکراه، بیزاری','/rɪˈlʌktəns/ · unwillingness','He agreed to help, but with some reluctance.','[["He agreed to help, but with some reluctance.","او موافقت کرد که کمک کند، اما با کمی اکراه."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:remarkably','remarkably','adv','مقدار قابل ملاحظه، زیاد از حد انتظار','/rɪˈmɑːkəbli/ · surprisingly','Remarkably, they made it on time.','[["Remarkably, they made it on time.","نکته قابل توجه این است که آنها به موقع رسیدند."],["Claudio was a remarkably intelligent man.","کلودیو مردی فوق‌العاده باهوش بود."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:remnant','remnant','n','باقی مانده، بقیه، اثر','/ˈremnənt/ · residue/remains/remaining/left-over, the parts of something that are left after the rest has been destroyed or has disappeared','Only a few remnants of the structure have survived.','[["Only a few remnants of the structure have survived.","تنها چند بقایای این سازه باقی مانده است."],["Archeology is the science that studies the remnants of human civilization.","باستان‌شناسی علمی است که به بررسی آثار به جا مانده از تمدن بشری می‌پردازد."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:render','render','v','ارائه دادن، ساختن، ایجاد کردن','/ˈrendər/ · make','The clause was rendered null and void.','[["The clause was rendered null and void.","بند مذکور باطل و بلااثر اعلام شد."],["You have rendered us invaluable service.","شما خدمات ارزشمندی به ما ارائه داده‌اید."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:rendering','rendering','n','تفسیر، شرح، ارائه','/ˈrendərɪŋ/ · presentation','The prime purpose of the profession is the rendering of a public service.','[["The prime purpose of the profession is the rendering of a public service.","هدف اصلی این حرفه، ارائه خدمات عمومی است."],["Binary space partitioning (BSP) is used in some video games as an alternative graphics rendering technique to raycasting.","پارتیشن‌بندی فضای دودویی (BSP) در برخی از بازی‌های ویدیویی به عنوان یک تکنیک رندر گرافیکی جایگزین برای raycasting استفاده می‌شود."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:resembling','resembling','adj','شبیه به، همانند','approximating','The rock had a shape resembling a human face.','[["The rock had a shape resembling a human face.","این سنگ شکلی شبیه به صورت انسان داشت."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:residual','residual','adj','باقی مانده، پس ماند','/rɪˈzɪdʒuəl/ · remaining','Residual heat stays in the rocks.','[["Residual heat stays in the rocks.","گرمای باقیمانده در سنگ‌ها باقی می‌ماند."],["There is still some residual pain after the operation.","بعد از عمل هنوز مقداری درد باقی مانده است."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:resilient','resilient','adj','ارتجاعی، بازگشت‌پذیر، قابل بازیابی','/rɪˈzɪliənt/ · 1)easy to recover 2)quick to recover','Children are often very resilient.','[["Children are often very resilient.","کودکان اغلب بسیار انعطاف پذیر هستند."],["The economy proved resilient during the crisis.","اقتصاد در طول بحران مقاوم بود."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:retrieve','retrieve','v','پس گرفتن، دوباره بدست آوردن','/rɪˈtriːv/ · bring back','The brain retrieves stored memories when needed.','[["The brain retrieves stored memories when needed.","مغز در صورت نیاز، خاطرات ذخیره شده را بازیابی می‌کند."],["Ziri carefully retrieved the map.","زیری با دقت نقشه را بیرون آورد."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:revive','revive','v','احیا کردن، احیا شدن','/rɪˈvaɪv/ · resuscitate, recover 1)to bring something back after it has not been used or has not existed.2) to become healthy and strong again, or to make someone or something healthy and strong again','It will likely be revived.','[["It will likely be revived.","احتمالاً دوباره احیا خواهد شد."],["Old quarrels are easily revived.","دعواهای قدیمی به راحتی دوباره زنده می‌شوند."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:rigorous','rigorous','adj','سخت، شدید','/ˈrɪɡərəs/ · demanding, harsh','IQ is not a scientifically rigorous concept.','[["IQ is not a scientifically rigorous concept.","ضریب هوشی یک مفهوم علمی دقیق نیست."],["I scrubbed the bathtub rigorously.","وان حمام را با دقت شستم."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:roam','roam','v','پرسه زدن، سرگردان بودن','/rəʊm/ · wander v','I was roaming the woods.','[["I was roaming the woods.","داشتم تو جنگل پرسه می‌زدم."],["The peacock roamed the park.","طاووس در پارک پرسه می‌زد."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:rotate','rotate','v','چرخیدن، دوران کردن','/rəʊˈteɪt/ · turn','The Earth rotates once a day.','[["The Earth rotates once a day.","زمین یک بار در روز می‌چرخد."],["Farmers rotate their crops each year.","کشاورزان هر سال محصولات خود را به تناوب تغییر می‌دهند."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:routinely','routinely','adv','معمولاً','/ruːˈtiːnli/ · commonly','Prisoners in Guantanamo are routinely abused.','[["Prisoners in Guantanamo are routinely abused.","زندانیان گوانتانامو به طور مرتب مورد آزار و اذیت قرار می‌گیرند."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:scatter','scatter','v','پخش کردن، پراکنده شدن، افشاندن، پراکندن','/ˈskæt.ɚ/ · diffuse/disperse, distribute, disperse','Scattered clouds mean heavy rain.','[["Scattered clouds mean heavy rain.","ابرهای پراکنده به معنای باران شدید هستند."],["People scattered in all directions.","مردم به هر سو پراکنده شدند."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:scented','scented','adj','معطر، خوشبو','/ˈsen.tɪd/ · fragrant, fragrant flowersscent (n,v), scent of a woman','Do you like coconut scented candles, kitten?','[["Do you like coconut scented candles, kitten?","بچه گربه، شمع‌های معطر نارگیل دوست داری؟"],["Mary lit a scented candle.","مریم یک شمع معطر روشن کرد."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:scrutiny','scrutiny','n','بررسی دقیق، تحقیق موشکافانه، موشکافی','/ˈskruː.tən.i/ · examination n','The policy came under public scrutiny.','[["The policy came under public scrutiny.","این سیاست مورد توجه عمومی قرار گرفت."],["Politicians are always under public scrutiny.","سیاستمداران همیشه تحت نظارت عمومی هستند."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:seldom','seldom','adv','به ندرت، بسیار نادر','/ˈsel.dəm/ · rare','She seldom engages in group activities.','[["She seldom engages in group activities.","او به ندرت در فعالیت‌های گروهی شرکت می‌کند."],["He seldom picks up a book.","او به ندرت کتابی را در دست می‌گیرد."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sensational','sensational','adj','فوق العاده، بسیار خوب، خاص','/senˈseɪ.ʃən.əl/ · extraordinary','The food at that new restaurant is sensational.','[["The food at that new restaurant is sensational.","غذای آن رستوران جدید فوق‌العاده است."],["William found something sensational to get the reporter.","ویلیام برای جلب نظر خبرنگار، چیز هیجان‌انگیزی پیدا کرد."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:setback','setback','n','شکست، تنزل','/ˈset.bæk/ · failurebarrierobstaclestumbling back','A setback delayed our progress.','[["A setback delayed our progress.","یک شکست، پیشرفت ما را به تأخیر انداخت."],["The project faced a setback.","این پروژه با شکست مواجه شد."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:severity','severity','n','شدت، بشدت، جدیت','/səˈver.ə.ti/ · seriousness','Doctors are worried about the severity of her injuries.','[["Doctors are worried about the severity of her injuries.","پزشکان نگران شدت جراحات او هستند."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:shrink','shrink','v','کوچک شدن یا کردن، آب رفتن','/ʃrɪŋk/ · contract','Can something like that shrink?','[["Can something like that shrink?","آیا چیزی شبیه به آن می‌تواند کوچک شود؟"],["Did you see a shrink?","آیا شما یک کوچک کننده دیدید؟"]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:simulated','simulated','adj','شبیه سازی‌شده، مصنوعی','/ˈsɪm·jəˌleɪ·tɪd/ · artificial','The proposed method is applied to three simulated case studies.','[["The proposed method is applied to three simulated case studies.","روش پیشنهادی بر روی سه مطالعه موردی شبیه‌سازی شده اعمال شده است."],["VR blocks out the physical world and transports the user to a simulated world.","واقعیت مجازی (VR) دنیای فیزیکی را مسدود کرده و کاربر را به یک دنیای شبیه‌سازی شده منتقل می‌کند."]]','t1212',18,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:skeptical','skeptical','adj','شک و تردید، مشکوک، شک','/ˈskep.tɪ.kəl/ · doubting, suspected, doubtful','To start with, I was skeptical.','[["To start with, I was skeptical.","برای شروع، من شک داشتم."],["Gabriel was skeptical about the plan.","گابریل در مورد این نقشه تردید داشت."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:soak','soak','v','خیس کردن، بشدت جذب کردن','/soʊk/ · absorb','Ziri was pretty much soaked in sweat.','[["Ziri was pretty much soaked in sweat.","زیری کاملاً خیس عرق شده بود."],["Benedito soaked in the hot springs'' water.","بندیتو در آب چشمه‌های آب گرم غوطه‌ور شد."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:solitary','solitary','adj','تنها، مجرد، منحصر به فرد، تک','/ˈsɑː.lə.ter.i/ · alone','He was sent to solitary confirnelment for a long time.','[["He was sent to solitary confirnelment for a long time.","او را مدت‌ها به انفرادی فرستادند."],["Now and then, a solitary leaf floats to the ground.","هر از گاهی، یک برگ تنها روی زمین شناور می‌شود."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sparse','sparse','adj','پراکنده','/spɑːrs/ · thinly distributed adj., not rich','Vegetation is sparse in the desert.','[["Vegetation is sparse in the desert.","پوشش گیاهی در بیابان کم است."],["The population of the region is sparse.","جمعیت منطقه کم است."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:spawn','spawn','v','تولید مثل کردن، تخم گذاری کردن، به وجود آوردن','/I)/ · create, produce','This open source code spawned hundreds of projects.','[["This open source code spawned hundreds of projects.","این کد متن‌باز، صدها پروژه را ایجاد کرد."],["Salmon return to their original birthplace to spawn.","ماهی سالمون برای تخم ریزی به زادگاه اصلی خود بازمی گردد."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:specify','specify','v','مشخص کردن','/ˈspes.ə.faɪ/ · state v.','Payments will be made for a specified month.','[["Payments will be made for a specified month.","پرداخت‌ها برای یک ماه مشخص انجام می‌شود."],["There was no need to specify that.","نیازی به تصریح آن نبود."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:spectator','spectator','n','تماشاگر','/spekˈteɪ.tɚ/ · beholder, human viewer','There were over three thousand spectators.','[["There were over three thousand spectators.","بیش از سه هزار تماشاگر حضور داشتند."],["He made the spectators sad.","او تماشاگران را غمگین کرد."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:splendid','splendid','adj','پر زرق و برق، عالی، باشکوه','/ˈsplen.dɪd/ · magnificent adj.','Algeria is known for its splendid natural environment.','[["Algeria is known for its splendid natural environment.","الجزایر به خاطر محیط طبیعی باشکوهش شناخته شده است."],["His nephew was absorbed in the splendid fireworks.","برادرزاده‌اش غرق در آتش‌بازی باشکوه بود."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:spontaneous','spontaneous','adj','خود به خود','/spɑːnˈteɪ.ni.əs/ · impulsive, instinctive, unplanned','It was a spontaneous decision.','[["It was a spontaneous decision.","این یک تصمیم خودجوش بود."],["The audience broke into spontaneous applause.","حضار با تشویق خود به خود شکستند."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:spontaneously','spontaneously','adv','خودبخود','/spɑːnˈteɪ.ni.əs.li/ · automatically adv.','Sami''s phone has spontaneously exploded.','[["Sami''s phone has spontaneously exploded.","گوشی سامی خود به خود منفجر شد."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:spur','spur','v','تحریک کردن، برانگیختن','/spɝː/ · stimulate v.','You spurred me on to do better and better.','[["You spurred me on to do better and better.","تو به من انگیزه دادی تا بهتر و بهتر عمل کنم."],["His sudden decision to resign spurred an investigation.","تصمیم ناگهانی او برای استعفا، تحقیقات را آغاز کرد."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:stabilize','stabilize','v','تثبیت کردن','/ˈsteɪ.bə.laɪz/ · hold in place','Will the economy stabilize after the reforms?','[["Will the economy stabilize after the reforms?","آیا اقتصاد پس از اصلاحات به ثبات خواهد رسید؟"],["The situation in the region has stabilized.","اوضاع در منطقه به ثبات رسیده است."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:staggering','staggering','adj','گیج‌کننده','/ˈstæɡ.ɚ.ɪŋ/ · overwhelming','The desolation left in his wake is staggering.','[["The desolation left in his wake is staggering.","ویرانی به جا مانده از او حیرت‌انگیز است."],["It''s staggering to me to hear this again.","شنیدن دوباره این حرفا برام عجیبه."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:staple','staple','adj','عمده، اساسی، بنیادین','/ˈsteɪ.pəl/ · important','Black jeans are a versatile wardrobe staple.','[["Black jeans are a versatile wardrobe staple.","شلوار جین مشکی یک عنصر همه کاره در کمد لباس است."],["A poster was stapled onto a signpost.","یک پوستر به تابلوی راهنمایی منگنه شده بود."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:stimulate','stimulate','v','انگیختن','/ˈstɪm.jə.leɪt/ · cause, prompt','Music can stimulate memory and emotions.','[["Music can stimulate memory and emotions.","موسیقی می‌تواند حافظه و احساسات را تحریک کند."],["Coffee and tea stimulate me.","قهوه و چای به من انرژی مثبت می‌دهند."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:stride','stride','v','گام‌های بلند برداشتن','/straɪd/ · step','Lorenzo was taking big and long strides.','[["Lorenzo was taking big and long strides.","لورنزو گام‌های بلند و بلندی برمی‌داشت."],["She had such a confident stride.","او با اعتماد به نفس خاصی قدم برمی‌داشت."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:stringent','stringent','adj','دقیق، سخت','/ˈstrɪn.dʒənt/ · strict','Stringent rules govern food production.','[["Stringent rules govern food production.","قوانین سختگیرانه بر تولید مواد غذایی حاکم است."],["The country has stringent rules on immigration.","این کشور قوانین سختگیرانه ای در زمینه مهاجرت دارد."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sturdy','sturdy','adj','محکم','/ˈstɝː.di/ · strong','Take cover under a sturdy table.','[["Take cover under a sturdy table.","زیر یک میز محکم پناه بگیرید."],["Sturdy houses are built with bricks.","خانه‌های محکم با آجر ساخته می‌شوند."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sunk','sunk','adj','غرق، فرو رفته','/ˈsʌmp.tʃu.əs/ · down to the bottom','Exhausted, she sunk into the cushion.','[["Exhausted, she sunk into the cushion.","خسته، در کوسن فرو رفت."],["The ship was sunk on purpose.","کشتی عمداً غرق شد."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:supplemental','supplemental','adj','اضافی، متمم، تکمیلی','/ˌsʌplɪˈmentl/ · adj) additional','Good personal investments may provide supplemental income in retirement.','[["Good personal investments may provide supplemental income in retirement.","سرمایه‌گذاری‌های شخصی خوب می‌توانند درآمد مکملی در دوران بازنشستگی فراهم کنند."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:suppress','suppress','v','سرکوب کردن، فرو نشاندن','/səˈpres/ · v) to end by force; to prevent something from being expressed or known','He took medicine to suppress his allergy symptoms.','[["He took medicine to suppress his allergy symptoms.","او برای سرکوب علائم آلرژی خود دارو مصرف کرد."],["He has a propensity to suppress his feelings.","او عادت دارد احساساتش را سرکوب کند."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:susceptible','susceptible','adj','حساس، مستعد پذیرش','/səˈsep·tə·bəl/ · prone to, be subject to, easily influenced or likely to be hurt by something','Elderly people are more susceptible to illness.','[["Elderly people are more susceptible to illness.","افراد مسن بیشتر مستعد ابتلا به بیماری هستند."],["Everybody is susceptible to an affair.","همه مستعد ابتلا به یک رابطه نامشروع هستند."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:suspend','suspend','v','معلق کردن، آویزان شدن یا کردن','/səˈspend/ · v) float, hang','The judge suspended judgment until January 15.','[["The judge suspended judgment until January 15.","قاضی قضاوت را تا 15 ژانویه به حالت تعلیق درآورد."],["Modern framed glasses, suspended from the ears by earpieces, were uncommon until the 19th century.","عینک‌های قاب‌دار امروزی که با دسته‌ها از گوش آویزان‌اند، تا قرن نوزدهم رایج نبودند."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:swell','swell','v','متورم شدن، پف کردن؛ تورم','/swel/ · v) to become larger and rounder, expand n)enlargement; adj)excellent; very good','My head has swelled up.','[["My head has swelled up.","سرم حسابی ورم کرده."],["Your feet have swelled up.","پاهایت ورم کرده است."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:swiftly','swiftly','adv','سریعا','/ˈswɪft·li/ · adj) quickly','Anna swiftly covered the cockroach with the jar.','[["Anna swiftly covered the cockroach with the jar.","آنا به سرعت سوسک را با شیشه پوشاند."],["With a glance of her, he left swiftly.","با نگاهی گذرا به او، سریع آنجا را ترک کرد."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:tactic','tactic','n','تاکتیک، رزم شیوه','/ˈtæk·tɪk/ · n) strategy','He used devious tactics to sabotage the race.','[["He used devious tactics to sabotage the race.","او از تاکتیک‌های حیله‌گرانه برای خرابکاری در مسابقه استفاده کرد."],["Narcissists employ manipulation tactics to assert their dominance.","خودشیفته‌ها از تاکتیک‌های دستکاری برای اعمال سلطه خود استفاده می‌کنند."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:tame','tame','adj','اهلی','/teɪm/ · domesticate','Gods created women to tame men.','[["Gods created women to tame men.","خدایان زنان را آفریدند تا مردان را رام کنند."],["Can a jackal be tamed?","آیا شغال را می‌توان رام کرد؟"]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:tangible','tangible','adj','ملموس، محسوس','/ˈtæn·dʒə·bəl/ · material, physical, real, concrete','The project produced tangible benefits.','[["The project produced tangible benefits.","این پروژه مزایای ملموسی را به همراه داشت."],["We need tangible results, not promises.","ما به نتایج ملموس نیاز داریم نه وعده."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:taper','taper','v','مخروطی شدن، باریک شدن','/ˈteɪ·pər/ · diminish','In the tumbler, the cylinder form is tapered.','[["In the tumbler, the cylinder form is tapered.","در لیوان، شکل استوانه مخروطی است."],["He tapered off to one cigarette a day.","او مصرف سیگار را به روزی یک نخ کاهش داد."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:tempting','tempting','adj','وسوسه‌انگیز','/ˈtemp.tɪŋ/ · appealing','This offer has nothing tempting about it.','[["This offer has nothing tempting about it.","این پیشنهاد هیچ چیز وسوسه‌انگیزی ندارد."],["The smell of this cake is tempting.","بوی این کیک وسوسه‌انگیز است."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:terminated','terminated','adj','تمام‌شده، پایان یافته','finished','Your connection to the server was terminated.','[["Your connection to the server was terminated.","اتصال شما به سرور قطع شد."],["We have terminated your insurance contract.","ما قرارداد بیمه شما را فسخ کرده‌ایم."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:thrill','thrill','n','شوق و شعف، شور، هیجان','/θrɪl/ · excitement','Science experiments thrill my inquisitive mind.','[["Science experiments thrill my inquisitive mind.","آزمایش‌های علمی ذهن کنجکاو مرا به وجد می‌آورند."],["I embarked on a thrilling adventure.","من وارد یک ماجراجویی هیجان‌انگیز شدم."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:tract','tract','n','وسعت','/trækt/ · (~of land), area','Have you ever been treated for a urinary tract infection?','[["Have you ever been treated for a urinary tract infection?","آیا تا به حال برای عفونت ادراری تحت درمان قرار گرفته‌اید؟"],["Millions of beneficial organisms live in the human digestive tract.","میلیون‌ها موجود زنده مفید در دستگاه گوارش انسان زندگی می‌کنند."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:traumatic','traumatic','adj','زخمی، جراحتی، تخریب زا، ناگوار','/traumatic/ · upsetting, If an experience is traumatic, it causes you severe emotional shock and upset','You had a very traumatic experience.','[["You had a very traumatic experience.","شما یک تجربه بسیار آسیب‌زا داشتید."],["Ziri has had a traumatic night.","زیری شب دردناکی را پشت سر گذاشته است."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:traverse','traverse','v','گذشتن از، پیمودن','/trəˈvɝːs/ · cross','There must be some way of traversing the river.','[["There must be some way of traversing the river.","باید راهی برای عبور از رودخانه وجود داشته باشد."],["That path can easily be traversed by foot.","آن مسیر را می‌توان به راحتی با پای پیاده طی کرد."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:turbulent','turbulent','adj','آشفته، مضطرب','/ˈtɜːrbjələnt/ · agitated','Algeria is going through turbulent times.','[["Algeria is going through turbulent times.","الجزایر روزهای پرتلاطمی را پشت سر می‌گذارد."],["That day was very turbulent.","آن روز خیلی آشفته بود."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ubiquitous','ubiquitous','adj','فراگیر، همه جا حاضر','/juːˈbɪkwɪtəs/ · common','Smartphones are now ubiquitous.','[["Smartphones are now ubiquitous.","گوشی‌های هوشمند اکنون در همه جا حاضر هستند."],["Smartphones have become ubiquitous in modern life.","گوشی‌های هوشمند در زندگی مدرن همه جا حاضر شده اند."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:undertake','undertake','v','به عهده گرفتن، متعهد شدن','/ˌʌndəˈteɪk/ · attempt','Sometimes I undertake more projects than I can finish.','[["Sometimes I undertake more projects than I can finish.","گاهی اوقات من بیش از آنچه می‌توانم به پایان برسانم پروژه‌هایی را انجام می‌دهم."],["The university undertook a major research project.","دانشگاه یک پروژه تحقیقاتی بزرگ را انجام داد."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:undertaking','undertaking','n','متعهد','/ˈʌn.dɚˌteɪ.kɪŋ/ · enterprise','They are undertaking a trip around the world in eighty days!','[["They are undertaking a trip around the world in eighty days!","آنها در حال انجام سفری به دور دنیا در هشتاد روز هستند!"],["That would sound the death knell for many industrial undertakings.","این امر ناقوس مرگ بسیاری از شرکت‌های صنعتی را به صدا در خواهد آورد."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:uneasy','uneasy','adj','مضطرب، ناراحت','/ʌnˈiːzi/ · unstable','This place gives off very uneasy vibes.','[["This place gives off very uneasy vibes.","این مکان حس و حال بسیار ناخوشایندی را القا می‌کند."],["Santiago was uneasy at the dining table.","سانتیاگو سر میز ناهارخوری معذب بود."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:universally','universally','adv','عموماً','/ˌjuːnəˈvɜːsəli/ · without exception','I love how universally applicable these lyrics are.','[["I love how universally applicable these lyrics are.","من عاشق این هستم که این اشعار چقدر جهانی و قابل اجرا هستند."],["It is a truth universally acknowledged.","این حقیقتی است که مورد اذعان جهانیان قرار گرفته است."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:unleash','unleash','v','رها کردن، از بند باز کردن','/ʌnˈliːʃ/ · release','How much democracy can a B-52 unleash in a single flight?','[["How much democracy can a B-52 unleash in a single flight?","یک بمب افکن B-52 با یک پرواز چقدر می‌تواند دموکراسی را به نمایش بگذارد؟"],["The fire burned through the forest like a monster unleashed.","آتش مانند هیولایی رها شده، جنگل را در بر گرفت."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:vaguely','vaguely','adv','مبهم','/ˈveɪɡli/ · slightly','I vaguely remember what happened to me.','[["I vaguely remember what happened to me.","کم کم یادم میاد چی به سرم اومد."],["I''m vaguely familiar with it.","من به طور مبهمی با آن آشنا هستم."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:vanish','vanish','v','ناپدید شدن','/ˈvænɪʃ/ · disappear','My willpower has vanished, replaced by resignation.','[["My willpower has vanished, replaced by resignation.","اراده‌ام از بین رفته و جایش را به تسلیم داده است."],["He vanished a couple of hours later.","او چند ساعت بعد ناپدید شد."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:variability','variability','n','تغییرپذیری','/ˈveəriəbəl/ · tendency to change','Farmers have to get used to dealing with the variability of the weather.','[["Farmers have to get used to dealing with the variability of the weather.","کشاورزان باید به سازگاری با تغییرات آب و هوایی عادت کنند."],["Herbal supplements sold in drugstores have poor quality control and high content variability.","مکمل‌های گیاهی که در داروخانه‌ها فروخته می‌شوند، کنترل کیفیت ضعیفی دارند و ترکیبات آنها بسیار متنوع است."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:versatile','versatile','adj','همه کاره، تطبیق‌پذیر','/ˈvɜːsətaɪl/ · adaptable, competent /all-around','He is a versatile actor.','[["He is a versatile actor.","او یک بازیگر همه کاره است."],["Eggs are a versatile ingredient.","تخم مرغ یک ماده همه کاره است."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:viability','viability','n','زیست پذیری، قابلیت زیست','/ˌvaɪəˈbɪləti/ · ability to exist','The viability of this approach is a matter of some debate.','[["The viability of this approach is a matter of some debate.","امکان‌سنجی این رویکرد، موضوع بحث و جدل است."],["The viability of the project needs to be studied.","لازم است امکان‌سنجی اجرای طرح بررسی شود."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:vibrant','vibrant','adj','پر جنب و جوش','/ˈvaɪbrənt/ · vivid','The garden featured vibrant rosemary plants.','[["The garden featured vibrant rosemary plants.","این باغ شامل گیاهان رزماری پر جنب و جوش بود."],["Algeria possesses a young vibrant population.","الجزایر دارای جمعیتی جوان و پویا است."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:vigorous','vigorous','adj','نیرومند، زورمند، قوی، شدید','/ˈvɪɡərəs/ · active, energetic, strong','Ivy is a pretty vigorous grower.','[["Ivy is a pretty vigorous grower.","پیچک گیاهی بسیار پرانرژی است."],["Santiago washed his body vigorously.","سانتیاگو بدنش را با شور و شوق شست."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:vivid','vivid','adj','روشن، سرزنده، واضح','/ˈvɪvɪd/ · bright','Is the house vivid red or pale red?','[["Is the house vivid red or pale red?","آیا خانه قرمز پررنگ است یا قرمز کم‌رنگ؟"],["This painter carefully chooses the most vivid colours.","این نقاش با دقت رنگ‌های زنده را انتخاب می‌کند."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:wary','wary','adj','بسیار محتاط، با ملاحظه، هشیار','/ˈweri/ · cautious','I''m a little wary of people who punctuate their text messages.','[["I''m a little wary of people who punctuate their text messages.","من کمی نسبت به افرادی که پیامک‌هایشان را با نقطه‌گذاری تمام می‌کنند، محتاط هستم."],["My parents always told me to be wary of strangers.","پدر و مادرم همیشه به من می‌گفتند که از غریبه‌ها دوری کنم."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:whereby','whereby','adv','که به موجب آن، نظر به این که، به وسیله آن','/werˈbaɪ/ · through a process in which','A plan whereby we can make lots of money.','[["A plan whereby we can make lots of money.","طرحی که به موجب آن بتوانیم پول زیادی به دست آوریم."],["Titles also provide guidelines whereby people know how to address others.","عنوان‌ها همچنین رهنمودهایی فراهم می‌کنند که به‌واسطهٔ آن‌ها مردم می‌دانند دیگران را چگونه خطاب کنند."]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:withstand','withstand','v','تحمل کردن، مقاومت کردن در برابر','/ˈstʊd/ · resist, tolerate','He was unable to withstand the torture.','[["He was unable to withstand the torture.","او قادر به تحمل شکنجه نبود."],["Do you think trust can withstand anything?","فکر می‌کنی اعتماد می‌تونه در برابر هر چیزی مقاومت کنه؟"]]','t1212',19,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:a-solicitation-of','a solicitation of','phr','درخواست از کسی برای کمک، پول، اطلاعات و غیره','/səˌlɪsɪˈteɪʃən/ · an invitation of','The charity sent out a solicitation of funds to its members.','[["The charity sent out a solicitation of funds to its members.","این موسسه خیریه برای اعضای خود درخواست کمک مالی ارسال کرد."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:aberrant','aberrant','adj','غیر معمول، غیر طبیعی','/əˈberənt/ · abnormal, deviating from what is normal or typical or from an established rule; abnormal or deviant','Scientists studied the aberrant behavior of the birds during the storm.','[["Scientists studied the aberrant behavior of the birds during the storm.","دانشمندان رفتار غیرعادی پرندگان را در طول طوفان بررسی کردند."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:abort','abort','v','متوقف کردن یه فعالیت','/əˈbɔːrt/ · quit, to stop an activity because it would be difficult or dangerous to continue it','My mother nearly aborted me at my birth.','[["My mother nearly aborted me at my birth.","مادرم موقع تولد نزدیک بود سقطم کنه."],["The mission had to be aborted.","ماموریت باید لغو می‌شد."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:adherent','adherent','n','طرفدار، هواخواه','/ədˈhɪrənt/ · supporter','The Mormons have outlawed polygamy, but some adherents still practice it.','[["The Mormons have outlawed polygamy, but some adherents still practice it.","مورمون‌ها چندهمسری را ممنوع کرده‌اند، اما برخی از پیروان آنها هنوز به آن پایبندند."],["Adherents of various religions live in Belarus.","پیروان ادیان مختلف در بلاروس زندگی می‌کنند."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:adjacency','adjacency','n','مجاورت، نزدیکی','nearing','The adjacency pair has five basic characteristics.','[["The adjacency pair has five basic characteristics.","جفت مجاورت پنج ویژگی اساسی دارد."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:aggravate','aggravate','v','خشمگین کردن، اذیت کردن، وضعیتی بدی یا بیماری یا جراحتی را بدتر کردن','/ˈæɡrəveɪt/ · 1) to make someone angry or annoyed; irritate, annoy, 2) increase, to make a bad situation, an illness, or an injury worse','Poor diet can aggravate the condition.','[["Poor diet can aggravate the condition.","رژیم غذایی نامناسب می‌تواند این بیماری را تشدید کند."],["Stress can aggravate skin problems.","استرس می‌تواند مشکلات پوستی را تشدید کند."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:aggregation','aggregation','n','گروه، توده','/ˌægrɪˈgeɪʃən/ · group, when different things are combined to make a whole, or the whole that is produced','The aggregation of player statistics was completed in two seconds.','[["The aggregation of player statistics was completed in two seconds.","جمع آوری آمار بازیکنان در دو ثانیه انجام شد."],["A nibble is a data aggregation that comprises 4 bits, also called a half-byte, tetrade or quartet.","نیبل (Nibble) یک تجمیع داده است که شامل ۴ بیت می‌شود و به آن نیم بایت (Half-byte)، تتراد (Tetrade) یا کوارتت (Quartet) نیز می‌گویند."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:allude-to','allude to','phr','اشاره به، ذکر کردن','/əˈlud tə/ · refer to, suggest, cite','I have never alluded to marriage.','[["I have never alluded to marriage.","من هیچ وقت به ازدواج اشاره نکرده‌ام."],["His letter alludes to the event.","نامه او به این رویداد اشاره دارد."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ambivalent','ambivalent','adj','دودل، دوسوگرا، دارای احساسات متضاد','/æmˈbɪvələnt/ · uncertain, unsure, doubtful, mixed (having mixed feelings ), not sure whether you want or like something or not','She felt ambivalent about moving.','[["She felt ambivalent about moving.","او در مورد حرکت احساس دوگانگی می‌کرد."],["Many voters remain ambivalent about the new law.","بسیاری از رای دهندگان در مورد قانون جدید تردید دارند."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:amplify','amplify','v','تقویت کردن، توسعه دادن، توضیح دادن','/ˈæmplɪfaɪ/ · 1) magnify, to increase the effects or strength of something 2) to explain something that you have said by givingmation a more inforbout it','We need to amplify their voice.','[["We need to amplify their voice.","ما باید صدای آنها را تقویت کنیم."],["Try to amplify your opportunity.","سعی کنید فرصت خود را تقویت کنید."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:annihilate','annihilate','v','نابود کردن','/əˈnaɪəleɪt/ · completely remove, destroy, eradicate - to destroy something or someone completely','The natives need to be annihilated.','[["The natives need to be annihilated.","بومیان باید نابود شوند."],["The Giants annihilated the Dodgers.","جاینتز، داجرز را نابود کرد."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:antiseptic','antiseptic','n','پاکیزه و تمیز، ضدعفونی‌کننده','/ˌæntəˈseptɪk/ · clean (adj)completely free from infection-(n) a medicine that you put onto a wound to stop it from becoming infected','If the throat is very inflamed, an antiseptic gargle should be used.','[["If the throat is very inflamed, an antiseptic gargle should be used.","اگر گلو بسیار ملتهب باشد، باید از غرغره ضدعفونی‌کننده استفاده شود."],["The effective application of antiseptics is an important matter in the prevention of hospital infections.","استفاده موثر از ضدعفونی‌کننده‌ها، عامل مهمی در پیشگیری از عفونت‌های بیمارستانی است."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:antithesis','antithesis','n','متناقض','/siːz/ · opposite-the complete opposite of something','A moral monopoly is the antithesis of a marketplace of ideas.','[["A moral monopoly is the antithesis of a marketplace of ideas.","انحصار اخلاقی، نقطه مقابل بازار ایده‌هاست."],["Cosmos is the antithesis of chaos.","کیهان نقطه مقابل آشوب است."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:antler','antler','n','شاخ گوزن','/ˈæntlər/ · horn-one of two horns of a male','The creature had antlers atop its head.','[["The creature had antlers atop its head.","این موجود شاخ‌هایی بالای سرش داشت."],["He was looking for discarded antlers.","او دنبال شاخ‌های گوزنِ دور انداخته شده می‌گشت."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:appreciable','appreciable','adj','قابل تحسین','/əˈprēSH(ē)əb(ə)l/ · noticeable-large or important enough to be noticed','There has been an appreciable increase in the price of food this year.','[["There has been an appreciable increase in the price of food this year.","امسال افزایش قیمت مواد غذایی قابل توجه بوده است."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:arduous','arduous','adj','دشوار','/ˈɑːdjʊəs/ · difficult-involving or requiring strenuous effort; difficult and tiring','He mastered these words through the arduous consultation of the dictionary.','[["He mastered these words through the arduous consultation of the dictionary.","او این کلمات را از طریق مراجعه‌ی طاقت‌فرسا به فرهنگ لغت فرا گرفت."],["Pioneer men and women had an arduous life, and their children, too.","مردان و زنان پیشگام، و همچنین فرزندانشان، زندگی سختی داشتند."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:assimilate','assimilate','v','همانند ساختن','/əˈsɪmɪleɪt/ · combine-to become part of a group, country, society, etc., or to make someone or something become part of a group, country, society','Immigrants often assimilate into new cultures.','[["Immigrants often assimilate into new cultures.","مهاجران اغلب با فرهنگ‌های جدید جذب می‌شوند."],["The body assimilates nutrients from food.","بدن مواد مغذی را از غذا جذب می‌کند."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:assorted','assorted','adj','گوناگون، متنوع، جورواجور','/əˈsɔːtɪd/ · various- various sorts put together','The butcher shop sells assorted cuts of meat.','[["The butcher shop sells assorted cuts of meat.","قصابی، گوشت‌های مختلف و متنوعی می‌فروشد."],["This box contains assorted chocolates.","این جعبه شامل شکلات‌های متنوع است."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:astonish','astonish','v','متعجب ساختن','/əˈstɒnɪʃ/ · surprise-surprise or impress (someone) greatly','Boris was astonished by the results.','[["Boris was astonished by the results.","بوریس از نتایج شگفت زده شد."],["He was too astonished to reply.","او آنقدر شگفت‌زده بود که نتوانست پاسخی بدهد."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:astoundingly','astoundingly','adv','به طرز شگفت انگیزی','/əˈstaʊn.dɪŋ.li/ · incredibly','The young pianist played astoundingly well for her age.','[["The young pianist played astoundingly well for her age.","این پیانیست جوان با توجه به سنش، به طرز شگفت انگیزی خوب می‌نواخت."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:astute','astute','adj','باهوش','/əˈstuːt/ · clever','He is an astute businessman.','[["He is an astute businessman.","او یک تاجر زیرک است."],["She is an astute observer of human behavior.","او ناظر زیرک رفتار انسان است."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:attainment','attainment','n','دستیابی، دستاورد','/əˈteɪnmənt/ · 1) achievement; success in achieving something or reaching a particular level.2)something that you have succeeded in achieving or learning, such as a skill','The attainment of a university degree opened many doors for him.','[["The attainment of a university degree opened many doors for him.","اخذ مدرک دانشگاهی درهای زیادی را به روی او گشود."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:attest','attest','v','گواهی دادن','/əˈtest/ · confirm, testify, to show or prove that something is true','The notary acted as an attester of the contract.','[["The notary acted as an attester of the contract.","دفتردار به عنوان گواهی دهنده قرارداد عمل کرد."],["I will attest that I did not hear that.","من گواهی می‌دهم که چنین چیزی نشنیده‌ام."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:augment','augment','v','افزایش دادن سایز یا حجم چیزی','/ɑːɡˈment/ · increase, to increase the "size or value" of something by adding something to it','Peasants often have a secondary activity to augment their income.','[["Peasants often have a secondary activity to augment their income.","دهقانان اغلب یک فعالیت ثانویه برای افزایش درآمد خود دارند."],["Augmented reality enables the user to interact with the real world superimposed by virtual objects.","واقعیت افزوده به کاربر این امکان را می‌دهد که با دنیای واقعی که توسط اشیاء مجازی احاطه شده است، تعامل داشته باشد."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:beckon','beckon','v','دعوت کردن','/ˈbekən/ · invite','The policeman beckoned to me with his forefinger.','[["The policeman beckoned to me with his forefinger.","پلیس با انگشت اشاره‌اش به من اشاره کرد."],["She beckoned me to come in.","با اشاره از من خواست که داخل شوم."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:bombard','bombard','v','بمباران کردن','/bɑːmˈbɑːrd/ · assault, strike, assail','We''re constantly bombarded with images of success.','[["We''re constantly bombarded with images of success.","ما دائماً با تصاویر موفقیت بمباران می‌شویم."],["Mars is bombarded by cosmic radiation.","مریخ در معرض تشعشعات کیهانی قرار دارد."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:brittle','brittle','adj','شکننده','/ˈbrɪtl/ · breakable, fragile','I don''t like peanut brittle. I love it!','[["I don''t like peanut brittle. I love it!","من از تردی بادام زمینی خوشم نمیاد. عاشقشم!"],["Metals can become brittle at low temperatures.","فلزات در دماهای پایین می‌توانند شکننده شوند."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:burgeon','burgeon','v','درامدن، شروع برشدکردن','/ˈbɜːrdʒən/ · expand, to grow or develop quickly','The empire expanded eastward, in search of resources for its burgeoning textile industry.','[["The empire expanded eastward, in search of resources for its burgeoning textile industry.","امپراتوری در جستجوی منابع برای صنعت نساجی رو به رشد خود، به سمت شرق گسترش یافت."],["Algeria needs raw materials for its burgeoning industry.","الجزایر برای صنعت رو به رشد خود به مواد اولیه نیاز دارد."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:bustling','bustling','adj','شلوغ، زنده','/ˈbʌsəlɪŋ/ · lively','Algiers is a bustling city.','[["Algiers is a bustling city.","الجزیره شهری شلوغ و پرجنب‌وجوش است."],["Tokyo is bustling with life.","توکیو پر از شور و شوق و زندگی است."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:chancy','chancy','adj','تصادفی، پرمخاطره','/ˈtʃænsi/ · risky','Investing into stocks is a highly chancy endeavor.','[["Investing into stocks is a highly chancy endeavor.","سرمایه‌گذاری در سهام یک تلاش بسیار ریسک‌پذیر است."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:chisel','chisel','v','تراشیدن، حک کردن','/ˈtʃɪzəl/ · carve','The chisel slipped, and I cut my hand.','[["The chisel slipped, and I cut my hand.","اسکنه لیز خورد و دستم را بریدم."],["Have you got a chisel in your toolbox?","آیا در جعبه ابزار خود اسکنه دارید؟"]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:chronically','chronically','adv','دائماً','/ˈkrɑ:nɪkli/ · constantly, consistently','Police districts are chronically understaffed.','[["Police districts are chronically understaffed.","حوزه‌های پلیس به طور مزمن با کمبود نیرو مواجه هستند."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:circuitous','circuitous','adj','غیرمستقیم','/sɜːrˈkjuːɪtəs/ · indirect','The train made a circuitous route back to the city center every day.','[["The train made a circuitous route back to the city center every day.","قطار هر روز مسیر غیرمستقیمی را به سمت مرکز شهر طی می‌کرد."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:collide-with','collide with','phr','برخورد با، اصابت','/kəˈlaɪd/ · run into, hit','Our bus collided with a lorry.','[["Our bus collided with a lorry.","اتوبوس ما با یک کامیون تصادف کرد."],["The truck collided with the bus.","کامیون با اتوبوس برخورد کرد."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:compel','compel','v','وادار کردن، مجبور کردن','/kəmˈpel/ · push','Shall we compel you to accept it?','[["Shall we compel you to accept it?","آیا ما شما را مجبور به پذیرش آن کنیم؟"],["What compels you to meow?","چی تو رو مجبور به میو میو کردن می‌کنه؟"]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:conceiving','conceiving','adj','با ملاحظه ی، درک','/kəˈnaɪvɪŋ/ · considering','Early engineers had difficulty conceiving of a machine that could fly.','[["Early engineers had difficulty conceiving of a machine that could fly.","مهندسان اولیه در تصور ماشینی که بتواند پرواز کند، مشکل داشتند."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:conducive','conducive','adj','منجر (شونده)، موجب، باعث','/kənˈduː.sɪv/ · contributive','A quiet room is conducive to study.','[["A quiet room is conducive to study.","یک اتاق آرام برای مطالعه مساعد است."],["The warm climate is conducive to growing fruit.","آب و هوای گرم برای رشد میوه مناسب است."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:confine','confine','v','محدود کردن','/kənˈfaɪn/ · limit, keep or restrict within limits-~ to=limited to, restricted','It wasn''t easy to sleep in such a confined space.','[["It wasn''t easy to sleep in such a confined space.","خوابیدن در چنین فضای محدودی آسان نبود."],["The exploration of an ancient Mayan burial site in Honduras uncovered the tomb of a young woman, confined there for 1,400 years.","کاوش در یک گورگاه باستانی مایاها در هندوراس، آرامگاه زن جوانی را آشکار کرد که ۱۴۰۰ سال در آن‌جا محبوس بود."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:congeal','congeal','v','یخ بستن، سفت کردن','/kənˈdʒiːl/ · solidify','If you leave it for too long, it will congeal.','[["If you leave it for too long, it will congeal.","اگر آن را برای مدت طولانی رها کنید، سفت می‌شود."],["Frozen water is called ice; dew congealed is called frost.","آب منجمد را یخ و شبنم منجمد را برفک می‌نامند."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:congregate','congregate','v','جمع کردن','/ˈkɒŋɡrɪɡeɪt/ · gather, assemble','The gazelles congregated in a small huddle.','[["The gazelles congregated in a small huddle.","غزال‌ها در یک گروه کوچک جمع شدند."],["Eagles congregate here in the spring.","عقاب‌ها در بهار اینجا جمع می‌شوند."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:consequent','consequent','adj','نتیجه بخش، برآیند','/ˈkɒnsəkwənt/ · resulting, later, resultant','The police might see a crime as it was happening or use the video to help in any consequent investigations.','[["The police might see a crime as it was happening or use the video to help in any consequent investigations.","پلیس ممکن بود جرمی را در حین وقوع ببیند یا از ویدئو برای کمک به تحقیقات بعدی استفاده کند."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:consequential','consequential','adj','مهم، قابل توجه','/ˌkɒnsəˈkwenʃəl/ · significant','All elections are important. But we know in our bones this one is more consequential.','[["All elections are important. But we know in our bones this one is more consequential.","همه انتخابات مهم هستند. اما ما با تمام وجود می‌دانیم که این یکی مهم‌تر است."],["Tom wanted to do something consequential for once.","تام می‌خواست برای یک بار هم که شده کاری مهم انجام دهد."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:constrain','constrain','v','محدود کردن، مقید کردن، ملزم کردن، جلوگیری کردن، مهار کردن','/kənˈstreɪn/ · restrict, limit','Like most autistic children, Shawn likes repetition, and he can’t constrain his behavior.','[["Like most autistic children, Shawn likes repetition, and he can’t constrain his behavior.","مانند بیشتر کودکان اوتیسمی، شان تکرار را دوست دارد و نمی‌تواند رفتارش را مهار کند."],["We are constrained to and restrained from an action.","ما به انجام کاری مقید و از آن منع شده‌ایم."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:constraint','constraint','n','الزام، اجبار، قید، محدودیت، وادارسازی، جبر','/kənˈstreɪnt/ · limit, restriction','Constraints on spending have forced the company to rethink its plans.','[["Constraints on spending have forced the company to rethink its plans.","محدودیت‌های مخارج، شرکت را مجبور کرده تا در برنامه‌های خود تجدید نظر کند."],["Constraints can inspire innovative thinking.","محدودیت‌ها می‌توانند الهام بخش تفکر نوآورانه باشند."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:contiguous','contiguous','adj','مجاور، هم‌مرز، چسبیده به هم، متصل','/kənˈtɪɡ.ju.əs/ · neighboring','I just acquired some land that''s contiguous to your farm.','[["I just acquired some land that''s contiguous to your farm.","من به تازگی زمینی را که مجاور مزرعه شماست، خریداری کرده‌ام."],["For the contiguous 48 states, 7 of the 10 warmest years on record have occurred since 1998.","برای ۴۸ ایالت مجاور، ۷ سال از ۱۰ سال گرم ثبت شده از سال ۱۹۹۸ به بعد رخ داده‌اند."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:contrive','contrive','v','طرح‌ریزی کردن، تدبیر کردن، نقشه کشیدن؛ (با مهارت) ساختن، ابداع کردن','/kənˈtraɪv/ · create or invent in a skilful way','He kicked off his bonds, which he had somehow contrived to loosen.','[["He kicked off his bonds, which he had somehow contrived to loosen.","او قید و بندهایی را که به نحوی برای شل کردنشان تدبیر کرده بود، با لگد باز کرد."],["Yes, I know it''s a contrived example, but you get the idea.","بله، می‌دانم که مثالی تصنعی است، اما منظورم را می‌فهمید."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:converging','converging','adj','همگرا شونده، همسان شونده','/kənˈvɝːdʒɪŋ/ · concentrating','Converging series of numbers are finite.','[["Converging series of numbers are finite.","سری‌های همگرا از اعداد متناهی هستند."],["We''re converging, you and I.","ما داریم به هم نزدیک میشیم، من و تو."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:copious','copious','adj','فراوان، بسیار، خیلی، وافر، متنابه، زیاد','/ˈkoʊ.pi.əs/ · plentiful, ample, abundant','I found the suites capacious, the sofas commodious, the sandwiches copious.','[["I found the suites capacious, the sofas commodious, the sandwiches copious.","سوئیت‌ها را جادار، مبل‌ها را جادار و ساندویچ‌ها را فراوان یافتم."],["Alberto started packing up his copious amounts of equipment.","آلبرتو شروع به جمع کردن وسایل فراوانش کرد."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:correlate','correlate','v','همبستگی داشتن، لازم و ملزوم بودن، بستگی داشتن، هم وابستگی داشتن','/ˈkɔːr.ə.leɪt/ · match','High birthrates are correlated with poverty, while low birthrates are correlated with wealth and education.','[["High birthrates are correlated with poverty, while low birthrates are correlated with wealth and education.","نرخ بالای زاد و ولد با فقر همبستگی دارد، در حالی که نرخ پایین زاد و ولد با ثروت و تحصیلات همبستگی دارد."],["Some of the work in the workbook doesn''t correlate with the readings in the textbook.","برخی از مطالب کتاب کار با مطالب کتاب درسی همخوانی ندارند."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:correspondingly','correspondingly','adv','بهمان نسبت، همانطور، متقابلاً','/ˌkɔːr.əˈspɑːn.dɪŋ.li/ · accordingly','Prices rose and wages increased correspondingly.','[["Prices rose and wages increased correspondingly.","قیمت‌ها بالا رفت و به همان نسبت دستمزدها هم افزایش یافت."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:corroborate','corroborate','v','تایید کردن، اثبات کردن','/kəˈrɑː.bə.reɪt/ · confirm','Other studies corroborate these findings.','[["Other studies corroborate these findings.","مطالعات دیگر این یافته‌ها را تایید می‌کنند."],["The witness corroborated her story.","شاهد داستان او را تایید کرد."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:countervail','countervail','v','خنثی کردن، جبران کردن، مقابله کردن','/ˈkaʊntəˈveɪl/ · compensate, oppose, neutralize','Countervailing opinions have sadly prevented me from instituting martial law.','[["Countervailing opinions have sadly prevented me from instituting martial law.","متأسفانه نظرات مخالف مانع از برقراری حکومت نظامی توسط من شده است."],["What will countervail the power of the crown?","چه چیزی قدرت تاج و تخت را خنثی خواهد کرد؟"]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:crucially','crucially','adv','بطورقطعی، قطعاً','/ˈkruː.ʃəl.i/ · decisively, definitely','Crucially, the vaccine can be stored without a refrigerator.','[["Crucially, the vaccine can be stored without a refrigerator.","نکته مهم این است که واکسن را می‌توان بدون یخچال نگهداری کرد."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:cueing','cueing','n','سخن رهنما، ایماء، اشاره برای راهنمایی','/ˈkjuːɪŋ/ · hint, clue','This interview has been cueing her up for a run in the next election.','[["This interview has been cueing her up for a run in the next election.","این مصاحبه او را برای شرکت در انتخابات بعدی آماده کرده است."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:culminate','culminate','phr','به انتها رسیدن، به اوج رسیدن، به حد اعلا رسیدن','/ˈkʌlməneɪt/ · reach a climax or peak','I hope this year will culminate in something good.','[["I hope this year will culminate in something good.","امیدوارم امسال به یه اتفاق خوب ختم بشه."],["The celebrations culminated in a spectacular fireworks display.","این جشن با یک نمایش آتش‌بازی باشکوه به پایان رسید."]]','t1212',20,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:culmination','culmination','n','اوج، اوگ، فرازینگاه، منتهی درجه، سرانجام','/ˌkʌl.məˈneɪ.ʃən/ · high point, zenith, apex, crest','This is the culmination of a long journey.','[["This is the culmination of a long journey.","این نقطه اوج یک سفر طولانی است."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:cumbersome','cumbersome','adj','سخت کاربرد، دست و پا گیر، گت و گنده','/ˈkʌm.bɚ.səm/ · awkward, clumsy, unwieldy; slow, difficult and heavy','The old system was cumbersome.','[["The old system was cumbersome.","سیستم قدیمی دست و پا گیر بود."],["The application process is cumbersome and slow.","روند درخواست دست و پا گیر و کند است."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:dangle','dangle','v','تاب خوردن، (روی تاب) آویزان کردن یا بودن','/ˈdæŋ.ɡəl/ · hang','The bat dangled from a branch, sleeping peacefully.','[["The bat dangled from a branch, sleeping peacefully.","خفاش از شاخه‌ای آویزان بود و آرام خوابیده بود."],["They dangled their feet in the water.","پاهایشان را در آب آویزان کردند."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:decimate','decimate','v','نابود کردن، تلفات سنگین وارد کردن','/ˈdes.ə.meɪt/ · destroy','The cavaliers were decimated by the artillery.','[["The cavaliers were decimated by the artillery.","سواران توسط توپخانه نابود شدند."],["Bruno learnt that humanity had been decimated.","برونو فهمید که بشریت نابود شده است."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:decimation','decimation','n','خرابی، ویرانی','/ˌdes.əˈmeɪ.ʃən/ · destruction','The disease caused the decimation of the population.','[["The disease caused the decimation of the population.","این بیماری باعث نابودی جمعیت شد."],["The army suffered a terrible decimation.","ارتش متحمل تلفات وحشتناکی شد."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:deflect','deflect','v','منحرف کردن یا شدن، ورتابه کردن یا شدن، کژراه کردن یا شدن','/dɪˈflekt/ · redirect','He deflected the ball with a diving header.','[["He deflected the ball with a diving header.","او با یک ضربه سر شیرجه‌ای توپ را دفع کرد."],["Deflect any question related to your personal life.","از هر سوالی که مربوط به زندگی شخصی شماست، طفره بروید."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:demography','demography','n','جمعیت‌شناسی، اطلاعات آماری جمعیت (سن، جنس و ...)','/dɪˈmɒɡrəfi/ · (study of)population','Due to its geography and demography, conquering Panjshir by force is considered extremely difficult.','[["Due to its geography and demography, conquering Panjshir by force is considered extremely difficult.","با توجه به جغرافیا و جمعیت‌شناسی پنجشیر، فتح آن با زور بسیار دشوار تلقی می‌شود."],["Tom just finished writing a 300-page treatise on demography.","تام به تازگی نوشتن یک رساله ۳۰۰ صفحه‌ای در مورد جمعیت‌شناسی را تمام کرده است."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:dependable','dependable','adj','قابل اعتماد','/dɪˈpɛndəb(ə)l/ · reliable','She is a dependable worker who always finishes on time.','[["She is a dependable worker who always finishes on time.","او یک کارمند قابل اعتماد است که همیشه کار را به موقع تمام می‌کند."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:deplete','deplete','v','خالی کردن','/dɪˈpliːt/ · exhaust','Overfishing has depleted fish stocks.','[["Overfishing has depleted fish stocks.","صید بی رویه ذخایر ماهی را کاهش داده است."],["The long war depleted the country''s resources.","جنگ طولانی منابع کشور را تحلیل برد."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:depletion','depletion','n','تخلیه','/dɪˈpliːʃn/ · drain, evacuation','Crop rotation helps maintain soil fertility by preventing the depletion of specific nutrients.','[["Crop rotation helps maintain soil fertility by preventing the depletion of specific nutrients.","تناوب زراعی با جلوگیری از کاهش مواد مغذی خاص، به حفظ حاصلخیزی خاک کمک می‌کند."],["Unsustainable fishing on coral reef areas can lead to the depletion of key reef species in many locations.","ماهیگیری ناپایدار در مناطق صخره‌های مرجانی می‌تواند منجر به کاهش گونه‌های کلیدی صخره‌های مرجانی در بسیاری از مناطق شود."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:desiccated','desiccated','adj','خشک','/ˈdɛsɪkeɪt/ · dry, arid, parched','Do you think desiccated coconut will do for the topping instead of hundreds and thousands?','[["Do you think desiccated coconut will do for the topping instead of hundreds and thousands?","فکر می‌کنی نارگیل خشک شده به جای صدها و هزاران نارگیل، برای رویه کافی است؟"]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:detractor','detractor','n','بدگو','/dɪˈtræktə/ · critic','Any truly influential person will have a fair share of detractors.','[["Any truly influential person will have a fair share of detractors.","هر فرد واقعاً تأثیرگذاری، سهم قابل توجهی از مخالفان خواهد داشت."],["For a writer there is no dearth of detractors.","برای یک نویسنده، منتقد کم نیست."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:deviate','deviate','v','کجروی کردن، منحرف شدن، گمراه شدن','/ˈdiːvieɪt/ · digress, stray','deviate from the normal procedure','[["deviate from the normal procedure","از روال عادی منحرف شود"],["Any indication that a roommate’s life deviates from the familiar can heighten a student''s fear of the unknown.","هر نشانه‌ای از اینکه زندگی هم‌اتاقی با چیزهای آشنا تفاوت دارد، می‌تواند ترس دانشجو از ناشناخته‌ها را بیشتر کند."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:devise','devise','v','ابداع کردن، اختراع کردن، ساختن','/dɪˈvaɪz/ · create, invent, contrive','He devised a new plan.','[["He devised a new plan.","او طرح جدیدی ریخت."],["She started devising sinister plans.","او شروع به طراحی نقشه‌های شوم کرد."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:devour','devour','v','بلعیدن','/dɪˈvaʊə/ · eat','They were devouring me with their eyes.','[["They were devouring me with their eyes.","با چشم‌هایشان داشتند مرا می‌بلعیدند."],["The cows eagerly devoured the fresh alfalfa.","گاوها با ولع یونجه تازه را می‌خوردند."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:diffuse','diffuse','v','پراکنده کردن، پخش کردن یا شدن','/dɪˈfuːz/ · disperse/ spread out, travel','There were no galaxies or even stars, only diffuse gas.','[["There were no galaxies or even stars, only diffuse gas.","هیچ کهکشان یا حتی ستاره‌ای وجود نداشت، فقط گاز پراکنده بود."],["A great light was diffused over the baseball stadium.","نور عظیمی بر فراز استادیوم بیسبال پخش شده بود."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:diligent','diligent','adj','کوشا، سخت کوش، مستمر','/ˈdɪlədʒənt/ · careful, hard-working','She is a diligent student.','[["She is a diligent student.","او یک دانش آموز کوشا است."],["After years of diligent research, he made a discovery.","او پس از سالها تحقیق مجدانه به کشفی دست یافت."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:dilute','dilute','v','کم توان کردن، ضعیف کردن','/daɪˈluːt/ · reduce, weaken','We''re diluting the colour of the paint by adding more white.','[["We''re diluting the colour of the paint by adding more white.","ما با اضافه کردن رنگ سفید بیشتر، رنگ را رقیق می‌کنیم."],["Can I use this solvent to dilute my sample?","آیا می‌توانم از این حلال برای رقیق کردن نمونه‌ام استفاده کنم؟"]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:disassemble','disassemble','v','از هم باز کردن، پیاده کردن ماشین آلات','/dis‧as‧sem‧ble/ · break up, break apart (often a device), dismantle','I have to disassemble this engine.','[["I have to disassemble this engine.","من باید این موتور را از هم جدا کنم."],["The crowd begins to disassemble.","جمعیت شروع به پراکنده شدن می‌کند."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:disband','disband','v','منحل شدن یا کردن، از هم پاشیدن','/dɪsˈbænd/ · dismiss','That same year, the group disbanded.','[["That same year, the group disbanded.","در همان سال، این گروه از هم پاشید."],["My reading group voted to disband.","گروه کتابخوانی من رأی به انحلال داد."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:discernible','discernible','adj','قابل تشخیص، قابل فهم','/dɪˈsɝː.nə.bəl/ · noticeable, discriminating','Her voice was barely discernible.','[["Her voice was barely discernible.","صدایش به سختی قابل تشخیص بود."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:disentangle','disentangle','v','جدا کردن، رها کردن، صاف کردن، از پیچیدگی درآوردن','/ˌdɪsənˈtæŋɡəl/ · disband, abandon, unwrap','I''m not sure what''s the best way to disentangle this.','[["I''m not sure what''s the best way to disentangle this.","مطمئن نیستم بهترین راه برای خلاص شدن از این مخمصه چیست."],["The detective tried to disentangle fact from fiction.","کارآگاه سعی کرد واقعیت را از خیال جدا کند."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:disintegrate','disintegrate','v','فروپاشیدن، متلاشی شدن یا کردن','/dɪsˈɪntɪɡreɪt/ · fall apart, break apart, tear apart','The project started to disintegrate from 2004.','[["The project started to disintegrate from 2004.","این پروژه از سال ۲۰۰۴ شروع به فروپاشی کرد."],["The toy is starting to disintegrate.","اسباب‌بازی شروع به تجزیه شدن می‌کند."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:dismantle','dismantle','v','برچیدن','/dɪsˈmæntl/ · demolish, destroy, disassemble','This needs to be dismantled.','[["This needs to be dismantled.","این باید برچیده شود."],["We need to dismantle this.","ما باید این را از بین ببریم."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:dispensable','dispensable','adj','غیرضروری','/dɪˈspensəbəl/ · not necessary, inessential','In a crisis, many luxury goods become dispensable.','[["In a crisis, many luxury goods become dispensable.","در شرایط بحرانی، بسیاری از کالاهای لوکس غیرضروری می‌شوند."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:dispersal','dispersal','n','پراکنش، توزیع، انتشار','/dɪˈspɜːsəl/ · distribution, spread','Birds play an important role in the dispersal of seeds.','[["Birds play an important role in the dispersal of seeds.","پرندگان نقش مهمی در پراکندگی دانه‌ها دارند."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:displace','displace','v','جا به جا کردن، بی خانمان کردن','/dɪsˈpleɪs/ · move out of position, replacedisplace','The flood displaced thousands.','[["The flood displaced thousands.","سیل هزاران نفر را آواره کرد."],["Native plants were displaced by invasive species.","گیاهان بومی توسط گونه‌های مهاجم جابجا شدند."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:dissipate','dissipate','v','پراکندن، پخش کردن یا شدن','/ˈdɪsəpeɪt/ · disperse, scatter, diffuse','The fog started to dissipate about ten o''clock.','[["The fog started to dissipate about ten o''clock.","حدود ساعت ده مه شروع به پراکنده شدن کرد."],["The fog dissipated as the sun rose.","با طلوع خورشید، مه از بین رفت."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:dissuade','dissuade','v','منصرف کردن، بازداشتن، نظر کسی را تغییر دادن','/dɪˈsweɪd/ · discourage, persuade against','She was not so easily dissuaded.','[["She was not so easily dissuaded.","او به این راحتی‌ها منصرف نمی‌شد."],["She tried to dissuade him.","او سعی کرد او را منصرف کند."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:diversification','diversification','n','تنوع و گوناگونی','/daɪˌvɜːrsɪfɪˈkeɪʃn/ · emergence of many varieties','Algeria needs an efficient economic diversification strategy.','[["Algeria needs an efficient economic diversification strategy.","الجزایر به یک استراتژی کارآمد برای تنوع اقتصادی نیاز دارد."],["Tebboune''s government is currently encouraging economic diversification.","دولت تبون در حال حاضر تنوع اقتصادی را تشویق می‌کند."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:diversify','diversify','v','متنوع ساختن','/dɪˈvɝː.sə.faɪ/ · vary, bring variety todiversify','Algiers has a very diversified economy.','[["Algiers has a very diversified economy.","الجزایر اقتصاد بسیار متنوعی دارد."],["Algeria focuses on diversifying its exports.","الجزایر بر تنوع بخشیدن به صادرات خود تمرکز دارد."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:divest','divest','v','محروم کردن، بی بهره کردن','/daɪˈvest/ · deprive, get rid of, exclude','The company plans to divest its non-core assets.','[["The company plans to divest its non-core assets.","این شرکت قصد دارد دارایی‌های غیر اصلی خود را واگذار کند."],["Many farmers had to divest themselves of stock during the drought to save on feeding costs.","بسیاری از کشاورزان در طول خشکسالی مجبور شدند برای صرفه‌جویی در هزینه‌های تغذیه، دام‌های خود را بفروشند."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:efface','efface','v','زدودن، از بین بردن','/ɪˈfeɪs/ · eliminate, remove','I tried to efface the memory of her tears.','[["I tried to efface the memory of her tears.","سعی کردم خاطره اشک‌هایش را از ذهنم پاک کنم."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:elapsed','elapsed','adj','سپری‌شده','/ɪˈlæps/ · passed (of time)','About an hour has elapsed.','[["About an hour has elapsed.","حدود یک ساعت گذشته است."],["How much time has elapsed?","چقدر زمان گذشته است؟"]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:emanate','emanate','v','بیرون آمدن، پدیدار شدن','/ˈeməneɪt/ · emerge, appear, spread out, show a particular quality','Ripples were emanating from the middle of the lake.','[["Ripples were emanating from the middle of the lake.","موج‌هایی از وسط دریاچه بیرون زده بودند."],["From the sphere emanated some kind of strange glow.","از کره نوعی درخشش عجیب ساطع می‌شد."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:embed','embed','v','جاسازی کردن، محصور کردن، وارد کردن','/ɪmˈbed/ · enclose, implant, insert','To embed this video, copy and paste the following HTML code onto your webpage.','[["To embed this video, copy and paste the following HTML code onto your webpage.","برای قرار دادن این ویدیو، کد HTML زیر را کپی کرده و در صفحه وب خود قرار دهید."],["How can I embed the debt clock on my Web site?","چگونه می‌توانم ساعت بدهی را در وب‌سایت خود جاسازی کنم؟"]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:emergent','emergent','adj','نوظهور و در حال توسعه','/ɪˈmɜːrdʒənt/ · in the early stages of existence or development, developing','Emergent behaviour arises from simple interactions.','[["Emergent behaviour arises from simple interactions.","رفتار اضطراری از تعاملات ساده ناشی می‌شود."],["Consciousness is an emergent property of the brain.","هوشیاری یک ویژگی نوظهور مغز است."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:enactment','enactment','n','تصویب، به صورت قانون درآمدن','/ɪˈnæktmənt/ · establishment, approval','The enactment of the new law took several years.','[["The enactment of the new law took several years.","تصویب قانون جدید چندین سال طول کشید."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:encapsulate','encapsulate','v','به صورت خلاصه بیان کردن','/ɪnˈkæpsəleɪt/ · state briefly, summarize, capture','Love can''t be encapsulated in words. It can only be felt.','[["Love can''t be encapsulated in words. It can only be felt.","عشق را نمی‌توان در کلمات گنجاند. فقط می‌توان آن را احساس کرد."],["Katti''s work involved very small particles of gold encapsulated in a protective stabilizer from an acacia tree.","کار کاتی شامل ذرات بسیار کوچکی از طلا بود که در یک تثبیت‌کننده محافظ از درخت اقاقیا محصور شده بودند."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:endow','endow','v','وقف کردن، موهبت بخشیدن به','/ɪnˈdaʊ/ · bestow, grant, dedicate','Are there teachers endowed with artificial intelligence?','[["Are there teachers endowed with artificial intelligence?","آیا معلمانی با هوش مصنوعی وجود دارند؟"],["Algeria is well endowed in natural resources.","الجزایر از نظر منابع طبیعی بسیار غنی است."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:engulf','engulf','v','قورت دادن، فرا گرفتن','/ɪnˈɡʌlf/ · swallow, ingest, comprehend, 1) if an unpleasant feeling engulfs you, you feel it very strongly.2) to completely surround or cover something','Oleg was engulfed in the flames of the firestorm.','[["Oleg was engulfed in the flames of the firestorm.","اولگ در شعله‌های آتش گرفتار شد."],["Their living room was engulfed in flames.","اتاق نشیمن آنها در آتش سوخت."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ensue','ensue','v','در پی آمدن، ناشی شدن','/ɪnˈsuː/ · result, to happen after or as a result of something','After his speech a standing ovation ensued.','[["After his speech a standing ovation ensued.","پس از سخنرانی او، حضار ایستاده تشویق کردند."],["A vicious custody battle ensued.","نبردی خونین بر سر حضانت آغاز شد."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:entail','entail','v','شامل بودن، مستلزم بودن','/ɪnˈteɪl/ · involve, require, call for','His occupation entails a lot of travelling.','[["His occupation entails a lot of travelling.","شغل او مستلزم سفرهای زیادی است."],["Could you tell me what that entails?","میشه بگید این یعنی چی؟"]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:envision','envision','v','تصور کردن','/ɪnˈvɪʒən/ · imagine','Do you envision an urban landscape without cars?','[["Do you envision an urban landscape without cars?","آیا چشم‌انداز شهری بدون ماشین را تصور می‌کنید؟"],["It''s difficult to envision a brighter future.","تصور آینده‌ای روشن‌تر دشوار است."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ephemeral','ephemeral','adj','زودگذر','/ɪˈfemərəl/ · existing or popular for only a short time, short-lived, transitory, temporary','Fame on social media is ephemeral.','[["Fame on social media is ephemeral.","شهرت در شبکه‌های اجتماعی زودگذر است."],["Fame in the internet age is often ephemeral.","شهرت در عصر اینترنت اغلب زودگذر است."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:epitomize','epitomize','v','مجسم کردن، مثالی معروف از چیزی بودن','/ɪˈpɪtəmaɪz/ · exemplify, to be a very typical example of something','The Durga puja festival epitomizes the victory of good over evil.','[["The Durga puja festival epitomizes the victory of good over evil.","جشنواره دورگا پوجا، پیروزی خیر بر شر را به تصویر می‌کشد."],["He epitomizes the American dream.","او تجسم رؤیای آمریکایی است."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:eradicate','eradicate','v','ریشه کن کردن، نابود کردن','/ɪˈrædɪkeɪt/ · remove completely, annihilate, to completely get rid of something such as a disease or a social problem','Vaccines helped eradicate smallpox.','[["Vaccines helped eradicate smallpox.","واکسن‌ها به ریشه کنی آبله کمک کردند."],["Vaccines have helped to eradicate many diseases.","واکسن‌ها به ریشه کن کردن بسیاری از بیماری‌ها کمک کرده اند."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:erroneous','erroneous','adj','نادرست','/əˈroʊ.ni.əs/ · wrong, incorrect','The claim is based on erroneous data.','[["The claim is based on erroneous data.","این ادعا بر اساس داده‌های اشتباه است."],["It is an erroneous belief that money brings happiness.","این یک باور اشتباه است که پول خوشبختی می‌آورد."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:euphoric','euphoric','adj','سرخوش','/juːˈfɔːr.ɪk/ · extremely happy','He heaved a euphoric sigh of relief.','[["He heaved a euphoric sigh of relief.","او آهی از سر آسودگی کشید."],["Vicodin, Oxycontin and their cousins quickly became popular, providing a euphoric effect while they dulled pain.","ویکودین، اکسی‌کانتین و پسرعموهایشان به سرعت محبوب شدند و ضمن تسکین درد، اثر سرخوشی ایجاد می‌کردند."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:evoke','evoke','v','به وجوداوردن خاطره یا حسی در کسی','/ɪˈvoʊk/ · create in the mind, arouse, draw, promote, stimulate, produce','The smell of mown grass evokes hot summer afternoons.','[["The smell of mown grass evokes hot summer afternoons.","بوی چمن‌های هرس‌شده، بعدازظهرهای گرم تابستان را تداعی می‌کند."],["They performed a ritual to evoke the gods.","آنها مراسمی را برای احضار خدایان انجام دادند."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:exaggerate','exaggerate','v','غلو کردن','/ɪɡˈzædʒəreɪt/ · overstate, overemphasize','Don''t exaggerate; it wasn''t that bad.','[["Don''t exaggerate; it wasn''t that bad.","اغراق نکنید؛ آنقدرها هم بد نبود"],["He always exaggerates his stories.","او همیشه در داستان هایش اغراق می‌کند."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:excavate','excavate','v','حفاری کردن','/ˈekskəveɪt/ · dig out','Archaeologists excavated the site.','[["Archaeologists excavated the site.","باستان شناسان این محوطه را کاوش کردند."],["Archaeologists excavated an ancient city.","باستان شناسان یک شهر باستانی را کاوش کردند."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:excrete','excrete','v','دفع کردن، بیرون انداختن','/ɪkˈskriːt/ · expel, formal to get rid of waste material from your body through your bowels, your skin','When someone is diabetic, they excrete sugar in their urine.','[["When someone is diabetic, they excrete sugar in their urine.","وقتی کسی دیابت دارد، قند را از طریق ادرار دفع می‌کند."],["I occasionally excrete concrete: this is not strange.","من گاهی اوقات بتن دفع می‌کنم: این چیز عجیبی نیست."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:expanse','expanse','n','گسترده، وسیع','/ɪkˈspæns/ · area; expansive, large','The university has a large expanse of forest.','[["The university has a large expanse of forest.","این دانشگاه دارای وسعت زیادی از جنگل است."],["Felix admired the vast expanses of wilderness.","فلیکس وسعت وسیع طبیعت بکر را تحسین می‌کرد."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:expediency','expediency','n','صرفه، مزیت، مناسب','/ɪkˈspiːdiənsi/ · advantage, convenience, efficiency','The decision was made out of expediency rather than principle.','[["The decision was made out of expediency rather than principle.","این تصمیم بیشتر از روی مصلحت‌اندیشی گرفته شد تا اصول."]]','t1212',21,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:expedient','expedient','adj','مقتضی، مصلحت','/ɪkˈspiːdiənt/ · fitting, suitable, convenient','Never lie if the truth is more expedient.','[["Never lie if the truth is more expedient.","اگر راستگویی مصلحت‌آمیزتر است، هرگز دروغ نگو."],["The true danger is when liberty is nibbled away, for expedients, and by parts.","خطر واقعی زمانی است که آزادی، به خاطر مصلحت‌ها، و بخش بخش، از بین برود."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:expend','expend','v','صرف کردن، استفاده کردن، خرج کردن، مصرف کردن','/ɪkˈspend/ · use, spend, consume','According to the budget, she could expend no more on supplies.','[["According to the budget, she could expend no more on supplies.","طبق بودجه، او نمی‌توانست بیشتر از این برای تدارکات هزینه کند."],["Such a person invariably expends his physical energy more slowly.","چنین شخصی همواره انرژی فیزیکی خود را کندتر مصرف می‌کند."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:extant','extant','adj','باقی مانده موجود، دارای هستی','/ɪkˈstænt/ · remaining, existing, not extinct','The echidna and the platypus are the only extant monotremes.','[["The echidna and the platypus are the only extant monotremes.","اکیدنا و پلاتیپوس تنها تک‌سوراخی‌های باقی‌مانده هستند."],["But there is no publication extant authenticated with his name.","اما هیچ نشریه‌ای که نام او را تأیید کرده باشد، موجود نیست."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:extol','extol','v','ستودن، تمجید کردن','/ɪkˈstəʊl/ · praise','I plan to extol your virtues to all who will listen.','[["I plan to extol your virtues to all who will listen.","من قصد دارم فضایل تو را برای همه کسانی که گوش می‌دهند، ستایش کنم."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:extraneous','extraneous','adj','خارجی، غیر ضروری، غیر اصلی، خارج قلمرو','/ɪkˈstreɪniəs/ · from outside, inessential','Everything beyond food, water, and shelter is extraneous.','[["Everything beyond food, water, and shelter is extraneous.","هر چیزی فراتر از غذا، آب و سرپناه، اضافی و بی‌اهمیت است."],["Love is what matters; everything else is extraneous.","عشق است که اهمیت دارد؛ هر چیز دیگری فرعی است."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:exude','exude','v','تراوش کردن، بیرون دادن، از خود نشان دادن','/ɪɡˈzjuːd/ · give off; release, discharge','She exudes happiness every moment.','[["She exudes happiness every moment.","او هر لحظه شادی را از خود ساطع می‌کند."],["She always exuded great energy.","او همیشه انرژی زیادی از خود ساطع می‌کرد."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:fabricate','fabricate','v','ساختن، تولید کردن؛ جعل کردن','/ˈfæbrɪkeɪt/ · 1) produce, to make or produce goods or equipment, 2) to invent a story, piece of information etc in order to deceive someone','She began to fabricate a story.','[["She began to fabricate a story.","او شروع به ساختن یک داستان کرد."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:facet','facet','n','جنبه','/ˈfæsɪt/ · aspect','A facet of genius is the ability to provoke scandals.','[["A facet of genius is the ability to provoke scandals.","یکی از جنبه‌های نبوغ، توانایی برانگیختن رسوایی است."],["That''s not the most important facet of the tale.","این مهم‌ترین جنبه‌ی داستان نیست."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:flake','flake','n','قطعه، تکه','/fleɪk/ · fragment, piece, scrap','He likes to sprinkle coconut flakes on top of his cupcakes.','[["He likes to sprinkle coconut flakes on top of his cupcakes.","او دوست دارد روی کاپ‌کیک‌هایش پودر نارگیل بپاشد."],["After a while, corn flakes in milk will become soggy.","بعد از مدتی، کورن فلکس‌های داخل شیر، خمیر می‌شوند."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:flattery','flattery','n','چاپلوسی، تملق','/ˈflætəri/ · praise, compliments','She is easily taken in by flattery.','[["She is easily taken in by flattery.","او به راحتی مجذوب چاپلوسی می‌شود."],["She won my heart with flattery.","او با چاپلوسی دل مرا به دست آورد."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:flourishing','flourishing','adj','رونق، شکوفایی','/ˈflʌrɪʃɪŋˈflɜːr/ · prosperous','The arms trade is flourishing.','[["The arms trade is flourishing.","تجارت اسلحه رونق گرفته است."],["His Algerian hotel was flourishing.","هتل الجزایری او در حال شکوفایی بود."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:fluctuate','fluctuate','v','نوسان داشتن، نوسان کردن','/ˈflʌktʃueɪt/ · change, vary, swing','Oil prices fluctuated throughout the year.','[["Oil prices fluctuated throughout the year.","قیمت نفت در طول سال در نوسان بود."],["The temperature fluctuates between 10 and 25 degrees.","دمای هوا بین 10 تا 25 درجه در نوسان است."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:fluctuation','fluctuation','n','نوسان، تغییر','/ˌflʌktʃuˈeɪʃən/ · variation, oscillation','The chart shows fluctuations in sales.','[["The chart shows fluctuations in sales.","نمودار نوسانات فروش را نشان می‌دهد."],["There have been sharp fluctuations in oil prices.","نوسانات شدیدی در قیمت نفت رخ داده است."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:forage','forage','n','علوفه، علف','/ˈfɑː-/ · search for food, feed','Worker ants forage for food collectively.','[["Worker ants forage for food collectively.","مورچه‌های کارگر به طور جمعی برای غذا علوفه می‌گیرند."],["They foraged for food in the forest.","آنها در جنگل به دنبال غذا می‌گشتند."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:formulate','formulate','v','فرمول بندی کردن، تنظیم کردن','/ˈfɔːmjəleɪt/ · form / devise methodically','We have to formulate a plan if we are to save her!','[["We have to formulate a plan if we are to save her!","اگر می‌خواهیم او را نجات دهیم، باید نقشه‌ای بکشیم!"],["I cannot coherently formulate words without coffee.","من بدون قهوه نمی‌توانم کلمات را به طور منسجم بیان کنم."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:freestanding','freestanding','adj','مستقل، بی پیرایه','/friːˈstændɪŋ/ · separate, independent','The museum displays a freestanding statue in the center of the hall.','[["The museum displays a freestanding statue in the center of the hall.","این موزه یک مجسمه مستقل را در مرکز سالن به نمایش می‌گذارد."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:frigid','frigid','adj','منجمد، بسیار سرد','/ˈfrɪdʒɪd/ · very cold','In the frigid, autumnal air, icy droplets plummeted to the ground.','[["In the frigid, autumnal air, icy droplets plummeted to the ground.","در هوای سرد پاییزی، قطرات یخ به زمین می‌افتادند."],["The frigid air stung our faces.","هوای سرد صورتمان را سوزاند."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:groundless','groundless','adj','بی اساس','/ˈɡraʊndləs/ · unfounded, baseless','The fact is that the rumor is groundless.','[["The fact is that the rumor is groundless.","واقعیت این است که این شایعه بی‌اساس است."],["So far, your action seems completely groundless.","تا اینجا، اقدام شما کاملاً بی‌اساس به نظر می‌رسد."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:groundwork','groundwork','n','پایه، اساس','/ˈɡraʊndwɜːk/ · base, basis, foundation','We''re laying the groundwork of a better future for ourselves and our progeny.','[["We''re laying the groundwork of a better future for ourselves and our progeny.","ما در حال پایه ریزی آینده ای بهتر برای خود و فرزندانمان هستیم."],["Thanks for doing the groundwork.","ممنون که کارهای مقدماتی رو انجام دادی."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:grudging','grudging','adj','سوء نیت، با اکراه','/grʌdʒ.ɪŋ/ · unenthusiastic, bad intentionto do or give something very unwillingly.','This decision was grudgingly accepted.','[["This decision was grudgingly accepted.","این تصمیم با اکراه پذیرفته شد."],["Tom grudgingly did what Mary asked.","تام با اکراه کاری را که مری خواسته بود انجام داد."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:hairline','hairline','adj','بسیار باریک، جزئی','/heə.laɪn/ · slight, fracture, crack','He''s not even 30 and he has a receding hairline.','[["He''s not even 30 and he has a receding hairline.","او حتی 30 سال هم ندارد و خط رویش موهایش عقب رفته است."],["His hairline is receding. He''ll end up bald like his father and grandfather.","خط رویش موهایش دارد عقب می‌رود. او هم مثل پدر و پدربزرگش کچل خواهد شد."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:hamper','hamper','v','مانع شدن، مانع شدن از','/hæm.pə/ · restrictmake difficultyhinder','Fog banks continued to hamper visibility for motorists.','[["Fog banks continued to hamper visibility for motorists.","مه غلیظ همچنان مانع دید رانندگان می‌شود."],["Please be quiet and don''t hamper my work.","لطفا ساکت باشید و مانع کار من نشوید."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:haphazard','haphazard','adj','اتفاقی، تصادفی','/hæpˈhæzəd/ · random, accidental','The march toward progress is really more of a haphazard stagger.','[["The march toward progress is really more of a haphazard stagger.","حرکت به سمت پیشرفت در واقع بیشتر شبیه یک تلوتلو خوردن تصادفی است."],["Haphazard eating habits caused the castaway''s food supply to be quickly depleted.","عادات غذایی نامنظم باعث شد که ذخیره غذایی مرد رانده شده به سرعت تمام شود."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:hasten','hasten','v','شتاب کردن، تسریع کردن','/ˈheɪsən/ · speed up, accelerate','He often hastens physical intimacy, much to the chagrin of his dates.','[["He often hastens physical intimacy, much to the chagrin of his dates.","او اغلب صمیمیت فیزیکی را تسریع می‌کند، که این امر باعث ناراحتی قرارهایش می‌شود."],["She hastened back to her room.","با عجله به اتاقش برگشت."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:hasty','hasty','adj','شتابزده، عجول','/ˈheɪsti/ · hurried','This was a hasty translation.','[["This was a hasty translation.","این ترجمه عجولانه بود."],["Tom beat a hasty retreat.","تام با عجله عقب‌نشینی کرد."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:heighten','heighten','v','افزایش دادن، یافتن','/ˈhaɪtn/ · increase, if something heightens a feeling, effect etc, or if a feeling etc heightens, it becomes stronger or increases','To cause laughter without joining in greatly heightens the effect.','[["To cause laughter without joining in greatly heightens the effect.","ایجاد خنده بدون مشارکت، تأثیر آن را به شدت افزایش می‌دهد."],["She tried to allay their fears but only ended up heightening them.","او سعی کرد ترس آنها را کاهش دهد، اما در نهایت فقط آنها را تشدید کرد."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:heterogeneous','heterogeneous','adj','متنوع','/hetərəʊˈdʒiːniəs/ · varied, diverse, not homogeneous','The population is heterogeneous.','[["The population is heterogeneous.","جمعیت ناهمگن است."],["The class is a heterogeneous group of students.","کلاس یک گروه ناهمگون از دانش آموزان است."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:hitherto','hitherto','adv','قبلا','/ˌhɪð.ɚˈtuː/ · previously','The history of all hitherto existing societies is the history of class struggles.','[["The history of all hitherto existing societies is the history of class struggles.","تاریخ تمام جوامع تاکنون موجود، تاریخ مبارزات طبقاتی بوده است."],["This kind of writing I do not remember to have seen hitherto attempted in our language.","به یاد ندارم که تا به حال تلاشی برای این نوع نگارش در زبان خودمان دیده باشم."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:homogeneous','homogeneous','adj','همگن، یکنواخت','/həʊməˈdʒiːniəs/ · uniform, consisting of people or things that are all of the same type','This is a linguistically homogeneous region.','[["This is a linguistically homogeneous region.","این منطقه از نظر زبانی همگن است."],["We are a homogeneous community.","ما یک جامعه‌ی همگن هستیم."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:idiosyncrasies','idiosyncrasies','n','طرز فکر ویژه، خصیصه‌های ذاتی','/ˌɪdiəˈsɪŋkrəsi/ · peculiarity, oddity','I have a lot of idiosyncrasies; feel free to mention if something sounds unnatural.','[["I have a lot of idiosyncrasies; feel free to mention if something sounds unnatural.","من ویژگی‌های شخصیتی خاص زیادی دارم؛ اگر چیزی غیرطبیعی به نظر می‌رسد، لطفاً به من بگویید."],["Discussing beliefs will always present a challenge, since we all have our own idiosyncrasies.","بحث در مورد باورها همیشه چالش برانگیز خواهد بود، زیرا همه ما ویژگی‌های خاص خودمان را داریم."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:imitate','imitate','v','تقلید کردن','/ˈɪmɪteɪt/ · emulate with','The little one imitates the big one.','[["The little one imitates the big one.","کوچولو از بزرگتر تقلید میکنه."],["Danish just sounds impossible to imitate.","تقلید کردن زبان دانمارکی غیرممکن به نظر می‌رسد."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:immobile','immobile','adj','ثابت','/ɪˈməʊbaɪl/ · fixed, motionless, inert','This supposition, that the Earth is immobile, was completely untrue.','[["This supposition, that the Earth is immobile, was completely untrue.","این فرض که زمین بی‌حرکت است، کاملاً نادرست بود."],["The car stopped completely immobile.","ماشین کاملاً بی‌حرکت ایستاد."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:immobility','immobility','n','عدم تحرک و حرکت','/ˌɪməˈbɪləti/ · absence of motion, when land, labour, or capital cannot be easily moved from one kind of use or employment to another, for example when skilled workers cannot be easily employed in another job that uses different skills','Immobility isn''t a recommendable political option.','[["Immobility isn''t a recommendable political option.","بی‌تحرکی گزینه سیاسی قابل توصیه‌ای نیست."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:impermeable','impermeable','adj','غیر قابل نفوذ','/ɪmˈpɜːmiəbəl/ · impervious, impenetrable','He glazed his pottery to make it impermeable to water.','[["He glazed his pottery to make it impermeable to water.","او سفال‌هایش را لعاب می‌داد تا در برابر آب نفوذناپذیر شوند."],["The eardrum is a thin, impermeable membrane.","پرده گوش یک غشای نازک و نفوذناپذیر است."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:impetus','impetus','n','انگیزه، محرک','/ˈɪmpɪtəs/ · incentive, stimulus, inducement','If there''s no reward, what''s the impetus to return their dog?','[["If there''s no reward, what''s the impetus to return their dog?","اگر پاداشی در کار نباشد، انگیزه بازگرداندن سگشان چیست؟"],["What''s the impetus underlying all of your actions?","انگیزه‌ی پشت تمام اعمال شما چیست؟"]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:implausible','implausible','adj','باور نکردنی','/ɪmˈplɔːzəbəl/ · unbelievable','Richa''s theories can be very fascinating, even if they are implausible.','[["Richa''s theories can be very fascinating, even if they are implausible.","نظریه‌های ریچا می‌توانند بسیار جذاب باشند، حتی اگر غیرمحتمل باشند."],["That Richa can read minds is implausible, to say the least.","اینکه ریچا بتواند ذهن‌ها را بخواند، حداقل می‌توان گفت که غیرقابل باور است."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:imprecise','imprecise','adj','درست نشده، مبهم','/ˌɪmprɪˈsaɪs/ · inexact','Every translation is imprecise, every translation is free.','[["Every translation is imprecise, every translation is free.","هر ترجمه‌ای نادقیق است، هر ترجمه‌ای آزاد است."],["The measurement is far too imprecise.","اندازه‌گیری خیلی خیلی غیردقیق است."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:improbable','improbable','adj','بعید','/ɪmˈprɒbəbəl/ · unlikely, not probable','Our existence is very improbable.','[["Our existence is very improbable.","وجود ما بسیار بعید است."],["That is an improbable coincidence.","این یک تصادف بعید است."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:inaugurate','inaugurate','v','معرفی کردن','/ɪˈnɑː.ɡjə.reɪt/ · introduce','The new Algiers airport was inaugurated in 2019.','[["The new Algiers airport was inaugurated in 2019.","فرودگاه جدید الجزیره در سال ۲۰۱۹ افتتاح شد."],["He was inaugurated as President.","او به عنوان رئیس جمهور سوگند یاد کرد."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:inauspicious','inauspicious','adj','نامساعد','/ˌɪnɒːˈspɪʃəs/ · unfavorable, not auspicious','The team made an inauspicious start, losing its first three games.','[["The team made an inauspicious start, losing its first three games.","این تیم شروع بدی داشت و سه بازی اول خود را باخت."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:inclement','inclement','adj','شدید، نامساعد','/ɪnˈklemənt/ · unfavorable, intemperate, inclement weather is unpleasantly cold, wet etc','In spite of the inclement weather, many people were there.','[["In spite of the inclement weather, many people were there.","با وجود آب و هوای نامساعد، افراد زیادی آنجا بودند."],["In case of inclement weather, we''ll hold the event in the gym.","در صورت نامساعد بودن هوا، مراسم را در سالن ورزشی برگزار خواهیم کرد."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:inconceivable','inconceivable','adj','غیر قابل تصور','/ˌɪnkənˈsiːvəbəl/ · unimaginable, incredible, too strange or unusual to be thought real or possible','It is inconceivable that he could ever be elected president.','[["It is inconceivable that he could ever be elected president.","بعید است که او بتواند به عنوان رئیس جمهور انتخاب شود."],["It is inconceivable to me that he would do such a thing.","برای من غیرقابل تصور است که او چنین کاری انجام دهد."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:inconclusive','inconclusive','adj','بی نتیجه','/ˌɪnkənˈkluːsɪv/ · without result, indefinite, indeterminate','Talks between labour and management were inconclusive.','[["Talks between labour and management were inconclusive.","مذاکرات بین کارگران و مدیران بی‌نتیجه ماند."],["The result of the experiment was inconclusive.","نتیجه آزمایش قطعی نبود."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:incursion','incursion','n','تهاجم، تاخت و تاز','/ɪnˈkɜːʃən/ · 1)invasion, a sudden attack into an area that belongs to other people2)the sudden arrival of something or someone into a place or activity','We should resist the incursion of the English language.','[["We should resist the incursion of the English language.","ما باید در مقابل تهاجم زبان انگلیسی مقاومت کنیم."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:indiscriminately','indiscriminately','adv','بدون نظم و فکر، تصادفی','/ˌɪndɪˈskrɪmɪnətli/ · at random, arbitrarily, haphazardly','Me, I hate people who are indiscriminately friendly.','[["Me, I hate people who are indiscriminately friendly.","من، از آدم‌هایی که بی‌هدف و بدون تبعیض با هم دوست هستند، متنفرم."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:indistinct','indistinct','adj','نا معلوم','/indisˈtiNGkt/ · not clear','After a few minutes I thought I heard an indistinct murmuring.','[["After a few minutes I thought I heard an indistinct murmuring.","بعد از چند دقیقه فکر کردم صدای زمزمه‌ی نامفهومی شنیدم."],["A few indistinct groans could be heard from the back seat.","صدای ناله‌های نامفهومی از صندلی عقب به گوش می‌رسید."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:inducement','inducement','n','انگیزه','/inˈd(y)o͞osmənt/ · incentive, motivation, impetus','The company offered higher pay as an inducement to stay.','[["The company offered higher pay as an inducement to stay.","این شرکت به عنوان انگیزه‌ای برای ماندن، حقوق بالاتری پیشنهاد داد."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ineffectively','ineffectively','adv','غیرموثر','/ˌɪn.ɪˈfek.tɪv.li/ · without any result','I ineffectively tried to win her heart back.','[["I ineffectively tried to win her heart back.","تلاشم برای بدست آوردن دوباره دلش بی نتیجه ماند."],["The school used its computer lab funds ineffectively.","مدرسه از بودجه آزمایشگاه کامپیوتر خود به طور ناکارآمد استفاده کرد."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:inert','inert','adj','بی انگیزه، بی احساس، ساکن','/iˈnərt/ · motionless, motiveless, immobile','It doesn''t make any difference, guys. The balls are inert.','[["It doesn''t make any difference, guys. The balls are inert.","بچه‌ها، فرقی نمی‌کنه. توپ‌ها بی‌اثر هستن."],["Nitrous oxide is inert at room temperature.","اکسید نیتروژن در دمای اتاق بی‌اثر است."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:inference','inference','n','استنتاج','/ˈɪnfərəns/ · conclusion, deduction, a conclusion reached on the basis of evidence and reasoning','Select the statements which are observations rather than inferences.','[["Select the statements which are observations rather than inferences.","گزاره‌هایی را انتخاب کنید که بیشتر مشاهده‌ای باشند تا استنتاجی."],["You must draw inferences but not speculate.","شما باید استنتاج کنید اما حدس و گمان نکنید."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:infirm','infirm','adj','ناتوان، ضعیف','/inˈfərm/ · weak, feeble','My father is very infirm.','[["My father is very infirm.","پدرم خیلی ضعیف و ناتوان است."],["Tom is old and infirm.","تام پیر و ناتوان است."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:inflate','inflate','v','بزرگ کردن، بادکردن، افزایش دادن','/inˈflāt/ · expand, 1) to fill something with air or gas 2) to make something seem more important or impressive than it really is','Ziri struggled to inflate the balloon.','[["Ziri struggled to inflate the balloon.","زیری به سختی بادکنک را باد کرد."],["The wind inflated their coat hoods.","باد، کلاه‌هایشان را باد کرد."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ingenuity','ingenuity','n','نبوغ، استعداد، قوه ابتکار','/ˌinjəˈn(y)o͞oitē/ · cleverness, creativeness, inventiveness, resourcefulness','It is nothing that a little persistence and ingenuity can''t overcome.','[["It is nothing that a little persistence and ingenuity can''t overcome.","چیزی نیست که کمی پشتکار و نبوغ نتواند بر آن غلبه کند."],["Gabriel survived using his ingenuity and determination.","گابریل با استفاده از نبوغ و عزم راسخ خود زنده ماند."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:inhospitable','inhospitable','adj','ناخوشایند، نامهربان','/ˌɪnhɒˈspɪtəbəl/ · unfavorable, adverse, unkind','Mars underwent serious climate change that made it inhospitable.','[["Mars underwent serious climate change that made it inhospitable.","مریخ دستخوش تغییرات اقلیمی شدیدی شد که آن را غیرقابل سکونت کرد."],["Russia is an enormous country, but most of its territory is quite inhospitable.","روسیه کشور پهناوری است، اما بیشتر قلمرو آن کاملاً غیرقابل سکونت است."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:inordinate','inordinate','adj','بیش از حد معمول و لازم، افراط','/iˈnôrdn-it/ · excessive','His so-called apology involved an inordinate amount of explanation and complaining.','[["His so-called apology involved an inordinate amount of explanation and complaining.","عذرخواهی کذایی او شامل مقدار زیادی توضیح و شکایت بود."],["This involved an inordinate amount of working together.","این شامل حجم بیش از حدی از همکاری بود."]]','t1212',22,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:insistent','insistent','adj','مقاوم، مصر، با اصرار زیاد','/inˈsistənt/ · persistent, determined','Ziri was insistent on pressing forward.','[["Ziri was insistent on pressing forward.","زیری اصرار داشت که به جلو حرکت کند."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:instantaneous','instantaneous','adj','فوری، در لحظه','/ˌinstənˈtānēəs/ · immediate, instant','Telegraph messages were almost instantaneous compared to letters.','[["Telegraph messages were almost instantaneous compared to letters.","پیام‌های تلگراف در مقایسه با نامه‌ها تقریباً آنی بودند."],["He knew it was so, with an unaccountable but instantaneous certainty.","او با یقینی غیرقابل توصیف اما آنی می‌دانست که چنین است."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:instigate','instigate','v','تحریک کردن، وادار کردن','/ˈinstiˌgāt/ · incite, stimulate','They used every means in their power to instigate the people against him.','[["They used every means in their power to instigate the people against him.","آنها از هر وسیله‌ای برای تحریک مردم علیه او استفاده کردند."],["Feminists instigate women against men.","فمینیست‌ها زنان را علیه مردان تحریک می‌کنند."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:instructive','instructive','adj','آموزنده و مفید','/inˈstrəktiv/ · informative','It is instructive to compare the two versions of the story.','[["It is instructive to compare the two versions of the story.","مقایسه‌ی دو روایت از این داستان آموزنده است."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:intangible','intangible','adj','غیرقابل لمس، نامشهود','/ɪnˈtændʒəbl/ · nonmaterial; immaterial, untouchable','Collecting satisfies intangible desires.','[["Collecting satisfies intangible desires.","جمع آوری خواسته‌های ناملموس را ارضا می‌کند."],["Above the sea hovered a seagull, intangible as a dream.","مرغ دریایی، همچون رویایی، نامفهوم، بر فراز دریا شناور بود."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:intermingle','intermingle','v','با هم مخلوط کردن','/ˌɪn.tɚˈmɪŋ.ɡəl/ · interact, intermix','In the city, many different cultures intermingle.','[["In the city, many different cultures intermingle.","در این شهر، فرهنگ‌های مختلف با هم درآمیخته‌اند."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:inviolable','inviolable','adj','مصون، غیر قابل دسترسی و تغییر','/ɪnˈvaɪələbəl/ · allowing no attack; without exception, immune','Strict and inviolable gender roles have been fundamental to authoritarian regimes throughout history.','[["Strict and inviolable gender roles have been fundamental to authoritarian regimes throughout history.","نقش‌های جنسیتی سختگیرانه و غیرقابل نقض، در طول تاریخ برای رژیم‌های اقتدارگرا اساسی بوده‌اند."],["Inviolable gender roles are a form of authoritarianism.","نقش‌های جنسیتیِ خدشه‌ناپذیر، نوعی اقتدارگرایی هستند."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:irrecoverable','irrecoverable','adj','غیر قابل جبران، دائمی','/ˌiriˈkəvərəbəl/ · permanent, not able to be recovered','Some of the data was lost and is irrecoverable.','[["Some of the data was lost and is irrecoverable.","بخشی از اطلاعات از بین رفته و قابل بازیابی نیست."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:jettison','jettison','v','بیرون افکندن، آزادکردن','/zən/ · release, throw or drop (something) from an aircraft or ship','To save the lives of the people onboard, the crew had to jettison the cargo.','[["To save the lives of the people onboard, the crew had to jettison the cargo.","برای نجات جان سرنشینان، خدمه مجبور شدند محموله را به دریا بیندازند."],["Tom was jettisoned into the vacuum of space.","تام به درون خلاء فضا پرتاب شد."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:jolt','jolt','v','تکان دادن، تکان خوردن؛ تکان','/jōlt/ · 1)verb, jerk, to move suddenly, to give someone a sudden shock. 2)noun, a sudden shock','Fyodor was jolted awake by a noise.','[["Fyodor was jolted awake by a noise.","فئودور با صدایی از خواب پرید."],["She jolted her head back in surprise.","با تعجب سرش را به عقب تکان داد."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:juncture','juncture','n','پیوستگی','/ˈjəNGkCHər/ · connection, junction','I don''t want to jump into any conclusions at this juncture.','[["I don''t want to jump into any conclusions at this juncture.","نمی‌خواهم در این برهه از زمان، نتیجه‌گیری خاصی بکنم."],["He came to an important juncture in his life.","او به یک مرحله مهم در زندگی‌اش رسید."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:justly','justly','adv','عادلانه','/ˈjəstlē/ · rightly, fairly','The city is justly famous for its beautiful old buildings.','[["The city is justly famous for its beautiful old buildings.","این شهر به خاطر ساختمان‌های قدیمی و زیبایش به حق مشهور است."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:lading','lading','n','محموله، بارگیری','/ˈleɪdɪŋ/ · cargo, shipment, goods carried by a ship, plane, truck, etc., or the act of putting these goods on the vehicle','The captain checked the bill of lading before the ship left the port.','[["The captain checked the bill of lading before the ship left the port.","کاپیتان قبل از اینکه کشتی بندر را ترک کند، بارنامه را بررسی کرد."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:leisurely','leisurely','adj','با آسودگی، بدون عجله','/ˈleʒ.ɚ.li/ · slowly, if you do something in a leisurely way, you do it in a slow relaxed way, without hurrying','He imagined leisurely mornings without rush.','[["He imagined leisurely mornings without rush.","او صبح‌های آرام و بدون عجله را تصور می‌کرد."],["The leisurely women write many letters.","زنانِ با فراغت، نامه‌های زیادی می‌نویسند."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:liken','liken','v','مقایسه کردن','/ˈlaɪkən/ · to compare, equalize, [formal] to say that someone or something is similar to another person or thing','The hum of mating males has been likened to the buzz of a chain saw.','[["The hum of mating males has been likened to the buzz of a chain saw.","صدای وزوز نرهای جفت‌گیری‌کننده به صدای اره برقی تشبیه شده است."],["We often liken death to sleep.","ما اغلب مرگ را به خواب تشبیه می‌کنیم."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:locale','locale','n','محل، منطقه','/ˈloʊkeɪt/ · 1)place2)find','The small village was the perfect locale for the film.','[["The small village was the perfect locale for the film.","آن روستای کوچک، لوکیشن بی‌نظیری برای فیلم بود."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:luxuriant','luxuriant','adj','مجلل، انبوه، پربرکت','/ləɡˈʒʊriənt/ · thriving, lush, luxurious','The valley is covered with luxuriant vegetation.','[["The valley is covered with luxuriant vegetation.","این دره پوشیده از پوشش گیاهی سرسبز و انبوه است."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:magnify','magnify','v','بزرگ کردن، زیر ذره بین بزرگ کردن','/ˈmæɡnɪfaɪ/ · enlarge; increase, amplify','Let me borrow your magnifying glass.','[["Let me borrow your magnifying glass.","بذار ذره‌بینت رو قرض بگیرم."],["Give me the magnifying glass, please.","لطفا ذره بین را به من بدهید."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:malleable','malleable','adj','نرم و قابل انعطاف','/ˈmæliəbəl/ · pliable , flexible','Lead is a soft, dense, malleable and fusible metal.','[["Lead is a soft, dense, malleable and fusible metal.","سرب فلزی نرم، چگال، چکش‌خوار و گدازپذیر است."],["The material is also malleable at low temperatures.","این ماده همچنین در دماهای پایین انعطاف‌پذیر است."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:markedly','markedly','adv','به طرز محسوسی، به طور قابل توجه‌ای','/ˈmɑːr.kɪd.li/ · distinctly, noticeably, to an extent that is clearly noticeable; significantly','The weather has improved markedly since yesterday.','[["The weather has improved markedly since yesterday.","از دیروز هوا به طور قابل توجهی بهتر شده است."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:marvelously','marvelously','adv','حیرت آور، عجیب، جالب','/ˈmɑr·və·ləs·li/ · remarkably, wonderfully, superbly','The old machine still works marvelously well.','[["The old machine still works marvelously well.","دستگاه قدیمی هنوز هم به طرز شگفت انگیزی خوب کار می‌کند."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:materialize','materialize','v','صورت خارجی به خود گرفتن، جامه عمل بخود پوشیدن','/məˈtɪriəlaɪz/ · come into being, become actual fact; happen','Tom''s plans failed to materialize.','[["Tom''s plans failed to materialize.","نقشه‌های تام عملی نشد."],["Mary''s dreams were finally materializing.","بالاخره رویاهای مریم داشت به واقعیت تبدیل می‌شد."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:mere-subsistence','mere subsistence','phr','حداقل معاش، زندگی بخور و نمیر','minimum survival','Many early farmers produced only enough for mere subsistence.','[["Many early farmers produced only enough for mere subsistence.","بسیاری از کشاورزان اولیه فقط به اندازه‌ای تولید می‌کردند که صرفاً برای امرار معاش کافی باشد."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:meticulously','meticulously','adv','با دقت بسیار','/məˈtɪkjələsli/ · carefully, minutely','Anna meticulously cleaned her room.','[["Anna meticulously cleaned her room.","آنا با دقت اتاقش را تمیز کرد."],["Fyodor packed his gear meticulously.","فئودور وسایلش را با دقت جمع کرد."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:minuscule','minuscule','adj','خیلی کوچک','/ˈmɪnəskjuːl/ · extremely small, tiny, miniature','The amount of arsenic in the water is minuscule but significant.','[["The amount of arsenic in the water is minuscule but significant.","مقدار آرسنیک موجود در آب ناچیز اما قابل توجه است."],["The thrust of this spacecraft is minuscule.","نیروی رانش این فضاپیما بسیار ناچیز است."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:minutely','minutely','adv','به‌طور دقیق','/maɪˈnuːtli/ · finely, in detail, meticulously','The scientist examined the leaf minutely under a microscope.','[["The scientist examined the leaf minutely under a microscope.","دانشمند برگ را با دقت زیر میکروسکوپ بررسی کرد."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:misconception','misconception','n','تصور غلط','/ˌmɪskənˈsepʃən/ · wrong idea, misunderstanding','Unfortunately, this misconception is very persistent.','[["Unfortunately, this misconception is very persistent.","متأسفانه این باور غلط خیلی جا افتاده است."],["That is a relatively widespread misconception.","این یک تصور غلط نسبتاً رایج است."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:modestly','modestly','adv','ساده، تواضع، با فروتنی','/ˈmɑːdɪstli/ · humbly','Daniel told Amanda to dress modestly.','[["Daniel told Amanda to dress modestly.","دنیل به آماندا گفت که لباس‌هایش را با وقار بپوشد."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:momentous','momentous','adj','بسیار مهم','/məʊˈmentəs/ · significant, of great importance, especially in its bearing on the future','The invention of printing was a momentous event in human history.','[["The invention of printing was a momentous event in human history.","اختراع چاپ، رویدادی مهم در تاریخ بشر بود."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:monopolize','monopolize','v','انحصاری کردن، به خود اختصاص دادن، به دیگران مجال ندادن','/məˈnɒpəlaɪz/ · dominate','They monopolized the supply of raw materials and set sky-high prices.','[["They monopolized the supply of raw materials and set sky-high prices.","آنها عرضه مواد اولیه را در انحصار خود داشتند و قیمت‌های سرسام‌آوری تعیین می‌کردند."],["Don''t let the children monopolize the television.","نگذارید بچه‌ها تلویزیون را در انحصار خود بگیرند."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:monotone','monotone','adj','یکنواخت و خسته‌کننده','/ˈmɒnətəʊn/ · tedious, boring, a continuing sound, especially of someone''s voice','Paul said that in a very monotone and slow voice.','[["Paul said that in a very monotone and slow voice.","پاول این را با صدای بسیار یکنواخت و آهسته گفت."],["Daniel was reading the words in a monotone voice like a robot.","دنیل داشت کلمات را با صدای یکنواخت مثل یک ربات می‌خواند."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:nocturnal','nocturnal','adj','شبانه، حیواناتی که در شب فعالیت میکنند','/nɑːkˈtɝː.nəl/ · nighttime1) [formal] happening at night2)an animal that is nocturnal is active at night','Owls are nocturnal birds.','[["Owls are nocturnal birds.","جغدها پرندگان شبگرد هستند."],["Bats are nocturnal animals.","خفاش‌ها حیوانات شب زی هستند."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:oblige','oblige','v','وادار کردن، مجبور کردن','/əˈblaɪdʒ/ · require, force, if you are obliged to do something, you have to do it because the situation, the law, a duty etc makes it necessary','Thank you very much! Much obliged.','[["Thank you very much! Much obliged.","خیلی ممنونم! خیلی لطف کردی."],["What am I obliged to do?","من موظف به انجام چه کاری هستم؟"]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:omit','omit','v','حذف کردن، از قلم انداختن','/oʊˈmɪt/ · 1)neglect 2)exclude','Make sure nothing is omitted.','[["Make sure nothing is omitted.","مطمئن شوید که چیزی از قلم نیفتاده باشد."],["You omitted one important fact.","شما یک حقیقت مهم را از قلم انداختید."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:orchestrate','orchestrate','v','هماهنگ و موزون کردن، اداره کردن','/ˈɔːrkəstreɪt/ · stage-manage','They orchestrated the entire thing.','[["They orchestrated the entire thing.","آنها کل ماجرا را سازماندهی کردند."],["The attack has been orchestrated.","این حمله سازماندهی شده است."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ornamentation','ornamentation','n','پیرایش','/ˌɔːrnəmenˈteɪʃən/ · decoration','He is singing with a lot of ornamentation.','[["He is singing with a lot of ornamentation.","او با تزئینات فراوان آواز می‌خواند."],["Proverbs are an ornamentation of speech.","ضرب المثل‌ها زینت کلام هستند."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ostentatious','ostentatious','adj','متظاهر، خودنما','/ɑːstənˈteɪʃəs/ · showy, designed to impress or attract notice','They live in an ostentatious villa.','[["They live in an ostentatious villa.","آنها در یک ویلای خودنمایی زندگی می‌کنند."],["She wore an ostentatious diamond ring.","او یک حلقه الماس خودنمایی می‌کرد."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:outermost','outermost','adj','از اقصی نقطه، از دورترین نقطه خارج','/ˈaʊtərmoʊst/ · farthermost away','The exosphere is the outermost layer of our atmosphere.','[["The exosphere is the outermost layer of our atmosphere.","اگزوسفر بیرونی‌ترین لایه جو زمین است."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:pacify','pacify','v','آرام کردن، فرونشاندن، تسکین دادن','/ˈpæsɪfaɪ/ · assuage , silence, soothe','You''re absurd if you think flowers alone will pacify him.','[["You''re absurd if you think flowers alone will pacify him.","اگر فکر می‌کنی گل‌ها به تنهایی او را آرام می‌کنند، احمق هستی."],["He finds it easier to just pacify her than be straight up with her.","برایش آسان‌تر است که فقط او را آرام کند تا اینکه با او رک و راست باشد."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:paradoxically','paradoxically','adv','به شکلی متناقض، ظاهراً','/ˌpærəˈdɑːksɪkli/ · seemingly, seemingly absurd or self-contradictory','Paradoxically, she craves social interaction while refusing to leave her house.','[["Paradoxically, she craves social interaction while refusing to leave her house.","به طور متناقضی، او در حالی که از ترک خانه‌اش امتناع می‌کند، مشتاق تعامل اجتماعی است."],["Paradoxically, drinkable water is the first thing in short supply after a flood.","به طور متناقضی، آب آشامیدنی اولین چیزی است که پس از سیل کمیاب می‌شود."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:pare-away','pare away','phr','کم کردن، تراشیدن، پوست کندن','/per əˈweɪ/ · remove, peel (off), trim (something) by cutting away its outer edges','The editor pared away unnecessary words from the article.','[["The editor pared away unnecessary words from the article.","ویراستار کلمات غیرضروری را از مقاله حذف کرد."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:perceptible','perceptible','adj','قابل درک، ادراک شدنی، محسوس','/pərˈseptəbəl/ · 1)noticeable 2)appreciable','The difference between the two colors is barely perceptible.','[["The difference between the two colors is barely perceptible.","تفاوت بین این دو رنگ به سختی قابل تشخیص است."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:perilous','perilous','adj','مخاطره امیز، خطرناک','/ˈperələs/ · 1)dangerous 2)hazardous 3)risky 4)toxic','Crossing the ice was a perilous challenge.','[["Crossing the ice was a perilous challenge.","عبور از یخ یک چالش خطرناک بود."],["You are in a perilous state, oh shepherd.","ای چوپان، تو در وضعیت خطرناکی هستی."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:perishable','perishable','adj','فاسد شدنی، نابود شدنی','/ˈperɪʃəbəl/ · easy to spoil','Fresh figs are very fragile and highly perishable.','[["Fresh figs are very fragile and highly perishable.","انجیر تازه بسیار شکننده و به سرعت فاسد می‌شود."],["During hot season, perishables go bad easily.","در طول فصل گرما، مواد فاسدشدنی به راحتی فاسد می‌شوند."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:perpetuate','perpetuate','v','جاودانی ساختن، دائمی کردن','/pərˈpetʃueɪt/ · maintain/ immortalize, to make a situation, attitude etc, especially a bad one, continue to exist for a long time','Lonely people perpetuate their own loneliness through their fear of others.','[["Lonely people perpetuate their own loneliness through their fear of others.","افراد تنها، تنهایی خود را از طریق ترس از دیگران تداوم می‌بخشند."],["Unequal access to quality education perpetuates this uneven income distribution.","دسترسی نابرابر به آموزش باکیفیت، این توزیع ناعادلانه درآمد را تداوم می‌بخشد."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:pigmentation','pigmentation','n','رنگی، رنگ کردن','/ˌpɪɡmənˈteɪʃən/ · 1)coloring 2)dye','The pigmentation of the skin protects it from sunlight.','[["The pigmentation of the skin protects it from sunlight.","رنگدانه‌های پوست، آن را در برابر نور خورشید محافظت می‌کنند."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:plumage','plumage','n','پر، پرهای زینتی','/ˈpluːmɪdʒ/ · feather','Tawny owls are well camouflaged by the colour of their plumage.','[["Tawny owls are well camouflaged by the colour of their plumage.","جغدهای قهوه‌ای به خوبی توسط رنگ پرهایشان استتار می‌شوند."],["Tawny owls have a grey or brown plumage.","جغدهای قهوه‌ای رنگ، پرهای خاکستری یا قهوه‌ای دارند."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:pocketbook','pocketbook','n','توان مالی، کیف پول','/ˈpɑː.kɪt.bʊk/ · affordable, the amount of money that you have, or your ability to pay for things','When I felt for my pocketbook I found it was gone.','[["When I felt for my pocketbook I found it was gone.","وقتی دنبال کیف پولم گشتم، دیدم که نیست."],["Is anything missing from your pocketbook?","چیزی از کیف پولت کم شده؟"]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:pore','pore','n','روزنه، سوراخ ریز، خلل و فرج','/pɔːr/ · space, hole, one of the very small holes in your skin that sweat can pass through; one of the similar small holes in the surface of a plant or a rock','Experts will now pore over the fine print of the contract.','[["Experts will now pore over the fine print of the contract.","اکنون کارشناسان جزئیات قرارداد را با دقت بررسی خواهند کرد."],["Virgilius was fond of books, and pored over them all day long.","ویرژیلیوس عاشق کتاب بود و تمام روز آنها را با دقت مطالعه می‌کرد."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:posit','posit','v','فرض کردن','/ˈpɑːzɪt/ · assume, propose, suggest','Some scientists posit that life began in the deep oceans.','[["Some scientists posit that life began in the deep oceans.","برخی از دانشمندان معتقدند که حیات در اعماق اقیانوس‌ها آغاز شده است."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:postulate','postulate','v','مسلم فرض کردن، فرض کردن','/ˈpɑːstʃəleɪt/ · hypothesize, presume','Biodynamic agriculture is based on anthroposophy, a philosophy founded by Rudolf Steiner, which postulates the existence of a spiritual world.','[["Biodynamic agriculture is based on anthroposophy, a philosophy founded by Rudolf Steiner, which postulates the existence of a spiritual world.","کشاورزی بیودینامیک مبتنی بر آنتروپوسوفی است، فلسفه‌ای که توسط رودولف اشتاینر بنیان نهاده شد و وجود یک جهان معنوی را فرض می‌کند."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:precarious','precarious','adj','متزلزل، پرمخاطره','/prɪˈkeriəs/ · insecure, dangerously likely to fall or collapse, dependent on chance','Many workers have precarious jobs.','[["Many workers have precarious jobs.","بسیاری از کارگران مشاغل نامطمئن دارند."],["The economy is in a precarious state.","اقتصاد در وضعیت ناپایداری قرار دارد."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:precede','precede','v','جلوتر بودن','/prɪˈsiːd/ · be beyond, come before','in the moments which immediately preceded the earthquake','[["in the moments which immediately preceded the earthquake","در لحظاتی که بلافاصله قبل از زلزله بود"],["I know all about you. Your reputation precedes you.","من همه چیز را در مورد تو می‌دانم. آبروی تو از خودت مهم‌تر است."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:precipitate','precipitate','v','تسریع کردن','/prɪˈsɪp.ə.teɪt/ · bring about, to make something happen suddenly or sooner than expected','A sudden decline in stock prices could precipitate a financial crisis.','[["A sudden decline in stock prices could precipitate a financial crisis.","کاهش ناگهانی قیمت سهام می‌تواند بحران مالی را تسریع کند."],["The clouds thickened and it started to precipitate.","ابرها متراکم شدند و شروع به باریدن کردند."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:preclude','preclude','v','مانع شدن','/prɪˈkluːd/ · rule out, prevent, impede, prohibit','Lack of money precludes travel.','[["Lack of money precludes travel.","بی پولی مانع از سفر می‌شود."],["His injury precluded him from playing.","مصدومیت او را از بازی کردن باز داشت."]]','t1212',23,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:predicament','predicament','n','مخمصه','difficult situation, serious situation','She found herself in a difficult predicament.','[["She found herself in a difficult predicament.","او خود را در مخمصه سختی یافت."],["She was in an uncomfortable predicament today.","او امروز در وضعیت ناخوشایندی قرار داشت."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:predominant','predominant','adj','غالب، چیره، عمده','/prɪˈdɑːmɪnənt/ · very noticeable, most aggressive, principal, dominant','The region is predominantly rural.','[["The region is predominantly rural.","این منطقه عمدتاً روستایی است."],["That’s because kids with autism are predominantly male, with boys outnumbering girls by a ratio of 4 to 1.","دلیلش این است که کودکان مبتلا به اوتیسم عمدتاً پسرند و نسبت پسران به دختران ۴ به ۱ است."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:preeminent','preeminent','adj','برجسته، افضل','/priˈem·ə·nənt/ · important, foremost, prominent','That impish man is a preeminent economist.','[["That impish man is a preeminent economist.","آن مرد شیطان صفت، یک اقتصاددان برجسته است."],["Monge stood preeminent above his contemporaries.","مونژ از معاصران خود برتر بود."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:preoccupation','preoccupation','n','شیفتگی، تمایل','/priːˌɑː.kjəˈpeɪ.ʃən/ · concentration on, when someone thinks or worries about something a lot, with the result that they do not pay attention to other things','Don''t open your mouth, and your physiognomy demonstrates a preoccupation.','[["Don''t open your mouth, and your physiognomy demonstrates a preoccupation.","دهانت را باز نکن، قیافه‌ات نشان می‌دهد که مشغولی."],["My major preoccupation is the question, ''What is reality?''","دغدغه اصلی من این سوال است که «واقعیت چیست؟»"]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:preordain','preordain','v','قبلا وقوع امری را ترتیب دادن','/ˌpriː.ɔːrˈdeɪn/ · ordain, appoint, foreordain, decide or determine (an outcome or course of action) beforehand','My life seems to have followed a preordained path.','[["My life seems to have followed a preordained path.","انگار زندگیم یه مسیر از پیش تعیین شده رو طی کرده."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:preponderance','preponderance','n','برتری، غلبه، اکثریت','/prɪˈpɑːn.dɚ.əns/ · majority','To decide means to succumb to the preponderance of one set of influences over another set.','[["To decide means to succumb to the preponderance of one set of influences over another set.","تصمیم گرفتن به معنای تسلیم شدن در برابر غلبه‌ی یک مجموعه از تأثیرات بر مجموعه‌ای دیگر است."],["In legal terms, the \"preponderance of evidence\" is a lower standard of proof than \"clear and convincing evidence\".","در اصطلاح حقوقی، «غلبه شواهد» معیار پایین‌تری برای اثبات نسبت به «شواهد واضح و قانع‌کننده» است."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:prerequisite','prerequisite','n','پیش نیاز، شرط لازم','/prerequisite/ · requirement, something needed to happenas a prior condition, something required','What are the prerequisites for a child to learn the piano?','[["What are the prerequisites for a child to learn the piano?","پیش‌نیازهای یادگیری پیانو برای کودکان چیست؟"],["Having good credit is a prerequisite to applying for a loan.","داشتن اعتبار خوب، شرط لازم برای درخواست وام است."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:presumable','presumable','adj','محتمل، قابل فرض','probable, supposable','The presumable cause of the fire was an electrical fault.','[["The presumable cause of the fire was an electrical fault.","علت احتمالی آتش‌سوزی اتصال برق بوده است."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:prohibitive','prohibitive','adj','گران','/prəˈhɪbətɪv/ · unaffordable, expensive, difficult or impossible to pay','The cost of the treatment was prohibitive for most families.','[["The cost of the treatment was prohibitive for most families.","هزینه درمان برای اکثر خانواده‌ها کمرشکن بود."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:prolifically','prolifically','adv','به وفور، پربارانه','/prəˈlɪfɪkli/ · abundantly','The author wrote prolifically, publishing more than fifty books.','[["The author wrote prolifically, publishing more than fifty books.","نویسنده به طور گسترده نوشت و بیش از پنجاه کتاب منتشر کرد."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:prolong','prolong','v','طولانی کردن','/prəˈlɔːŋ/ · extend, lengthen, extend the duration of','Healthy food prolongs your life.','[["Healthy food prolongs your life.","غذای سالم عمر شما را طولانی می‌کند."],["Gooseberries can prolong your life.","انگور فرنگی می‌تواند عمر شما را طولانی کند."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:propagate','propagate','v','رواج دادن','/ˈprɑːpəɡeɪt/ · 1)multiply, reproduce, breed, 2)spread and promote (an idea, theory, etc.) widely','I want to propagate the oleander.','[["I want to propagate the oleander.","من می‌خواهم خرزهره را تکثیر کنم."],["Ziri wants to propagate his heather.","زیری می‌خواهد هدرش را تبلیغ کند."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:propel','propel','v','سوق دادن، فشار دادن','/prəˈpel/ · push, drive, push, or cause to move in a particular direction, typically forward','Algeria needs to propel its economy forward.','[["Algeria needs to propel its economy forward.","الجزایر باید اقتصاد خود را به جلو سوق دهد."],["Economic diversification will propel Algeria into the post-oil era.","تنوع اقتصادی، الجزایر را به دوران پس از نفت سوق خواهد داد."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:proponent','proponent','n','حامی','/prəˈpoʊnənt/ · supporter, a person who advocates a theory, proposal, or project','She''s a strong proponent of renewable energy.','[["She''s a strong proponent of renewable energy.","او طرفدار قوی انرژی‌های تجدیدپذیر است."],["Proponents of increased import duties are at odds with each other.","موافقان افزایش عوارض واردات با یکدیگر اختلاف نظر دارند."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:protrude','protrude','v','خارج شدن','/proʊˈtruːd/ · project, stick out, extend, extend beyond or above a surface','Moreover, when viewed from the side, the front teeth are protruding.','[["Moreover, when viewed from the side, the front teeth are protruding.","علاوه بر این، وقتی از پهلو به او نگاه می‌کنید، دندان‌های جلویی بیرون زده هستند."],["In this type of break, the bone will actually protrude from the skin.","در این نوع شکستگی، استخوان در واقع از پوست بیرون می‌زند."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ramification','ramification','n','انشعاب، نتیجه، شاخه','/ræmɪfɪˈkeɪʃən/ · consequence, branch, outcome','The decision has serious ramifications.','[["The decision has serious ramifications.","این تصمیم تبعات جدی دارد."],["The ramifications of his execution was much greater than any of them expected.","پیامدهای اعدام او بسیار بیشتر از آن چیزی بود که هر یک از آنها انتظار داشتند."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ravage','ravage','v','از بین رفتن','/ˈrævɪdʒ/ · destroy, devastate, ruin, havoc, cause severe and extensive damage to','Our land was ravaged by the fire.','[["Our land was ravaged by the fire.","سرزمین ما در آتش سوخت."],["The flycatcher has ravaged the flies.","مگس‌گیر مگس‌ها را نابود کرده است."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:receptivity-to','receptivity to','n','قدرت پذیرش','/ˌriːsepˈtɪvəti/ · openness to','What fans describe as receptivity to psychic energy is probably just indigestion.','[["What fans describe as receptivity to psychic energy is probably just indigestion.","آنچه طرفداران به عنوان پذیرش انرژی روانی توصیف می‌کنند، احتمالاً فقط سوء هاضمه است."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:recur','recur','v','عود کردن، تکرار شدن','/rɪˈkɜːr/ · repeat, occur again, periodically, or repeatedly','Life sometimes feels like a recurring journey.','[["Life sometimes feels like a recurring journey.","زندگی گاهی اوقات مثل یک سفر تکراری به نظر می‌رسد."],["This seems to be a recurring problem.","به نظر می‌رسد این یک مشکل تکراری است."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:refine','refine','v','پالودن، تصفیه کردن، بهبود دادن','/rɪˈfaɪn/ · improve, purify, process, treat','Engineers spent many months refining the software.','[["Engineers spent many months refining the software.","مهندسان ماه‌های زیادی را صرف پالایش نرم افزار کردند."],["She refines the experimental design.","او طرح آزمایشی را اصلاح می‌کند."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:regenerate','regenerate','v','احیاء کردن','/rɪˈdʒenəreɪt/ · renew, revive, restore','If intelligent design is true, why can''t we regenerate our teeth?','[["If intelligent design is true, why can''t we regenerate our teeth?","اگر طراحی هوشمند درست است، چرا نمی‌توانیم دندان‌هایمان را بازسازی کنیم؟"],["Your health regenerates if your food bar is at over nine drumsticks.","اگر تعداد چوب‌های درام در نوار غذایتان از نه بیشتر باشد، سلامتی‌تان بازیابی می‌شود."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:regrettable','regrettable','adj','نامبارک، متاسفانه','/riˈgretəbəl/ · unfortunate; undesirable; unwelcome','This is regrettable but unavoidable.','[["This is regrettable but unavoidable.","این تاسف‌بار است اما اجتناب‌ناپذیر."],["I made a regrettable mistake.","من یک اشتباه پشیمان کننده مرتکب شدم."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:repercussion','repercussion','n','عکس العمل، تاثیر','/ˌriːpəˈkʌʃən/ · effect','There will be repercussions, all right. You can count on that.','[["There will be repercussions, all right. You can count on that.","باشه، عواقبی خواهد داشت. می‌تونی روش حساب کنی."],["The thieves retreated due to being afraid of repercussions.","دزدان از ترس عواقب کار، عقب‌نشینی کردند."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:replenish','replenish','v','دوباره پر کردن','/rɪˈplenɪʃ/ · 1)refill 2)restore','He wanted to replenish the stock as soon as possible.','[["He wanted to replenish the stock as soon as possible.","او می‌خواست هر چه سریع‌تر موجودی را دوباره پر کند."],["A military veteran shows how his compost business helps to replenish precious topsoil.","یک کهنه سرباز نظامی نشان می‌دهد که چگونه کسب و کار کمپوست او به تجدید خاک ارزشمند سطحی کمک می‌کند."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:replicas','replicas','n','کپی، المثنی','/ˈreplɪkə/ · copies','There exist various replicas of the Statue of Liberty scattered around the world.','[["There exist various replicas of the Statue of Liberty scattered around the world.","کپی‌های مختلفی از مجسمه آزادی در سراسر جهان پراکنده شده‌اند."],["There are replicas of the Eiffel Tower in Japan and China.","کپی‌هایی از برج ایفل در ژاپن و چین وجود دارد."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:repudiate','repudiate','v','انکار کردن، رد کردن','/rɪˈpjuːdieɪt/ · reject','Catholicism repudiates the idea of reincarnation.','[["Catholicism repudiates the idea of reincarnation.","کاتولیک‌ها ایده تناسخ را رد می‌کنند."],["The failed scientist''s work was repudiated.","کار دانشمند شکست خورده رد شد."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:retrospect','retrospect','n','نگاه به گذشته، پس نگری','/ˈretrəspekt/ · look back, thinking now about something in the past','In retrospect, I should have known that it was a scam.','[["In retrospect, I should have known that it was a scam.","حالا که به گذشته نگاه می‌کنم، باید می‌دانستم که این یک کلاهبرداری بود."],["In retrospect, I should have treated her with more respect.","حالا که به گذشته نگاه می‌کنم، باید با احترام بیشتری با او رفتار می‌کردم."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:revolutionize','revolutionize','v','تغییر اساسی دادن','/ˌrevəˈluːʃənaɪz/ · change dramatically','The invention revolutionized long- distance communication.','[["The invention revolutionized long- distance communication.","این اختراع ارتباطات راه دور را متحول کرد."],["Einstein''s ideas revolutionized modern physics.","ایده‌های اینشتین فیزیک مدرن را متحول کرد."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:rigidly','rigidly','adv','به طور سخت گیرانه، به شدت','/ˈrɪdʒɪdli/ · strictly','Actual objects can conform rigidly to the four basic form cube, cylinder, cone and sphere.','[["Actual objects can conform rigidly to the four basic form cube, cylinder, cone and sphere.","اشیاء واقعی می‌توانند به طور دقیق با چهار شکل اساسی مکعب، استوانه، مخروط و کره مطابقت داشته باشند."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:rigors','rigors','n','دشواری‌ها','/ˈrɪɡə/ · difficulties','Spring swept away the rigors of the cold winter.','[["Spring swept away the rigors of the cold winter.","بهار، سختی‌های زمستان سرد را از بین برد."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:rudiment','rudiment','n','اصول ابتدایی','/ˈruːdəmənt/ · basic','The course teaches the rudiments of computer programming.','[["The course teaches the rudiments of computer programming.","این دوره اصول اولیه برنامه‌نویسی کامپیوتر را آموزش می‌دهد."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:rudimentary','rudimentary','adj','بدوی، ساده','/ˌruːdəˈmentəri/ · primitive, basic','Digital cameras aren''t as good as rudimentary cameras.','[["Digital cameras aren''t as good as rudimentary cameras.","دوربین‌های دیجیتال به خوبی دوربین‌های ابتدایی نیستند."],["She has a rudimentary grasp of the Berber language.","او درک اولیه‌ای از زبان بربر دارد."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:rupture','rupture','v','گسستن، جدا کردن','/ˈrʌptʃə/ · burst','Becoming rivals in love caused the rupture of friendship.','[["Becoming rivals in love caused the rupture of friendship.","رقیب عشقی شدن باعث از هم پاشیدن دوستی شد."],["After extensively studying the quake and its aftermath, scientists say the rupture is unprecedented.","دانشمندان پس از مطالعه گسترده زلزله و پیامدهای آن، می‌گویند که این گسیختگی بی‌سابقه است."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:scant','scant','adj','اندک، ناکافی، ناقص','/skænt/ · minimal','The volunteer firefighters fought the blaze bravely, with scant regard for their own safety.','[["The volunteer firefighters fought the blaze bravely, with scant regard for their own safety.","آتش نشانان داوطلب شجاعانه و بدون توجه به ایمنی خود، با آتش جنگیدند."],["Your message was scant on details.","پیام شما فاقد جزئیات بود."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:scanty','scanty','adj','اندکی، کم، بسیار کم','/ˈskæn.ti/ · thin adj','The rice crop was scanty this year.','[["The rice crop was scanty this year.","امسال محصول برنج کم بود."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:scorching','scorching','adj','بشدت گرم، سوزان، داغ','/ˈskɔːr.tʃɪŋ/ · exceedingly hot','The desert sun was scorching hot.','[["The desert sun was scorching hot.","آفتاب صحرا، سوزان و سوزاننده بود."],["The scorching sun roasted me.","آفتاب سوزان مرا سوزاند."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:scorn','scorn','n','تمسخر، تحقیر، تنفر','/skɔːrn/ · despise','Don''t speak of holy things with such scorn, not even jokingly.','[["Don''t speak of holy things with such scorn, not even jokingly.","با چنین تحقیری، حتی به شوخی، از مقدسات صحبت نکن."],["True artists scorn nothing; they force themselves to understand instead of judging.","هنرمندان واقعی هیچ چیز را تحقیر نمی‌کنند؛ آنها خود را مجبور به فهمیدن می‌کنند، نه قضاوت کردن."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:scrutinize','scrutinize','v','به دقت بررسی کردن، موشکافی کردن','/ˈskruː.tən.aɪz/ · examine v.','The lawyer scrutinized the contract.','[["The lawyer scrutinized the contract.","وکیل قرارداد را به دقت بررسی کرد."],["Customs officers scrutinized our passports.","ماموران گمرک پاسپورت‌های ما را بررسی کردند."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sculpt','sculpt','v','حجاری، حجاری کردن، مجسمه سازی','/skʌlpt/ · shape','The sculptor is sculpting a statue of a lion.','[["The sculptor is sculpting a statue of a lion.","مجسمه‌ساز در حال ساختن مجسمه یک شیر است."],["The carver sculpted an ice sculpture for the festival.","این کنده‌کار برای جشنواره یک مجسمه یخی ساخت."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:secrete','secrete','v','ترشح کردن، تولید کردن، تراوش کردن','/sɪˈkriːt/ · producesecretion (n)','Some plants secrete a sticky substance to trap insects.','[["Some plants secrete a sticky substance to trap insects.","بعضی از گیاهان ماده‌ای چسبناک ترشح می‌کنند تا حشرات را به دام بیندازند."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sedentary','sedentary','adj','نشسته، بی تحرک','/ˈsed.ən.ter.i/ · settled','A sedentary lifestyle is unhealthy.','[["A sedentary lifestyle is unhealthy.","سبک زندگی بی تحرک ناسالم است."],["A sedentary lifestyle can lead to health problems.","یک سبک زندگی بی تحرک می‌تواند منجر به مشکلات سلامتی شود."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:seething','seething','adj','جوشان، پرجنب‌وجوش؛ (از خشم) جوشیدن','/ˈsiː.ðɪŋ/ · 1) active, (of a large number or amount) to move around energetically in a small space, 2) excited','The square was seething with people.','[["The square was seething with people.","میدان مملو از جمعیت بود."],["Rodrigo was seething in anger.","رودریگو از شدت عصبانیت داشت منفجر می‌شد."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sequent','sequent','adj','پیرو، پی در پی، بعد','/siː.kwənt/ · later; following','The report describes the flood and the sequent damage to farms.','[["The report describes the flood and the sequent damage to farms.","این گزارش، سیل و خسارات ناشی از آن به مزارع را شرح می‌دهد."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:serene','serene','adj','بی سروصدا، آرام، سکوت','/səˈriːn/ · calm, silent','The night was serene, the sky a sea of velvety black.','[["The night was serene, the sky a sea of velvety black.","شب آرام بود، آسمان دریایی از سیاهی مخملی."],["Taiwan is renowned for its natural hot springs and serene mountain retreats.","تایوان به خاطر چشمه‌های آب گرم طبیعی و اقامتگاه‌های کوهستانی آرام خود مشهور است."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sever','sever','v','قطع کردن، جدا کردن','/ˈsevər/ · cut off, to cut something into two pieces; to cut something off something','The storm severed the power lines to the town.','[["The storm severed the power lines to the town.","طوفان خطوط برق شهر را قطع کرد."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:shatter','shatter','v','شکستن، خرد شدن، خراب شدن','/ˈʃæt.ɚ/ · destroy v.','Trust is fragile, and sometimes it shatters easily.','[["Trust is fragile, and sometimes it shatters easily.","اعتماد شکننده است و گاهی اوقات به راحتی از بین می‌رود."],["The betrayal shattered the trust they had built.","این خیانت، اعتمادی را که آنها ایجاد کرده بودند، از بین برد."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:shiver','shiver','v','لرزیدن (از سرما، ترس و ...)','/ˈʃɪv.ɚ/ · tremor','Ziri began to shiver from the cold.','[["Ziri began to shiver from the cold.","زیری از سرما شروع به لرزیدن کرد."],["Ziri got out onto the shore, shivering.","زیری در حالی که می‌لرزید، به ساحل رسید."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:singularly','singularly','adv','فوق العاده، بخصوص، بویژه','/ˈsɪŋ.ɡjə.lɚ.li/ · particularly','Our attitude toward plants is singularly narrow.','[["Our attitude toward plants is singularly narrow.","نگرش ما نسبت به گیاهان به طرز عجیبی محدود است."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:snaking','snaking','adj','مارپیچ، پیچ‌درپیچ','winding','A long line of cars was snaking along the mountain road.','[["A long line of cars was snaking along the mountain road.","صف طولانی ماشین‌ها در امتداد جاده کوهستانی به صورت مارپیچ در حرکت بود."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:solicit','solicit','v','درخواست کردن، خواستار بودن، التماس کردن','/səˈlɪs.ɪt/ · request','What is your reason for soliciting a conversation with me?','[["What is your reason for soliciting a conversation with me?","دلیلت برای درخواست گفتگو با من چیه؟"],["Bids were solicited for the building of the bridge.","برای ساخت پل، مناقصه برگزار شد."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sophistication','sophistication','n','تکنولوژی، پیچیدگی','/səˌfɪs.təˈkeɪ.ʃən/ · technology n.','The sophistication of ancient Roman engineering still amazes experts.','[["The sophistication of ancient Roman engineering still amazes experts.","پیچیدگی مهندسی روم باستان هنوز هم متخصصان را شگفت‌زده می‌کند."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:speciation','speciation','n','گونه زایی','/ˌspiː.ʃiˈeɪ.ʃən/ · evolution','Isolation on islands often leads to speciation.','[["Isolation on islands often leads to speciation.","انزوا در جزایر اغلب منجر به گونه‌زایی می‌شود."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:splendor','splendor','n','شکوه و جلال','/u)/ · magnificence n.','Well, best not to let my splendor go to waste!','[["Well, best not to let my splendor go to waste!","خب، بهتره نذارم شکوه و جلالم هدر بره!"],["We were amazed by the splendor of the scenery.","ما از شکوه و جلال مناظر شگفت‌زده شدیم."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sporadic','sporadic','adj','متناوب','/spəˈræd.ɪk/ · intermittent, irregular','Apart from hearing sporadic gunfire, the day was pretty quiet.','[["Apart from hearing sporadic gunfire, the day was pretty quiet.","گذشته از شنیدن صدای تیراندازی پراکنده، روز نسبتاً آرامی بود."],["Sporadic rebel campaigns continued throughout 2006 and 2007.","مبارزات پراکنده شورشیان در طول سال‌های ۲۰۰۶ و ۲۰۰۷ ادامه یافت."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sporadically','sporadically','adv','گاه و بیگاه','/spəˈræd.ɪ.kəl.i/ · occasionally','Does the error occur regularly or sporadically? Is the error reproducible?','[["Does the error occur regularly or sporadically? Is the error reproducible?","آیا خطا به طور منظم یا گاه به گاه رخ می‌دهد؟ آیا خطا قابل تکرار است؟"],["I''m disabled and sporadically employed.","من معلول هستم و گهگاه شاغل هستم."]]','t1212',24,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:spottily','spottily','adv','گاه و بیگاه','/\ˈspä-tə-lē\/ · occasionally','The region is only spottily covered by mobile networks.','[["The region is only spottily covered by mobile networks.","این منطقه فقط به صورت مقطعی تحت پوشش شبکه‌های تلفن همراه است."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:stagnation','stagnation','n','رکود','/stæɡˈneɪʃən/ · inactivity','Algeria''s economy is suffering from stagnation.','[["Algeria''s economy is suffering from stagnation.","اقتصاد الجزایر از رکود رنج می‌برد."],["Is Algeria doomed to stagnation?","آیا الجزایر محکوم به رکود است؟"]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:staunch','staunch','adj','وفادار','/stɑːntʃ/ · strong, loyal, firm','He was a staunch devotee who had unflinching faith.','[["He was a staunch devotee who had unflinching faith.","او مؤمنی مؤمن و مؤمنه بود و ایمانی راسخ داشت."],["I am a staunch supporter of linguistic purism.","من طرفدار سرسختِ خلوص زبانی هستم."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:stealthily','stealthily','adv','پنهانی','/ˈstel.θəl.i/ · silently','The black jaguar stealthily stalked its prey through the rainforest.','[["The black jaguar stealthily stalked its prey through the rainforest.","جگوار سیاه مخفیانه طعمه خود را در جنگل بارانی تعقیب می‌کرد."],["The black cat stealthily crept through the bushes.","گربه سیاه یواشکی از میان بوته‌ها گذشت."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:stipulate','stipulate','v','الزام آور کردن، قرار گذاشتن','/ˈstɪp.jə.leɪt/ · require','It is stipulated that we should receive a month''s vacation every year.','[["It is stipulated that we should receive a month''s vacation every year.","مقرر شده است که ما باید هر سال یک ماه مرخصی داشته باشیم."],["If you stipulate that these things are true, I will sign the contract.","اگر شرط کنید که این موارد درست هستند، من قرارداد را امضا خواهم کرد."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:stockpile','stockpile','v','ذخیره کردن','/ˈstɑːk.paɪl/ · store up','You should stockpile necessary supplies in case of a big earthquake.','[["You should stockpile necessary supplies in case of a big earthquake.","شما باید لوازم ضروری را برای مواقع زلزله بزرگ ذخیره کنید."],["Did you stockpile food and water?","آیا غذا و آب ذخیره کردید؟"]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:stylus','stylus','n','قلم','/ˈstaɪ.ləs/ · pen','Many devices with resistive touchscreens also include a stylus for more precise pointing.','[["Many devices with resistive touchscreens also include a stylus for more precise pointing.","بسیاری از دستگاه‌های دارای صفحه لمسی مقاومتی، برای اشاره دقیق‌تر، دارای قلم نیز هستند."],["Paul wrote hi with his stylus.","پاول با قلمش نوشت: «سلام»."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:substantiate','substantiate','v','با دلیل و مدرک اثبات کردن','/səbˈstæn.ʃi.eɪt/ · confirm','He could not substantiate his claims.','[["He could not substantiate his claims.","او نتوانست ادعای خود را ثابت کند."],["There is no evidence to substantiate the rumor.","هیچ مدرکی برای اثبات این شایعه وجود ندارد."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:successively','successively','adv','پی در پی','/səkˈses.ɪv.li/ · one after another','The company was successively owned by three different families.','[["The company was successively owned by three different families.","این شرکت به طور متوالی متعلق به سه خانواده مختلف بود."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sumptuous','sumptuous','adj','مجلل','/ˈsʌmp.tʃu.əs/ · luxurious','The sumptuous residence of a government official was pillaged.','[["The sumptuous residence of a government official was pillaged.","خانه مجلل یک مقام دولتی غارت شد."],["I''ve just watched a video on how to bake a sumptuous blueberry pie.","من همین الان یه ویدیو دیدم که چطور یه پای بلوبری خوشمزه بپزیم."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:supersede','supersede','v','جانشین شدن','/ˌsuː.pɚˈsiːd/ · replace','The new rules will supersede the old ones.','[["The new rules will supersede the old ones.","قوانین جدید جایگزین قوانین قبلی خواهند شد."],["Malians need to supersede their ethnic fault lines.","مردم مالی باید از خطوط گسل قومی خود فراتر روند."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:supplant','supplant','v','تعویض کردن، جایگزین کردن','/səˈplænt/ · replace, substitute','Will artificial intelligence supplant human intelligence?','[["Will artificial intelligence supplant human intelligence?","آیا هوش مصنوعی جای هوش انسانی را خواهد گرفت؟"],["Christianity''s main connection to Judaism throughout history has been its attempt to eradicate and supplant it.","ارتباط اصلی مسیحیت با یهودیت در طول تاریخ، تلاش برای ریشه کن کردن و جایگزینی آن بوده است."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:surmise','surmise','v','حدس زدن، گمان بردن','/sərˈmɑɪz/ · v) assume, guess, infer','Those are the main facts of the case, stripped of all surmise, and stated as baldly as possible.','[["Those are the main facts of the case, stripped of all surmise, and stated as baldly as possible.","اینها حقایق اصلی پرونده هستند، عاری از هرگونه حدس و گمان، و تا حد امکان صریح بیان شده‌اند."],["Females feed on squid in the mesopelagic zone, which is below 650 feet, it is surmised to avoid their predators.","ماده‌ها در منطقه مزوپلاژیک که زیر ۶۵۰ فوت است از ماهی مرکب تغذیه می‌کنند، گمان می‌رود که این کار برای جلوگیری از شکارچیان آنها باشد."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sustenance','sustenance','n','تغذیه','/ˈsʌs·tə·nəns/ · n) food, life, living','Giraffes rely on acacia leaves for sustenance.','[["Giraffes rely on acacia leaves for sustenance.","زرافه‌ها برای تغذیه به برگ‌های اقاقیا وابسته‌اند."],["It was a source of sustenance.","منبع رزق و روزی بود."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:symmetric','symmetric','adj','متناسب','/ˌeɪsɪˈmetrɪk/ · adj) balance','The relationship "A loves B" is not reflexive, transitive, or symmetric.','[["The relationship \"A loves B\" is not reflexive, transitive, or symmetric.","رابطه‌ی «الف، ب را دوست دارد» انعکاسی، متعدی یا متقارن نیست."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:tailspin','tailspin','n','گیجی و بیهوشی، سقوط','/ˈteɪlˌspɪn/ · total confusion, a sudden fall that cannot be controlled','The shenanigans on Wall Street have sent the economy into a tailspin.','[["The shenanigans on Wall Street have sent the economy into a tailspin.","جنجال‌های وال استریت، اقتصاد را به ورطه سقوط کشانده است."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:tantalizing','tantalizing','adj','وسوسه انگیزی','/ˈtæn·təlˌɑɪ·zɪŋ/ · tempting','Make those images of the dishes as tantalizing as possible.','[["Make those images of the dishes as tantalizing as possible.","تصاویر غذاها را تا حد امکان وسوسه‌انگیز کنید."],["Indian cuisine is a tantalizing mix of flavors and spices that tickle the taste buds.","غذاهای هندی ترکیبی وسوسه‌انگیز از طعم‌ها و ادویه‌هایی هستند که جوانه‌های چشایی را قلقلک می‌دهند."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:teem-with','teem with','phr','سرشار از','/timwɪð/ · be full of','The river is teeming with fish.','[["The river is teeming with fish.","رودخانه پر از ماهی است."],["My mind always teems with ideas.","ذهنم همیشه پر از ایده‌های جدید است."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:tenacity','tenacity','n','سر سختی','/təˈnæs.ə.ti/ · stability','With tenacity like that, you can learn any language.','[["With tenacity like that, you can learn any language.","با چنین پشتکاری، می‌توانید هر زبانی را یاد بگیرید."],["I got over the difficulty with my characteristic tenacity.","با سرسختیِ ذاتی‌ام بر این مشکل غلبه کردم."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:tenet','tenet','n','اصول، عقیده','/ˈten·ɪt/ · belief, principle','Bouteflika violated basic tenets of democracy to maintain power.','[["Bouteflika violated basic tenets of democracy to maintain power.","بوتفلیقه برای حفظ قدرت، اصول اولیه دموکراسی را نقض کرد."],["It is necessary for every person who stands for progress to criticise every tenet of old beliefs.","هر کسی که خواهان پیشرفت است، لازم است که تک تک اصول باورهای قدیمی را نقد کند."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:tenuous','tenuous','adj','نازک','/ˈten·ju·əs/ · weak','Relations are tenuous as peace talks resume between warring factions.','[["Relations are tenuous as peace talks resume between warring factions.","با از سرگیری مذاکرات صلح بین جناح‌های متخاصم، روابط شکننده است."],["Netanyahu''s grip on power is tenuous.","تسلط نتانیاهو بر قدرت شکننده است."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:timid','timid','adj','ترسو، بزدل','/ˈtɪm.ɪd/ · fearful','He timidly put up his hand.','[["He timidly put up his hand.","با ترس دستش را بالا آورد."],["She is timid like a rabbit.","او مثل یک خرگوش ترسو است."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:toil','toil','v','زحمت کشیدن، رنج بردن','/preposition]/ · work','I have nothing to offer but blood, toil, tears and sweat.','[["I have nothing to offer but blood, toil, tears and sweat.","من چیزی جز خون، رنج، اشک و عرق ندارم که تقدیم کنم."],["We offer everyone the opportunity to toil in the mines.","ما به همه فرصت کار در معادن را می‌دهیم."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:transitory','transitory','adj','فانی، ناپایدار','/træn.sə.tɔːr.i/ · short-lived, ephemeral, temporary, transient','The woman is the most perfect of creatures; she''s a transitory creature between man and angel.','[["The woman is the most perfect of creatures; she''s a transitory creature between man and angel.","زن کامل‌ترین مخلوقات است؛ او موجودی گذرا بین مرد و فرشته است."],["“Yes, I think I see it now,” he said after some time, brightening in a quite transitory manner.","بعد از مدتی، در حالی که به طرزی گذرا شادمان می‌شد، گفت: «بله، فکر کنم حالا می‌فهمم.»"]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:trappings','trappings','n','تجملات و تزئینات','/transfer/ · decorations','He enjoyed all the trappings of success, such as a big house and a fast car.','[["He enjoyed all the trappings of success, such as a big house and a fast car.","او از تمام مظاهر موفقیت، مانند خانه بزرگ و ماشین سریع، لذت می‌برد."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:unadorned','unadorned','adj','ساده، بی پیرایه','/ˌʌnəˈdɔːrnd/ · not decorative','It was a small, unadorned room.','[["It was a small, unadorned room.","اتاق کوچکی بود، بدون هیچ تزیینی."],["She left her hair unadorned.","موهایش را بدون آرایش رها کرد."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:unambiguous','unambiguous','adj','واضح','/ˌʌnæmˈbɪɡjuəs/ · clear','I''m asking you to say unambiguously yes or no.','[["I''m asking you to say unambiguously yes or no.","از شما می‌خواهم که بدون ابهام بله یا خیر بگویید."],["I admit this isn''t an unambiguous answer.","قبول دارم که این پاسخ قطعی و بدون ابهام نیست."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:unanimity','unanimity','n','اتفاق نظر، هم رای بودن','/ˌjuːnəˈnɪməti/ · total agreement','There was unanimity among the members on the new rules.','[["There was unanimity among the members on the new rules.","در مورد قوانین جدید، بین اعضا اتفاق نظر وجود داشت."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:unconsolidated','unconsolidated','adj','شل، سست','/ˌʌnkənˈsɒlɪdeɪtɪd/ · loose','The house was built on unconsolidated sand, so it was not stable.','[["The house was built on unconsolidated sand, so it was not stable.","خانه روی شن و ماسه‌ی نچسب ساخته شده بود، بنابراین پایدار نبود."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:underlie','underlie','v','بر اساس چیزی بودن، زمینه چیزی بودن','/ˌʌndərˈlaɪ/ · on the basis of','What do you think are the problems that underlie your obsession with martyrdom?','[["What do you think are the problems that underlie your obsession with martyrdom?","به نظر شما چه مشکلاتی زمینه‌ساز وسواس شما در مورد شهادت‌طلبی شده است؟"],["Who knows what disagreements underlie this agreement?","چه کسی می‌داند چه اختلافاتی پشت این توافق وجود دارد؟"]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:underpinning','underpinning','n','زیربنا','foundation, support','Trust is the underpinning of any good relationship.','[["Trust is the underpinning of any good relationship.","اعتماد، زیربنای هر رابطه‌ی خوبی است."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:underrate','underrate','v','دست کم گرفتن','/ˌʌndəˈreɪt/ · undervalue, underestimate','What''s the most underrated travel destination in your opinion?','[["What''s the most underrated travel destination in your opinion?","به نظر شما، دست کم گرفته شده‌ترین مقصد گردشگری کجاست؟"],["Onions rings are an underrated alternative to fries.","حلقه‌های پیاز جایگزین دست کم گرفته شده‌ای برای سیب‌زمینی سرخ کرده هستند."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:underscore','underscore','v','تاکید کردن','/ˌʌndərˈskɔːr/ · stress, emphasize','Why do you have so many underscores in your username?','[["Why do you have so many underscores in your username?","چرا اینقدر زیرخط (_) توی نام کاربریت داری؟"],["The president repeatedly spoke of security, underscoring the need for better intelligence.","رئیس جمهور بارها از امنیت صحبت کرد و بر لزوم بهبود اطلاعات تأکید ورزید."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:uniformly','uniformly','adv','به طور یکنواخت','/ˈjuːnəfɔːm/ · consistently, evenly','The paint should be spread uniformly over the wall.','[["The paint should be spread uniformly over the wall.","رنگ باید به طور یکنواخت روی دیوار پخش شود."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:unintendedly','unintendedly','adv','ناخواسته، بدون قصد','occasionally','The new rule unintendedly made the problem worse.','[["The new rule unintendedly made the problem worse.","قانون جدید ناخواسته مشکل را بدتر کرد."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:uninterrupted','uninterrupted','adj','بی وقفه، متداوم','/ˌʌnɪntəˈrʌptɪd/ · steady','Let''s set a timer for 30 minutes of uninterrupted homework time.','[["Let''s set a timer for 30 minutes of uninterrupted homework time.","بیایید یک تایمر برای 30 دقیقه زمان انجام تکالیف بدون وقفه تنظیم کنیم."],["Although I slept uninterrupted for 12 hours last night, I still feel pretty tired.","با اینکه دیشب دوازده ساعت کامل خوابیدم، هنوز خیلی خسته‌ام."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:unqualified','unqualified','adj','کامل، بی قید و شرط؛ فاقد صلاحیت','/ʌnˈkwɒlɪfaɪd/ · complete, not limited in any way; to the largest degree possible','This question can''t be answered with an unqualified yes or no.','[["This question can''t be answered with an unqualified yes or no.","به این سوال نمی‌توان با یک بله یا خیر قطعی پاسخ داد."],["My first task was to screen out unqualified applicants.","اولین وظیفه من حذف متقاضیان فاقد صلاحیت بود."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:unreceptive','unreceptive','adj','ناپذیرا، بی‌علاقه، بی‌توجه','/ʌnrɪˈseptɪv/ · unresponsive, undecided','Adriano was unreceptive to Rima’s concerns.','[["Adriano was unreceptive to Rima’s concerns.","آدریانو به نگرانی‌های ریما توجهی نکرد."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:unrestricted','unrestricted','adj','نا محدود','/ˌʌnrɪˈstrɪktɪd/ · unlimited','Congress wants to vote for broad, general and unrestricted impunity for its members.','[["Congress wants to vote for broad, general and unrestricted impunity for its members.","کنگره می‌خواهد به مصونیت گسترده، عمومی و نامحدود اعضای خود از مجازات رأی دهد."],["You will have unrestricted access to this area.","شما به این منطقه دسترسی نامحدود خواهید داشت."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:unsophisticated','unsophisticated','adj','ساده، غیر پیچیده','/ˌʌnsəˈfɪstɪkeɪtɪd/ · simple','I think that Tom is unsophisticated.','[["I think that Tom is unsophisticated.","من فکر می‌کنم تام ساده‌لوح است."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:unsuitable','unsuitable','adj','غیر مناسب','/ʌnˈsuːtəbəl/ · inappropriate','I think the translation of that word is unsuitable.','[["I think the translation of that word is unsuitable.","به نظرم ترجمه این کلمه مناسب نیست."],["The unsuitable way you dress calls attention to you.","لباس نامناسبی که می‌پوشید توجه دیگران را به شما جلب می‌کند."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:unsurpassed','unsurpassed','adj','بی نظیر','/ˌʌnsəˈpɑːst/ · superior','The quality of craftsmanship in this clock company is unsurpassed.','[["The quality of craftsmanship in this clock company is unsurpassed.","کیفیت ساخت ساعت‌های این شرکت بی‌نظیر است."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:unwieldy','unwieldy','adj','سنگین، غیرقابل حمل','/ʌnˈwiːldi/ · cumbersome','Two heaping handfuls of cheese made for a rather unwieldy quesadilla.','[["Two heaping handfuls of cheese made for a rather unwieldy quesadilla.","دو مشت پر پنیر، کسادیلای نسبتاً حجیمی درست کرد."],["The vacuum cleaner is a bit unwieldy.","جاروبرقی کمی سنگین است."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:urbane','urbane','adj','مودب','/ɜːˈbeɪn/ · behaving in a relaxed and confident way in social situations','He was an urbane and polite gentleman.','[["He was an urbane and polite gentleman.","او مردی متین و مؤدب و بافرهنگ بود."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:utilitarian','utilitarian','adj','کاربردی','/juːˌtɪləˈteəriən/ · functional, practical','The study of history offers to individuals major utilitarian learning outcomes.','[["The study of history offers to individuals major utilitarian learning outcomes.","مطالعه تاریخ، نتایج یادگیری سودمندگرایانه مهمی را برای افراد به ارمغان می‌آورد."],["Utilitarian philosophers have tried to justify some messed-up things.","فیلسوفان فایده‌گرا سعی کرده‌اند برخی از چیزهای آشفته را توجیه کنند."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:vagary','vagary','n','هوس، تغییر ناگهانی و غیرقابل پیش‌بینی','uncertainty','I''ve adapted to the vagaries of the weather.','[["I''ve adapted to the vagaries of the weather.","من با تغییرات ناگهانی آب و هوا سازگار شده‌ام."],["Coping with the vagaries of the weather is part and parcel of being a farmer.","کنار آمدن با تغییرات ناگهانی آب و هوا بخشی جدایی‌ناپذیر از کشاورزی است."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:vial','vial','n','شیشه کوچک دارو','/ˈvaɪəl/ · bottle','Add the contents of the vial to 200 milliliters of water.','[["Add the contents of the vial to 200 milliliters of water.","محتویات ویال را به 200 میلی لیتر آب اضافه کنید."],["Jekyll ran out of vials of his serum.","جکیل شیشه‌های سرمش تمام شد."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:vigor','vigor','n','قدرت، نیرومندی، نیرو، انرژی، توان','/ˈvɪɡər/ · energy','Puffing and panting we continued to run with renewed vigor.','[["Puffing and panting we continued to run with renewed vigor.","نفس زنان و با انرژی مضاعف به دویدن ادامه دادیم."],["The high percentage of oxygen makes people full of vim and vigor.","درصد بالای اکسیژن، افراد را سرشار از انرژی و نشاط می‌کند."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:wield','wield','v','به کاربردن، خوب استفاده کردن','/wēld/ · exert','Who will wield the power after the election?','[["Who will wield the power after the election?","چه کسی پس از انتخابات قدرت را در دست خواهد گرفت؟"],["The old man approached me wielding a scythe.","پیرمرد با داسی در دست به من نزدیک شد."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:yearning','yearning','n','اشتیاق، حسرت، آرزو','/ˈjɜːnɪŋ/ · longing','The yearning never got away.','[["The yearning never got away.","این حسرت هرگز از بین نرفت."],["Algerians are yearning for change.","الجزایری‌ها مشتاق تغییر هستند."]]','t1212',25,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
